const RUSH_FIELDS=[{"key":"aro","label":"芳香族","icon":"⌬","img":"../aromatic-quest/assets/memo/","decks":[{"name":"No.1 芳香族炭化水素(構造式)","items":[{"id":"d0-0","q":"名称を答えよ。","a":"トルエン","w":["𝑜&#8209;キシレン","フェノール","ナフタレン","ニトロベンゼン"],"e":"ベンゼン環にメチル基が1つついたトルエン（メチルベンゼン）。𝑜&#8209;キシレンはメチル基が2つ、フェノールは−OH、ニトロベンゼンは−NO₂、ナフタレンはベンゼン環が2つ、辺を共有してつながったもの。","img":"トルエン.jpg"},{"id":"d0-1","q":"名称を答えよ。","a":"𝑜&#8209;キシレン","w":["トルエン","フェノール","ナフタレン","ニトロベンゼン"],"e":"ベンゼン環にメチル基が2つ、隣どうし（オルト位）についた𝑜&#8209;キシレン。トルエンはメチル基が1つ、フェノールは−OH、ニトロベンゼンは−NO₂、ナフタレンはベンゼン環が2つ。","img":"oーキシレン.jpg"},{"id":"d0-2","q":"名称を答えよ。","a":"クロロベンゼン","w":["フェノール","トルエン","ニトロベンゼン","𝑜&#8209;キシレン"],"e":"ベンゼン環にClが1つついたクロロベンゼン（ベンゼンの塩素化で生成）。フェノールは−OH、ニトロベンゼンは−NO₂、トルエンはメチル基。","img":"クロロベンゼン.jpg"},{"id":"d0-3","q":"名称を答えよ。","a":"ナフタレン","w":["フェノール","トルエン","ニトロベンゼン","𝑜&#8209;キシレン"],"e":"ベンゼン環が2つ、辺を共有してつながったナフタレン（C₁₀H₈）。フェノール・トルエン・ニトロベンゼン・𝑜&#8209;キシレンはベンゼン環が1つ。","img":"ナフタレン.jpg"},{"id":"d0-4","q":"名称を答えよ。","a":"ニトロベンゼン","w":["アニリン","ベンゼンスルホン酸","フェノール","ピクリン酸"],"e":"ベンゼン環にニトロ基（−NO₂）が1つついたニトロベンゼン。アニリンは−NH₂、ベンゼンスルホン酸は−SO₃H、フェノールは−OH、ピクリン酸は−NO₂が3つと−OH。","img":"ニトロベンゼン.jpg"},{"id":"d0-5","q":"名称を答えよ。","a":"2,4,6-トリニトロトルエン","w":["トルエン","ピクリン酸","ベンゼンスルホン酸"],"e":"トルエンのメチル基に対してオルト位2か所とパラ位に−NO₂がついた2,4,6-トリニトロトルエン（TNT）。トルエンは−NO₂なし、ピクリン酸は−OH、ベンゼンスルホン酸は−SO₃H。","img":"2,4,6－トリニトロトルエン.jpg"},{"id":"d0-6","q":"名称を答えよ。","a":"フェノール","w":["トルエン","𝑜&#8209;キシレン","𝑜&#8209;クレゾール","安息香酸"],"e":"ベンゼン環に−OHが直接1つついたフェノール。𝑜&#8209;クレゾールは−OHの隣にメチル基もある、安息香酸は−COOH、トルエン・𝑜&#8209;キシレンは−OHがない。","img":"フェノール.jpg"},{"id":"d0-7","q":"名称を答えよ。","a":"ベンゼンスルホン酸","w":["ニトロベンゼン","アニリン","フェノール","安息香酸"],"e":"ベンゼン環にスルホ基（−SO₃H）がついたベンゼンスルホン酸。ニトロベンゼンは−NO₂、アニリンは−NH₂、フェノールは−OH、安息香酸は−COOH。","img":"ベンゼンスルホン酸.jpg"},{"id":"d0-8","q":"名称を答えよ。","a":"ベンゼンヘキサクロリド","w":["シクロヘキサン","クロロベンゼン","塩化ベンゼンジアゾニウム","ヘキサクロロベンゼン"],"e":"ベンゼンに光をあてて塩素を付加させた、環に二重結合がなく各炭素にClが1つずつついたベンゼンヘキサクロリド。ヘキサクロロベンゼンはベンゼン環のHが6つともClに置換したもの、クロロベンゼンはClが1つ、シクロヘキサンはClがない。","img":"ベンゼンヘキサクロリド.jpg"}]},{"name":"No.2 酸素を含む芳香族炭化水素(構造式)","items":[{"id":"d1-0","q":"名称を答えよ。","a":"フェノール","w":["トルエン","𝑜&#8209;キシレン","𝑜&#8209;クレゾール","ベンジルアルコール"],"e":"ベンゼン環に−OHが直接1つついたフェノール。ベンジルアルコールは−CH₂OH（ベンゼン環とOHの間にCH₂）、𝑜&#8209;クレゾールは−OHの隣にメチル基もある、トルエン・𝑜&#8209;キシレンは−OHがない。","img":"フェノール.jpg"},{"id":"d1-1","q":"名称を答えよ。","a":"𝑜&#8209;クレゾール","w":["トルエン","𝑜&#8209;キシレン","フェノール","ベンジルアルコール"],"e":"フェノールの−OHの隣（オルト位）にメチル基がついた𝑜&#8209;クレゾール。フェノールはメチル基がない、ベンジルアルコールは−CH₂OH、𝑜&#8209;キシレンはメチル基が2つ。","img":"oークレゾール.jpg"},{"id":"d1-2","q":"名称を答えよ。","a":"ベンジルアルコール","w":["ベンズアルデヒド","フェノール","𝑜&#8209;クレゾール","安息香酸"],"e":"ベンゼン環に−CH₂OHがついたベンジルアルコール（−OHは環に直接ついていないのでフェノール類ではない）。ベンズアルデヒドは−CHO、安息香酸は−COOH、フェノールは−OHが環に直接つく。","img":"ベンジルアルコール.jpg"},{"id":"d1-3","q":"名称を答えよ。","a":"ベンゼンスルホン酸","w":["ニトロベンゼン","アニリン","フェノール","安息香酸"],"e":"ベンゼン環にスルホ基（−SO₃H）がついたベンゼンスルホン酸。ニトロベンゼンは−NO₂、アニリンは−NH₂、フェノールは−OH、安息香酸は−COOH。","img":"ベンゼンスルホン酸.jpg"},{"id":"d1-4","q":"名称を答えよ。","a":"クメンヒドロペルオキシド","w":["ベンジルアルコール","フェノール","ベンゼンスルホン酸"],"e":"クメンのCH（ベンゼン環のつく炭素）に−O−OHがついたクメンヒドロペルオキシド（クメン法の中間体）。フェノールは環に−OH、ベンジルアルコールは−CH₂OH、ベンゼンスルホン酸は−SO₃H。","img":"クメンヒドロペルオキシド.jpg"},{"id":"d1-5","q":"名称を答えよ。","a":"サリチル酸","w":["安息香酸","ベンゼンスルホン酸","ピクリン酸","フタル酸"],"e":"ベンゼン環の隣どうし（オルト位）に−COOHと−OHがついたサリチル酸。安息香酸は−OHがない、フタル酸は−COOHが2つ、ピクリン酸は−OHと−NO₂が3つ、ベンゼンスルホン酸は−SO₃H。","img":"サリチル酸.jpg"},{"id":"d1-6","q":"名称を答えよ。","a":"ピクリン酸","w":["安息香酸","ベンゼンスルホン酸","2,4,6－トリニトロトルエン","フタル酸"],"e":"フェノールの2,4,6位（−OHに対してオルト位2か所とパラ位）に−NO₂がついたピクリン酸（2,4,6-トリニトロフェノール）。2,4,6-トリニトロトルエンはメチル基、安息香酸・フタル酸は−COOH。","img":"ピクリン酸.jpg"},{"id":"d1-7","q":"名称を答えよ。","a":"ナトリウムフェノキシド","w":["安息香酸ナトリウム","ナトリウムエトキシド","ベンゼンスルホン酸ナトリウム"],"e":"フェノールの−OHのHがNaに置き換わったナトリウムフェノキシド（C₆H₅ONa）。安息香酸ナトリウムは−COONa、ベンゼンスルホン酸ナトリウムは−SO₃Na、ナトリウムエトキシドはエチル基。","img":"ナトリウムフェノキシド.jpg"},{"id":"d1-8","q":"名称を答えよ。","a":"2,4,6－トリブロモフェノール","w":["2,4,6－トリニトロトルエン","ピクリン酸","2,4,6－トリニトロフェノール","2,4,6－トリブロモトルエン"],"e":"フェノールの2,4,6位にBrがついた2,4,6-トリブロモフェノール（フェノール＋臭素水の白色沈殿）。ピクリン酸（＝2,4,6-トリニトロフェノール）は−NO₂、2,4,6-トリブロモトルエンはメチル基。","img":"2,4,6－トリブロモフェノール.jpg"},{"id":"d1-9","q":"名称を答えよ。","a":"安息香酸","w":["サリチル酸","フタル酸","ピクリン酸","マレイン酸"],"e":"ベンゼン環に−COOHが1つついた安息香酸。サリチル酸は隣に−OHもある、フタル酸は−COOHが2つ、ピクリン酸は−OHと−NO₂、マレイン酸はベンゼン環のないジカルボン酸。","img":"安息香酸.jpg"},{"id":"d1-10","q":"名称を答えよ。","a":"フタル酸","w":["サリチル酸","安息香酸","ピクリン酸","フマル酸"],"e":"ベンゼン環の隣どうし（オルト位）に−COOHが2つついたフタル酸。テレフタル酸はパラ位、安息香酸は−COOHが1つ、サリチル酸は−COOHと−OH、フマル酸はベンゼン環がない。","img":"フタル酸.jpg"},{"id":"d1-11","q":"名称を答えよ。","a":"テレフタル酸","w":["フタル酸","安息香酸","サリチル酸","フマル酸"],"e":"ベンゼン環の向かい合う位置（パラ位）に−COOHが2つついたテレフタル酸（PETの原料）。フタル酸はオルト位、安息香酸は−COOHが1つ、サリチル酸は−COOHと−OH。","img":"テレフタル酸.jpg"},{"id":"d1-12","q":"名称を答えよ。","a":"無水フタル酸","w":["無水マレイン酸","無水酢酸","無水フマル酸","無水テレフタル酸"],"e":"フタル酸の隣どうしの−COOHから水がとれて環になった無水フタル酸。無水マレイン酸はベンゼン環がない。無水酢酸は鎖状。フマル酸・テレフタル酸は−COOHが離れているので分子内脱水できず、「無水フマル酸」「無水テレフタル酸」は存在しない。","img":"無水フタル酸.jpg"},{"id":"d1-13","q":"名称を答えよ。","a":"アセチルサリチル酸","w":["サリチル酸","サリチル酸メチル","アセチルサリチル酸メチル","アセトアニリド"],"e":"サリチル酸の−OHがアセチル化された（−OCOCH₃になった）アセチルサリチル酸（アスピリン）。サリチル酸は−OHのまま、サリチル酸メチルは−COOHが−COOCH₃、アセトアニリドはアニリンのアセチル化物。","img":"アセチルサリチル酸.jpg"},{"id":"d1-14","q":"名称を答えよ。","a":"サリチル酸メチル","w":["サリチル酸","アセチルサリチル酸","アセチルサリチル酸メチル","アセトアニリド"],"e":"サリチル酸の−COOHがメタノールとエステル化して−COOCH₃になったサリチル酸メチル（湿布のにおい）。アセチルサリチル酸は−OHの方がアセチル化される、サリチル酸は−COOHのまま。","img":"サリチル酸メチル.jpg"}]},{"name":"No.3 窒素を含む芳香族炭化水素(構造式)","items":[{"id":"d2-0","q":"名称を答えよ。","a":"アニリン","w":["アミリン","アミドベンゼン","アウストラロピテクス"],"e":"ベンゼン環にアミノ基（−NH₂）がついたアニリン。アミリン・アミドベンゼンはこの物質の名前ではない。アウストラロピテクスは猿人で化学物質ではない。","img":"アニリン.jpg"},{"id":"d2-1","q":"名称を答えよ。","a":"ニトロベンゼン","w":["トリニトロトルエン","フェノール","アミノベンゼン"],"e":"ベンゼン環にニトロ基（−NO₂）が1つついたニトロベンゼン。トリニトロトルエンはトルエンに−NO₂が3つ、フェノールは−OH、アミノベンゼン（アニリンの別名）は−NH₂。","img":"ニトロベンゼン.jpg"},{"id":"d2-2","q":"名称を答えよ。","a":"塩化ベンゼンジアゾニウム","w":["アニリン塩酸塩","アニリン","クロロアニリン","𝑝&#8209;フェニルアゾフェノール"],"e":"ベンゼン環に−N⁺≡N Cl⁻がついた塩化ベンゼンジアゾニウム（アニリンのジアゾ化で生成）。アニリン塩酸塩は−NH₃⁺Cl⁻、アニリンは−NH₂、クロロアニリンは環にClがついたアニリン。","img":"塩化ベンゼンジアゾニウム.jpg"},{"id":"d2-3","q":"名称を答えよ。","a":"アセトアニリド","w":["アセチルサリチル酸","酢酸フェニル","アセトアミノフェン","アニリン"],"e":"アニリンの−NH₂がアセチル化された（−NHCOCH₃）アセトアニリド。アセチルサリチル酸・酢酸フェニルは−O−でつながるエステル、アセトアミノフェンはアセトアニリドのパラ位に−OHがついたもの、アニリンは−NH₂のまま。","img":"アセトアニリド.jpg"},{"id":"d2-4","q":"名称を答えよ。","a":"𝑝&#8209;ヒドロキシアゾベンゼン","w":["𝑝&#8209;ヒドロキシアゾフェノール","𝑝&#8209;フェニルアゾベンゼン","𝑝&#8209;ベンジルアゾベンゼン","𝑝&#8209;フェニルアゾヒドロキシ"],"e":"ベンゼン環2つが−N=N−（アゾ基）でつながり、片方のパラ位に−OHがついた𝑝&#8209;ヒドロキシアゾベンゼン（＝𝑝&#8209;フェニルアゾフェノール）。他の選択肢は名前の組み合わせを変えたもので、この物質の名前ではない。","img":"p-ヒドロキシアゾベンゼン.jpg"},{"id":"d2-5","q":"名称を答えよ。","a":"𝑝&#8209;フェニルアゾフェノール","w":["𝑝&#8209;ヒドロキシアゾフェノール","𝑝&#8209;フェニルアゾベンゼン","𝑝&#8209;ベンジルアゾベンゼン","𝑝&#8209;フェニルアゾヒドロキシ"],"e":"フェノールのパラ位に−N=N−C₆H₅（フェニルアゾ基）がついた𝑝&#8209;フェニルアゾフェノール（＝𝑝&#8209;ヒドロキシアゾベンゼン）。他の選択肢は名前の組み合わせを変えたもので、この物質の名前ではない。","img":"p-フェニルアゾフェノール.jpg"},{"id":"d2-6","q":"名称を答えよ。","a":"アニリン塩酸塩","w":["塩化ベンゼンジアゾニウム","アニリン","アセトアニリド","塩化ジアゾベンゼン"],"e":"アニリンの−NH₂が塩酸で中和されて−NH₃⁺Cl⁻になったアニリン塩酸塩。塩化ベンゼンジアゾニウムは−N⁺≡N Cl⁻、アセトアニリドは−NHCOCH₃。「塩化ジアゾベンゼン」という物質名は使わない。","img":"アニリン塩酸塩.jpg"}]},{"name":"No.4 構造式マイナー","items":[{"id":"d3-0","q":"名称を答えよ","a":"アントラセン","w":["キシレン","ナフタレン","トルエン","トリベンゼン"],"e":"ベンゼン環が3つ横一列につながったアントラセン（C₁₄H₁₀）。ナフタレンはベンゼン環が2つ、トルエン・キシレンはベンゼン環が1つ。「トリベンゼン」という物質名はない。","img":"アントラセン.jpg"},{"id":"d3-1","q":"名称を答えよ","a":"1-ナフトール","w":["2-ナフトール","フェノール","キシレン","β-ナフトール"],"e":"ナフタレンの1位（環のつなぎ目の隣）に−OHがついた1-ナフトール（α-ナフトール）。2-ナフトール（β-ナフトール）は−OHが2位、フェノールはベンゼン環が1つ。","img":"1-ナフトール.jpg"},{"id":"d3-2","q":"名称を答えよ","a":"2-ナフトール","w":["1-ナフトール","キシレン","フェノール","α-ナフトール"],"e":"ナフタレンの2位に−OHがついた2-ナフトール（β-ナフトール）。1-ナフトール（α-ナフトール）は−OHが1位（環のつなぎ目の隣）、フェノールはベンゼン環が1つ。","img":"2-ナフトール.jpg"},{"id":"d3-3","q":"名称を答えよ","a":"𝑚&#8209;キシレン","w":["𝑚&#8209;クレゾール","トルエン","𝑜&#8209;キシレン","𝑝&#8209;キシレン"],"e":"ベンゼン環に2つのメチル基が1つおき（メタ位）についた𝑚&#8209;キシレン。𝑜&#8209;キシレンは隣どうし（オルト位）、𝑝&#8209;キシレンは向かい合う位置（パラ位）、𝑚&#8209;クレゾールは片方が−OH、トルエンはメチル基が1つ。","img":"m-キシレン.jpg"},{"id":"d3-4","q":"名称を答えよ。","a":"𝑝&#8209;キシレン","w":["𝑚&#8209;クレゾール","トルエン","𝑜&#8209;キシレン","𝑚&#8209;キシレン"],"e":"ベンゼン環に2つのメチル基が向かい合う位置（パラ位）についた𝑝&#8209;キシレン。𝑜&#8209;キシレンはオルト位、𝑚&#8209;キシレンはメタ位、𝑚&#8209;クレゾールは片方が−OH、トルエンはメチル基が1つ。","img":"p-キシレン.jpg"},{"id":"d3-5","q":"名称を答えよ。","a":"𝑚&#8209;クレゾール","w":["𝑜&#8209;クレゾール","𝑝&#8209;クレゾール","𝑜&#8209;キシレン","𝑚&#8209;キシレン"],"e":"フェノールの−OHに対してメタ位（1つおき）にメチル基がついた𝑚&#8209;クレゾール。𝑜&#8209;クレゾールはオルト位、𝑝&#8209;クレゾールはパラ位。𝑜&#8209;・𝑚&#8209;キシレンはメチル基が2つ。","img":"m-クレゾール.jpg"},{"id":"d3-6","q":"名称を答えよ。","a":"𝑜&#8209;クレゾール","w":["𝑚&#8209;クレゾール","𝑝&#8209;クレゾール","𝑜&#8209;キシレン","𝑚&#8209;キシレン"],"e":"フェノールの−OHの隣（オルト位）にメチル基がついた𝑜&#8209;クレゾール。𝑚&#8209;クレゾールはメタ位、𝑝&#8209;クレゾールはパラ位。𝑜&#8209;・𝑚&#8209;キシレンはメチル基が2つ。","img":"o-クレゾール.jpg"},{"id":"d3-7","q":"名称を答えよ。","a":"𝑝&#8209;クレゾール","w":["𝑜&#8209;クレゾール","𝑚&#8209;クレゾール","𝑜&#8209;キシレン","𝑚&#8209;キシレン"],"e":"フェノールの−OHに対して向かい合う位置（パラ位）にメチル基がついた𝑝&#8209;クレゾール。𝑜&#8209;クレゾールはオルト位、𝑚&#8209;クレゾールはメタ位。𝑜&#8209;・𝑚&#8209;キシレンはメチル基が2つ。","img":"p-クレゾール.jpg"},{"id":"d3-8","q":"名称を答えよ。","a":"𝑜&#8209;ニトロトルエン","w":["𝑝&#8209;ニトロトルエン","𝑜&#8209;ニトロフェノール","𝑝&#8209;ニトロフェノール","ピクリン酸"],"e":"トルエンのメチル基の隣（オルト位）に−NO₂がついた𝑜&#8209;ニトロトルエン。𝑝&#8209;ニトロトルエンはパラ位、ニトロフェノールは−OH、ピクリン酸は−OHと−NO₂が3つ。","img":"o-ニトロトルエン.jpg"},{"id":"d3-9","q":"名称を答えよ。","a":"𝑝&#8209;ニトロトルエン","w":["𝑜&#8209;ニトロトルエン","𝑜&#8209;ニトロフェノール","𝑝&#8209;ニトロフェノール","ピクリン酸"],"e":"トルエンのメチル基に対して向かい合う位置（パラ位）に−NO₂がついた𝑝&#8209;ニトロトルエン。𝑜&#8209;ニトロトルエンはオルト位、ニトロフェノールは−OH。","img":"p-ニトロトルエン.jpg"},{"id":"d3-10","q":"名称を答えよ。","a":"𝑜&#8209;ニトロフェノール","w":["𝑜&#8209;ニトロトルエン","𝑝&#8209;ニトロトルエン","𝑝&#8209;ニトロフェノール","ピクリン酸"],"e":"フェノールの−OHの隣（オルト位）に−NO₂がついた𝑜&#8209;ニトロフェノール。𝑝&#8209;ニトロフェノールはパラ位、ニトロトルエンはメチル基、ピクリン酸は−NO₂が3つ。","img":"o-ニトロフェノール.jpg"},{"id":"d3-11","q":"名称を答えよ。","a":"𝑝&#8209;ニトロフェノール","w":["𝑜&#8209;ニトロトルエン","𝑝&#8209;ニトロトルエン","𝑜&#8209;ニトロフェノール","ピクリン酸"],"e":"フェノールの−OHに対して向かい合う位置（パラ位）に−NO₂がついた𝑝&#8209;ニトロフェノール。𝑜&#8209;ニトロフェノールはオルト位、ニトロトルエンはメチル基、ピクリン酸は−NO₂が3つ。","img":"p-ニトロフェノール.jpg"}]},{"name":"No.5 芳香族炭化水素(基礎)","items":[{"id":"d4-0","q":"ベンゼンの原子は","a":"全て同一平面上に配列","w":["炭素のみ同一平面上に配列","立体的に配列"],"e":"ベンゼンは正六角形の平面構造で、炭素だけでなく、環に結合するHも含めてすべての原子が同一平面上にある。"},{"id":"d4-1","q":"ベンゼンの炭素原子の結合の長さは、通常の炭素間の単結合より(ア)、二重結合より(イ)。","a":"ア：短く　イ：長い","w":["ア：長く　イ：短い"],"e":"ベンゼン環の結合は単結合と二重結合の中間（1.5重くらい）なので、単結合より短く、二重結合より長い。"},{"id":"d4-2","q":"ベンゼンは水と","a":"混ざらない","w":["任意の割合で混和"],"e":"ベンゼンは無極性で水と混ざらない（水より軽い）。有機物やヨウ素などの無極性分子をよく溶かす。"},{"id":"d4-3","q":"ベンゼン環を持つ化合物を一般に何というか。","a":"芳香族炭化水素","w":["脂肪族炭化水素"],"e":"ベンゼン環をもつ化合物を芳香族化合物（炭化水素なら芳香族炭化水素）という。脂肪族はベンゼン環をもたない鎖式などの化合物。"},{"id":"d4-4","q":"鉄粉を触媒にして、ベンゼンと塩素を反応させると一置換の化合物が生じた。この物質の名称を答えよ。","a":"クロロベンゼン","w":["ベンゼンヘキサクロリド","𝑝&#8209;ジクロロベンゼン","塩化ビニル","塩化ベンゼンジアゾニウム"],"e":"鉄粉（FeCl₃）触媒ではベンゼン環のHがClに1つ置換してクロロベンゼンができる。ベンゼンヘキサクロリドは光で付加したもの、𝑝&#8209;ジクロロベンゼンはClが2つ、塩化ビニルはベンゼン環がない、塩化ベンゼンジアゾニウムはアニリンのジアゾ化でできる。"},{"id":"d4-5","q":"ベンゼンに濃硫酸を加えて加熱すると生じる強酸性の物質の名称を答えよ。","a":"ベンゼンスルホン酸","w":["安息香酸","ニトロベンゼン","フタル酸","サリチル酸"],"e":"濃硫酸でスルホン化が起こり、強酸のベンゼンスルホン酸ができる。安息香酸・フタル酸・サリチル酸は−COOHをもつ物質で、濃硫酸だけではできない。ニトロベンゼンは混酸でできる。"},{"id":"d4-6","q":"ベンゼンに濃硝酸と濃硫酸の混合物を反応させると生じる、特有の臭気のある黄色い液体の名称を答えよ。","a":"ニトロベンゼン","w":["ヨードホルム","トリニトロトルエン","フェノール","ピクリン酸"],"e":"混酸（濃硝酸＋濃硫酸）でニトロ化が起こり、ニトロベンゼン（特有のにおいの淡黄色の液体）ができる。トリニトロトルエンはトルエン、ピクリン酸はフェノールのニトロ化でできる。ヨードホルムはヨードホルム反応の黄色の固体。"},{"id":"d4-7","q":"ベンゼンの水素原子1個をメチル基で置換すると生じる物質の名称を答えよ。","a":"トルエン","w":["キシレン","エチルベンゼン","クレゾール","フェノール"],"e":"ベンゼンのHを1つメチル基にするとトルエン。2つならキシレン、エチル基ならエチルベンゼン。クレゾール・フェノールは−OHをもつ。"},{"id":"d4-8","q":"ベンゼンの水素原子2個をメチル基で置換すると生じる物質の名称を答えよ。","a":"キシレン","w":["トルエン","フェノール","クレゾール","エチルベンゼン"],"e":"ベンゼンのHを2つメチル基にするとキシレン（𝑜&#8209;・𝑚&#8209;・𝑝&#8209;の3種類）。1つならトルエン。エチルベンゼンはエチル基が1つ（キシレンと異性体）。"},{"id":"d4-9","q":"ベンゼン環に置換基が2つあると、何種類の異性体が存在するか。","a":"3","w":["1","2","4","6"],"e":"置換基が2つだと、隣どうし（オルト）・1つおき（メタ）・向かい合う（パラ）の3種類。"},{"id":"d4-10","q":"ナフタレンの分子式を示せ。","a":"C10H8","w":["C12H12","C8H10","C6H6","C14H10"],"e":"ナフタレンはベンゼン環が2つ辺を共有したものでC₁₀H₈。C₆H₆はベンゼン、C₈H₁₀はキシレンなど、C₁₄H₁₀はアントラセン。"},{"id":"d4-11","q":"ベンゼンに関する次の(ア)～(オ)の記述のうち、誤りを\n含むものを1つ選べ。","a":"(イ)　分子の各原子のうち、炭素原子のみが同一平面上にある。","w":["(ア)　組成式はCHである。","(オ)　空気中で多くのすすを出して燃える。","(ウ)　結合している炭素原子間の距離はすべて等しい。","(エ)　水と混ざりにくいが、種々の有機物を溶かす。"],"e":"ベンゼンは炭素だけでなく、Hも含めすべての原子が同一平面上にあるので(イ)が誤り。組成式CH、炭素間距離がすべて等しい、有機物を溶かす、すすを出して燃えるはすべて正しい。"},{"id":"d4-12","q":"ベンゼン分子の不飽和結合は、(ア)やアルケンの\n不飽和結合と違って、(イ)反応を起こしにくい。","a":"ア：アルキン　イ：付加","w":["ア：アルキン　イ：置換","ア：アルカン　イ：付加","ア：アルカン　イ：置換"],"e":"ベンゼン環は安定なので、アルキンやアルケンと違って付加反応を起こしにくく、置換反応を起こしやすい。アルカンはもともと不飽和結合をもたない。"},{"id":"d4-13","q":"鉄を触媒として、ベンゼンに臭素を作用させると、ベンゼンの(ア)原子が、(イ)原子に置き換わる。","a":"ア：水素　イ：臭素","w":["ア：炭素　イ：臭素","ア：水素　イ：炭素","ア：水素　イ：鉄","ア：炭素　イ：鉄"],"e":"置換反応では、ベンゼン環に直接ついているHが他の原子（ここではBr）に置き換わる。環の炭素が置き換わるわけではない。鉄は触媒で、環にはつかない。"},{"id":"d4-14","q":"ベンゼンに触媒存在下水素を反応させると何が得られるか。","a":"シクロヘキサン","w":["トルエン","ナフタレン","フェノール"],"e":"Ni・Ptなどの触媒で高温・高圧にするとH₂が3分子付加して、シクロヘキサンC₆H₁₂になる。トルエン・ナフタレン・フェノールはH₂の付加ではできない。"},{"id":"d4-15","q":"ベンゼンに鉄触媒存在下塩素を反応させると何が得られるか。","a":"クロロベンゼン","w":["塩化ベンゼンジアゾニウム","𝑝&#8209;ジクロロベンゼン","ベンゼンヘキサクロリド"],"e":"鉄（FeCl₃）触媒では置換反応が起こり、クロロベンゼンができる。光照射なら付加反応でベンゼンヘキサクロリド。𝑝&#8209;ジクロロベンゼンはClが2つ、塩化ベンゼンジアゾニウムはアニリンから。"},{"id":"d4-16","q":"ベンゼンに光照射のもと塩素を反応させると何が得られるか。","a":"ベンゼンヘキサクロリド","w":["クロロベンゼン","塩化ベンゼンジアゾニウム","𝑝&#8209;ジクロロベンゼン"],"e":"光照射ではCl₂が3分子付加して、ベンゼンヘキサクロリドができる。鉄触媒なら置換反応でクロロベンゼン。"}]},{"name":"No.6 酸素を含む芳香族(基礎)","items":[{"id":"d5-0","q":"ベンゼン環にヒドロキシ基―OHが直接結合した構造の化合物を何というか。","a":"フェノール","w":["安息香酸","トルエン","ニトロベンゼン","𝑝&#8209;ヒドロキシアゾベンゼン"],"e":"ベンゼン環に−OHが直接ついたものがフェノール（類）。安息香酸は−COOH、ニトロベンゼンは−NO₂、トルエンはメチル基。𝑝&#8209;ヒドロキシアゾベンゼンも−OHをもつが、アゾ基がついたアゾ化合物。"},{"id":"d5-1","q":"フェノールは何性を示すか","a":"弱酸性","w":["中性","弱塩基性"],"e":"フェノールの−OHはわずかに電離して、炭酸より弱い酸性を示す。アルコールの−OHは中性。"},{"id":"d5-2","q":"フェノールは水酸化ナトリウムなどの強塩基と反応して何という物質を生成するか","a":"ナトリウムフェノキシド","w":["安息香酸ナトリウム","サリチル酸ナトリウム","ナトリウムエトキシド"],"e":"フェノールは弱酸なのでNaOHと中和して、塩のナトリウムフェノキシドC₆H₅ONaになる。安息香酸ナトリウム・サリチル酸ナトリウムは−COOHをもつ酸から、ナトリウムエトキシドはエタノールから。"},{"id":"d5-3","q":"ナトリウムフェノキシドの水溶液に、二酸化炭素を通じると、何が生じるか","a":"フェノール","w":["安息香酸","サリチル酸ナトリウム","サリチル酸","トルエン"],"e":"炭酸はフェノールより強い酸なので、弱酸のフェノールが遊離する（C₆H₅ONa＋H₂O＋CO₂→C₆H₅OH＋NaHCO₃）。高温・高圧でCO₂を反応させるとサリチル酸ナトリウムになる。"},{"id":"d5-4","q":"フェノール類は、塩化鉄(Ⅲ)水溶液FeCl3aqを加えると","a":"呈色する","w":["気体が発生する","沈殿が生じる","何も起こらない"],"e":"フェノール類はFeCl₃水溶液で青紫〜赤紫色に呈色する（フェノール類の検出）。気体や沈殿は生じない。"},{"id":"d5-5","q":"ベンゼン環にカルボキシ基―COOHが直接結合した構造の化合物を何というか。","a":"芳香族カルボン酸","w":["フェノール類","芳香族アミン","ベンゼンスルホン酸"],"e":"ベンゼン環に−COOHが直接ついたものが芳香族カルボン酸（例：安息香酸）。フェノール類は−OH、芳香族アミンは−NH₂、ベンゼンスルホン酸は−SO₃H。"},{"id":"d5-6","q":"サリチル酸はベンゼン環に、何基と何基が結合しているか。","a":"ヒドロキシ基とカルボキシ基","w":["ヒドロキシ基とアルデヒド基","カルボキシ基とアルデヒド基","ヒドロキシ基とアセチル基"],"e":"サリチル酸はベンゼン環の隣どうし（オルト位）に−OHと−COOHをもつ。そのためフェノール類とカルボン酸の両方の性質を示す。"},{"id":"d5-7","q":"トルエンやエチルベンゼンを過マンガン酸カリウムで酸化して得られる物質の名称を答えよ。","a":"安息香酸","w":["フェノール類","キシレン","ベンズアルデヒド","ベンジルアルコール"],"e":"KMnO₄で酸化すると、側鎖の炭素数に関わらずベンゼン環に直接ついた炭素が−COOHになり、安息香酸ができる。ベンズアルデヒド・ベンジルアルコールは途中段階の物質で、ここではできない。"},{"id":"d5-8","q":"次のうち、安息香酸と反応しないものはどれか。","a":"塩化鉄(Ⅲ)","w":["ナトリウム","炭酸水素ナトリウム","水酸化ナトリウム"],"e":"安息香酸はカルボン酸なので、Na・NaHCO₃・NaOHとは反応する。ベンゼン環に直接ついた−OH（フェノール性）をもたないので、塩化鉄(Ⅲ)では呈色しない。"},{"id":"d5-9","q":"𝑝&#8209;キシレンを過マンガン酸カリウムで酸化して得られる物質の名称を答えよ。","a":"テレフタル酸","w":["フマル酸","マレイン酸","フタル酸"],"e":"𝑝&#8209;キシレンを酸化すると、パラ位の2つのメチル基が−COOHになりテレフタル酸ができる。𝑜&#8209;キシレンならフタル酸。フマル酸・マレイン酸はベンゼン環をもたない。"},{"id":"d5-10","q":"𝑜&#8209;キシレンを過マンガン酸カリウムで酸化して得られる物質を、さらに加熱したときに得られる物質の名称を答えよ。","a":"無水フタル酸","w":["無水マレイン酸","無水フマル酸","無水酢酸"],"e":"𝑜&#8209;キシレンを酸化するとフタル酸になり、加熱すると隣どうしの−COOHから水がとれて無水フタル酸になる。無水マレイン酸はベンゼン環がない。「無水フマル酸」は存在しない。"},{"id":"d5-11","q":"シップのにおいがするのは","a":"サリチル酸メチル","w":["アセチルサリチル酸","フェノール","酢酸エチル","サリチル酸"],"e":"サリチル酸メチルは湿布のにおいのする消炎鎮痛剤。アセチルサリチル酸は解熱鎮痛剤（アスピリン）、酢酸エチルは果実臭。"},{"id":"d5-12","q":"ベンゼンの酸化開裂では何が得られるか。","a":"無水マレイン酸","w":["無水フタル酸","無水酢酸","安息香酸"],"e":"ベンゼンをV₂O₅触媒で酸化開裂すると、無水マレイン酸ができる。ナフタレンなら無水フタル酸。安息香酸はトルエンなどの側鎖の酸化でできる。"},{"id":"d5-13","q":"ナフタレンの酸化開裂では何が得られるか。","a":"無水フタル酸","w":["無水マレイン酸","無水酢酸","安息香酸"],"e":"ナフタレンをV₂O₅触媒で酸化開裂すると、片方の環が開いて無水フタル酸ができる。ベンゼンなら無水マレイン酸。"},{"id":"d5-14","q":"クメンヒドロペルオキシドは何の合成の際に生成するか。","a":"フェノール","w":["安息香酸","サリチル酸","ベンズアルデヒド"],"e":"クメン法：ベンゼン→クメン→クメンヒドロペルオキシド→フェノール＋アセトン。安息香酸・サリチル酸・ベンズアルデヒドの合成では出てこない。"},{"id":"d5-15","q":"塩化鉄(Ⅲ)と反応しないのはどれか。","a":"アセチルサリチル酸","w":["サリチル酸","フェノール","クレゾール","サリチル酸メチル"],"e":"アセチルサリチル酸は−OHがアセチル化されていて、フェノール性の−OHをもたないので呈色しない。サリチル酸・サリチル酸メチル・フェノール・クレゾールは環に−OHをもつので呈色する。"}]},{"name":"No.7 酸素を含む芳香族(基礎その2)","items":[{"id":"d6-0","q":"エタノールに当てはまり，フェノールには当てはまらない記述を1つ選べ。","a":"酸化するとアルデヒドが生じる","w":["水酸化ナトリウム水溶液に溶ける","酸性を示す","エステルをつくる","塩化鉄(III)によって呈色反応を示す。"],"e":"エタノールは1級アルコールなので酸化するとアセトアルデヒドになる。フェノールの−OHは環に直接ついているので、酸化してもアルデヒドにならない。NaOH水溶液に溶ける・酸性・FeCl₃で呈色はフェノールの性質、エステルをつくるのは両方。"},{"id":"d6-1","q":"ベンゼンとプロペン(プロピレン)の付加反応により生じる( ア )を酸化したのちに硫酸で分解すると，(イ )とともにフェノールが生じる。","a":"ア：クメン　イ：アセトン","w":["ア：トルエン　イ：アセトン","ア：プロピルベンゼン　イ：アセトアルデヒド","ア：クメン　イ：アセトアルデヒド","ア：クロロベンゼン　イ：食塩"],"e":"ベンゼンにプロペンを付加させるとクメン、それを酸化・分解するとフェノールとアセトンができる（クメン法）。アセトアルデヒドはできない。トルエン・クロロベンゼンは別の物質。"},{"id":"d6-2","q":"ベンゼンを濃硫酸と反応させて生じる( ア )を中和したのち，水酸化ナトリウムと融解すると(イ)が生じる。これを酸性にすることによっても，フェノールは得られる。","a":"ア：ベンゼンスルホン酸　イ：ナトリウムフェノキシド","w":["ア：ベンゼンスルホン酸　イ：ベンゼンスルホン酸ナトリウム","ア：ベンゼンスルホン酸ナトリウム　イ：ナトリウムフェノキシド","ア：ベンゼンスルホン酸　イ：クメン"],"e":"ベンゼン→ベンゼンスルホン酸→（中和）ベンゼンスルホン酸ナトリウム→（NaOHでアルカリ融解）ナトリウムフェノキシド→（酸）フェノール。濃硫酸との反応で直接できるのは酸のベンゼンスルホン酸。"},{"id":"d6-3","q":"フェノールはベンゼン環に( ア )基がついた構造で、弱い( イ )を示す。","a":"ア：ヒドロキシ基　　イ：酸性","w":["ア：ヒドロキシ基　　イ：塩基性","ア：カルボキシ基　　イ：酸性","ア：カルボキシ基　　イ：塩基性"],"e":"フェノールはベンゼン環にヒドロキシ基（−OH）がついた弱い酸。カルボキシ基をもつのは安息香酸などのカルボン酸。"},{"id":"d6-4","q":"ナトリウムフェノキシドの水溶液に二酸化炭素を吹き込むと，炭酸はフェノールよりも( ア)い酸のため，( イ )が遊離する。","a":"ア：強　　イ：フェノール","w":["ア：弱　　イ：フェノール","ア：強　　イ：サリチル酸","ア：弱　　イ：サリチル酸"],"e":"炭酸はフェノールより強い酸なので、弱い酸のフェノールが追い出される（弱酸の遊離）。サリチル酸ができるのは高温・高圧でCO₂を反応させたとき。"},{"id":"d6-5","q":"ナトリウムフェノキシドを融解して高圧で二酸化炭素を反応させると(ア)が生じ、これを酸性にすると、(イ)が生じる","a":"ア：サリチル酸ナトリウム　　イ：サリチル酸","w":["ア：フェノール　　イ：サリチル酸","ア：サリチル酸　　イ：アセチルサリチル酸","ア：サリチル酸　　イ：サリチル酸メチル","ア：ベンゼンスルホン酸ナトリウム　イ：ベンゼンスルホン酸"],"e":"高温・高圧でCO₂を反応させるとサリチル酸ナトリウムになり、酸を加えると弱酸の遊離でサリチル酸ができる（コルベ・シュミット反応）。アセチルサリチル酸・サリチル酸メチルはその後の反応でできる。"},{"id":"d6-6","q":"フェノールはベンゼンより( ア)反応を受けやすい。臭素を加えると(イ)反応により白色沈殿が生じる。","a":"ア：置換　　イ：置換","w":["ア：付加　　イ：置換","ア：置換　　イ：付加","ア：付加　　イ：付加"],"e":"フェノールの−OHがベンゼン環を反応しやすくするので、ベンゼンより置換反応を受けやすい。臭素水でもHがBrに置換されて2,4,6-トリブロモフェノールの白色沈殿ができる（付加ではない）。"},{"id":"d6-7","q":"サリチル酸は、メタノールと少量の濃硫酸と熱すると( ア )を生じ，無水酢酸と少量の濃硫酸との反応で( イ )を生じる。","a":"ア：サリチル酸メチル　イ：アセチルサリチル酸","w":["ア：サリチル酸メチル　イ：アセチルサリチル酸メチル","ア：アセチルサリチル酸メチル　イ：アセチルサリチル酸","ア：アセチルサリチル酸　イ：サリチル酸メチル"],"e":"メタノールとは−COOHがエステル化してサリチル酸メチル、無水酢酸とは−OHがアセチル化されてアセチルサリチル酸ができる。両方が同時に起こるわけではない。"},{"id":"d6-8","q":"サリチル酸メチルは","a":"消炎鎮痛剤","w":["解熱鎮痛剤","消炎鎮痛済","解熱鎮痛済"],"e":"サリチル酸メチルは消炎鎮痛剤（湿布）。解熱鎮痛剤はアセチルサリチル酸。「〜済」は「剤」の誤りで、そういう語はない。"},{"id":"d6-9","q":"アセチルサリチル酸は","a":"解熱鎮痛剤","w":["消炎鎮痛剤","消炎鎮痛済","解熱鎮痛済"],"e":"アセチルサリチル酸は解熱鎮痛剤（アスピリン）。消炎鎮痛剤はサリチル酸メチル。「〜済」は「剤」の誤りで、そういう語はない。"}]},{"name":"No.8 窒素を含む芳香族(基礎)","items":[{"id":"d7-0","q":"ベンゼン環にアミノ基―NH2が直接結合した構造の化合物を何というか。","a":"アニリン","w":["ニトロベンゼン","トルエン","アセトアニリド","𝑝&#8209;ヒドロキシアゾベンゼン"],"e":"ベンゼン環にアミノ基（−NH₂）が直接ついたものがアニリン（芳香族アミン）。ニトロベンゼンは−NO₂、アセトアニリドは−NHCOCH₃、トルエンはメチル基。"},{"id":"d7-1","q":"アニリンは何性を示すか","a":"弱塩基性","w":["中性","弱酸性"],"e":"アニリンのアミノ基はアンモニアと同じようにH⁺を受け取るので、弱い塩基性を示す。塩酸に溶けてアニリン塩酸塩になる。"},{"id":"d7-2","q":"ベンゼンに何を加えるとニトロベンゼンが得られるか。","a":"硝酸と硫酸","w":["塩酸と硝酸","塩酸と硫酸","亜硝酸ナトリウムと塩酸"],"e":"混酸（濃硝酸＋濃硫酸）でニトロ化してニトロベンゼンができる。亜硝酸ナトリウムと塩酸はジアゾ化に使う。塩酸ではニトロ基は入らない。"},{"id":"d7-3","q":"ニトロベンゼンをスズと塩酸で還元し、水酸化ナトリウム水溶液を加えると何が生成するか。","a":"アニリン","w":["アセトアニリド","𝑝&#8209;ヒドロキシアゾベンゼン","ナトリウムフェノキシド","アニリン塩酸塩"],"e":"スズと塩酸で還元するとアニリン塩酸塩になり、NaOHで弱塩基のアニリンが遊離する。アニリン塩酸塩はNaOHを加える前の段階。"},{"id":"d7-4","q":"アニリンは常温で","a":"液体","w":["固体","気体"],"e":"アニリンは常温で無色の液体（空気中で酸化されて黒ずむ）。"},{"id":"d7-5","q":"アニリンはベンゼン環に何基が直接結合しているか。","a":"アミノ基","w":["ヒドロキシ基","アルデヒド基","カルボキシ基","アセチル基"],"e":"アニリンはベンゼン環にアミノ基（−NH₂）が直接ついたもの。ヒドロキシ基ならフェノール、カルボキシ基なら安息香酸、アルデヒド基ならベンズアルデヒド。"},{"id":"d7-6","q":"アニリンに亜硝酸ナトリウムと塩酸を加えると、何が生成するか。","a":"塩化ベンゼンジアゾニウム","w":["𝑝&#8209;ヒドロキシアゾベンゼン","アニリン塩酸塩","フェノール","ニトロベンゼン"],"e":"5℃以下で亜硝酸ナトリウムと塩酸を加えるとジアゾ化が起こり、塩化ベンゼンジアゾニウムができる。アニリン塩酸塩は塩酸だけのとき、𝑝&#8209;ヒドロキシアゾベンゼンはさらにカップリングしたとき。"},{"id":"d7-7","q":"塩化ベンゼンジアゾニウムにナトリウムフェノキシドを加えると、何が生成するか。","a":"𝑝&#8209;ヒドロキシアゾベンゼン","w":["アニリン塩酸塩","フェノール","ニトロベンゼン","アセトアニリド"],"e":"ジアゾカップリングで、橙赤色の𝑝&#8209;ヒドロキシアゾベンゼン（𝑝&#8209;フェニルアゾフェノール）ができる。フェノールは塩化ベンゼンジアゾニウムを温めて分解したときにできる。"},{"id":"d7-8","q":"塩化ベンゼンジアゾニウムを水溶液中で昇温すると、何が生成するか。","a":"フェノール","w":["𝑝&#8209;ヒドロキシアゾベンゼン","アニリン","水素","酸素"],"e":"塩化ベンゼンジアゾニウムは不安定で、温めると分解してフェノールとN₂になる。だからジアゾ化は5℃以下で行う。"},{"id":"d7-9","q":"塩化ベンゼンジアゾニウムが分解すると、何が生成するか。","a":"窒素","w":["水素","酸素","𝑝&#8209;ヒドロキシアゾベンゼン","アニリン"],"e":"分解すると−N₂⁺がN₂として抜け、フェノールが残る（C₆H₅N₂Cl＋H₂O→C₆H₅OH＋N₂＋HCl）。H₂やO₂は出ない。"},{"id":"d7-10","q":"アニリンに無水酢酸を反応させると何が得られるか。","a":"アセトアニリド","w":["𝑝&#8209;ヒドロキシアゾベンゼン","アニリン塩酸塩","塩化ベンゼンジアゾニウム","ニトロベンゼン"],"e":"無水酢酸で−NH₂がアセチル化（アミド化）され、アセトアニリド（−NHCOCH₃）ができる。塩化ベンゼンジアゾニウムは亜硝酸ナトリウムと塩酸、アニリン塩酸塩は塩酸のとき。"},{"id":"d7-11","q":"アニリンに何を加えると、塩化ベンゼンジアゾニウムが生成するか。","a":"亜硝酸ナトリウムと塩酸","w":["硝酸と硫酸","硝酸と塩酸","塩酸と硫酸","さらし粉"],"e":"亜硝酸ナトリウムNaNO₂と塩酸を5℃以下で加えるとジアゾ化が起こる。硝酸と硫酸はニトロ化、さらし粉はアニリンの検出（赤紫色）。"},{"id":"d7-12","q":"ニトロベンゼンを何で還元するとアニリンが出来るか。","a":"スズと塩酸","w":["亜硝酸ナトリウムと塩酸","硝酸と硫酸","さらし粉"],"e":"ニトロベンゼンはスズと塩酸で還元してアニリンにする。亜硝酸ナトリウムと塩酸はジアゾ化、硝酸と硫酸はニトロ化。さらし粉は酸化剤で、還元には使わない。"},{"id":"d7-13","q":"アニリンに、硫酸酸性のニクロム酸カリウムを反応させると何が生成するか。","a":"アニリンブラック","w":["アニリンブルー","アニリンイエロー","アニリングリーン","アニリンレッド"],"e":"アニリンは硫酸酸性のK₂Cr₂O₇で高度に酸化され、黒色のアニリンブラックになる。他の色の名前の物質はこの反応ではできない。"}]},{"name":"No.9 反応の逆算","items":[{"id":"d8-0","q":"次のうち、フェノールと反応し、ナトリウムフェノキシドが生成しないものはどれか。","a":"炭酸水素ナトリウム","w":["水酸化ナトリウム","金属ナトリウム"],"e":"フェノールは炭酸より弱い酸なので、NaHCO₃とは反応しない。NaOHとは中和、金属Naとは反応してH₂を出し、どちらもナトリウムフェノキシドになる。"},{"id":"d8-1","q":"次のうち、酸素で酸化し、その後硫酸で分解するとフェノールが得られる物質はどれか。","a":"クメン","w":["クロロベンゼン","クメンヒドロペルオキシド","ベンゼンスルホン酸ナトリウム","トルエン"],"e":"クメンを酸化するとクメンヒドロペルオキシドになり、それを硫酸で分解するとフェノールが得られる。クメンヒドロペルオキシドは酸化後の物質なので、分解だけでよい。"},{"id":"d8-2","q":"次のうち、アルカリ融解の過程で出てくる物質はどれか","a":"ベンゼンスルホン酸ナトリウム","w":["クロロベンゼン","クメンヒドロペルオキシド","クメン","トルエン"],"e":"アルカリ融解はベンゼンスルホン酸ナトリウムを固体のNaOHと融解して、ナトリウムフェノキシドにする方法。クロロベンゼンは加水分解法、クメン・クメンヒドロペルオキシドはクメン法の物質。"},{"id":"d8-3","q":"次のうち、ピクリン酸の合成に用いる物質はどれか","a":"フェノール","w":["トルエン","キシレン","クレゾール","サリチル酸"],"e":"ピクリン酸（2,4,6-トリニトロフェノール）はフェノールに混酸を作用させて作る。トルエンからはTNT（2,4,6-トリニトロトルエン）。"},{"id":"d8-4","q":"次のうち、酸化して安息香酸が得られない物質はどれか。","a":"フェノール","w":["ベンジルアルコール","ベンズアルデヒド","トルエン","エチルベンゼン"],"e":"フェノールの−OHは環に直接ついていて、酸化しても−COOHにはならない。ベンジルアルコール・ベンズアルデヒドは酸化で、トルエン・エチルベンゼンは側鎖の酸化で安息香酸になる。"},{"id":"d8-5","q":"次のうち、酸化して安息香酸が得られない物質はどれか。","a":"サリチル酸","w":["ベンジルアルコール","ベンズアルデヒド","トルエン","エチルベンゼン"],"e":"サリチル酸は−OHと−COOHをもち、酸化しても−OHのない安息香酸にはならない。ベンジルアルコール・ベンズアルデヒド・トルエン・エチルベンゼンは酸化すると安息香酸。"},{"id":"d8-6","q":"次のうち、酸性条件の過マンガン酸カリウムで酸化したときに、安息香酸が得られるものはどれか","a":"トルエン","w":["フェノール","キシレン","クレゾール","サリチル酸"],"e":"トルエンは側鎖のメチル基が−COOHになり安息香酸ができる。キシレンはメチル基が2つなのでフタル酸類、クレゾール・サリチル酸は−OHが残る、フェノールは側鎖がない。"},{"id":"d8-7","q":"次のうち、酸性条件の過マンガン酸カリウムで酸化したときに、フタル酸が得られるものはどれか","a":"𝑜&#8209;キシレン","w":["𝑝&#8209;キシレン","トルエン","𝑝&#8209;クレゾール","フマル酸"],"e":"𝑜&#8209;キシレンは隣どうし（オルト位）のメチル基が2つとも−COOHになり、フタル酸ができる。𝑝&#8209;キシレンならテレフタル酸、トルエンなら安息香酸。フマル酸はベンゼン環のないカルボン酸。"},{"id":"d8-8","q":"次のうち、酸性条件の過マンガン酸カリウムで酸化したときに、テレフタル酸が得られるものはどれか","a":"𝑝&#8209;キシレン","w":["𝑜&#8209;キシレン","トルエン","𝑚&#8209;クレゾール","フマル酸"],"e":"𝑝&#8209;キシレンは向かい合う位置（パラ位）のメチル基が−COOHになり、テレフタル酸ができる。𝑜&#8209;キシレンならフタル酸、トルエンなら安息香酸。"},{"id":"d8-9","q":"次のうち、高温高圧で二酸化炭素を反応させ、その後酸で処理するとサリチル酸が得られるのはどれか。","a":"フェノール","w":["安息香酸","ベンゼンスルホン酸","サリチル酸メチル","フタル酸"],"e":"フェノール→（NaOH）ナトリウムフェノキシド→（CO₂、高温・高圧）サリチル酸ナトリウム→（酸）サリチル酸。安息香酸・フタル酸・ベンゼンスルホン酸からはできない。"},{"id":"d8-10","q":"次のうち、還元し、塩基で処理するとアニリンが得られるのはどれか。","a":"ニトロベンゼン","w":["2,4,6-トリニトロトルエン","フェノール","サリチル酸","サリチル酸メチル"],"e":"ニトロベンゼンをスズと塩酸で還元し、塩基で遊離させるとアニリン。TNTはニトロ基が3つでメチル基もあるので、還元してもアニリンにはならない。"},{"id":"d8-11","q":"次のうち、ナトリウムフェノキシドと反応させると、𝑝&#8209;ヒドロキシアゾベンゼンが得られるのはどれか。","a":"塩化ベンゼンジアゾニウム","w":["アニリン","アニリン塩酸塩","アセトアニリド","クロロベンゼン"],"e":"塩化ベンゼンジアゾニウムとナトリウムフェノキシドのジアゾカップリングで𝑝&#8209;ヒドロキシアゾベンゼンができる。アニリンやアニリン塩酸塩はまずジアゾ化が必要。"},{"id":"d8-12","q":"次のうち、温度を上げて分解されるとフェノールが得られる物質はどれか。","a":"塩化ベンゼンジアゾニウム","w":["アニリン","𝑝&#8209;ヒドロキシアゾベンゼン","アセトアニリド","クロロベンゼン"],"e":"塩化ベンゼンジアゾニウムは温めると分解してフェノールとN₂になる。クロロベンゼンからフェノールを得るには、NaOH水溶液と高温・高圧が必要。"}]},{"name":"No.10 検出反応まとめ","items":[{"id":"d9-0","q":"次のうち、金属ナトリウムと反応して水素を発生するものはどれか","a":"フェノール","w":["キシレン","ナフタレン","アニリン","アセトアニリド"],"e":"フェノールは−OHをもつので金属Naと反応してH₂を出す。キシレン・ナフタレンは−OHがない。アニリンの−NH₂やアセトアニリドはNaと反応しない（高校範囲）。"},{"id":"d9-1","q":"次のうち、炭酸水素ナトリウムと反応して二酸化炭素を発生するものはどれか","a":"サリチル酸","w":["サリチル酸メチル","フェノール","トルエン","ベンジルアルコール"],"e":"サリチル酸は−COOHをもち、炭酸より強い酸なのでNaHCO₃からCO₂を出す。フェノール（−OH）は炭酸より弱いので出さない。サリチル酸メチルは−COOHがエステルになっている。"},{"id":"d9-2","q":"次のうち、金属ナトリウムと反応して水素を発生しないものはどれか","a":"トルエン","w":["安息香酸","サリチル酸","サリチル酸メチル","アセチルサリチル酸"],"e":"トルエンは−OHも−COOHももたないのでNaと反応しない。安息香酸・サリチル酸・アセチルサリチル酸は−COOH、サリチル酸メチルは環に−OHをもつので反応する。"},{"id":"d9-3","q":"次のうち、炭酸水素ナトリウムと反応して二酸化炭素を発生しないものはどれか","a":"サリチル酸メチル","w":["安息香酸","ベンゼンスルホン酸","サリチル酸","フタル酸"],"e":"サリチル酸メチルは−COOHがエステルになっているので、NaHCO₃と反応しない（残った−OHは炭酸より弱い）。安息香酸・サリチル酸・フタル酸（−COOH）、ベンゼンスルホン酸（強酸）はCO₂を出す。"},{"id":"d9-4","q":"次のうち、金属ナトリウムと反応して水素を発生しないものはどれか","a":"ニトロベンゼン","w":["ベンジルアルコール","フェノール","ベンゼンスルホン酸","クレゾール"],"e":"ニトロベンゼンは−OHをもたないのでNaと反応しない。ベンジルアルコール・フェノール・クレゾールは−OH、ベンゼンスルホン酸は−SO₃Hをもつので反応する。"},{"id":"d9-5","q":"次のうち、塩化鉄(Ⅲ)を加えると、呈色するものはどれか","a":"クレゾール","w":["アセチルサリチル酸","ベンジルアルコール","アニリン","安息香酸"],"e":"クレゾールはフェノール類（環に直接−OH）なのでFeCl₃で呈色する。アセチルサリチル酸は−OHがアセチル化されている、ベンジルアルコールの−OHは環に直接ついていない、アニリン・安息香酸は−OHがない。"},{"id":"d9-6","q":"次のうち、塩化鉄(Ⅲ)を加えると、呈色するものはどれか","a":"サリチル酸","w":["アセチルサリチル酸","ベンジルアルコール","アニリン","安息香酸"],"e":"サリチル酸は環に直接−OHをもつので、FeCl₃で赤紫色に呈色する。アセチルサリチル酸・ベンジルアルコール・アニリン・安息香酸は環に直接ついた−OHをもたない。"},{"id":"d9-7","q":"次のうち、塩化鉄(Ⅲ)を加えても、呈色しないものはどれか","a":"アセチルサリチル酸","w":["サリチル酸メチル","サリチル酸","フェノール","クレゾール"],"e":"アセチルサリチル酸は−OHがアセチル化されているので呈色しない。サリチル酸メチルは−COOHがエステルになっただけで−OHは残るので呈色する。"},{"id":"d9-8","q":"次のうち、塩化鉄(Ⅲ)を加えても、呈色しないものはどれか","a":"アニリン","w":["サリチル酸メチル","サリチル酸","フェノール","クレゾール"],"e":"アニリンは−OHをもたないのでFeCl₃で呈色しない（アニリンの検出はさらし粉）。サリチル酸メチル・サリチル酸・フェノール・クレゾールは環に−OHをもつ。"},{"id":"d9-9","q":"次のうち、銀鏡反応陽性のものはどれか","a":"ベンズアルデヒド","w":["ベンジルアルコール","安息香酸","サリチル酸","アセチルサリチル酸"],"e":"ベンズアルデヒドはアルデヒド基（−CHO）をもつので銀鏡反応陽性。ベンジルアルコールは−CH₂OH、安息香酸・サリチル酸・アセチルサリチル酸は−COOHで、還元性がない。"},{"id":"d9-10","q":"次のうち、加熱して酸無水物を与えるものはどれか","a":"フタル酸","w":["テレフタル酸","安息香酸","サリチル酸","アセチルサリチル酸"],"e":"フタル酸は2つの−COOHが隣どうし（オルト位）にあるので、加熱すると分子内で脱水して無水フタル酸になる。テレフタル酸は−COOHが離れている（パラ位）、他は−COOHが1つ。"},{"id":"d9-11","q":"次のうち、五酸化バナジウムとともに加熱すると、無水マレイン酸が生成する物質はどれか。","a":"ベンゼン","w":["ナフタレン","キシレン","トルエン","フタル酸"],"e":"ベンゼンをV₂O₅触媒で酸化すると、環が開いて無水マレイン酸ができる。ナフタレンなら無水フタル酸。"},{"id":"d9-12","q":"次のうち、さらし粉で赤紫色に呈色するのものはどれか","a":"アニリン","w":["塩化ベンゼンジアゾニウム","サリチル酸","フェノール","トルエン"],"e":"アニリンはさらし粉水溶液で酸化されて赤紫色に呈色する（アニリンの検出）。フェノール類の検出はFeCl₃。"},{"id":"d9-13","q":"次のうち、酸性条件の二クロム酸カリウムで黒く呈色するのものはどれか","a":"アニリン","w":["塩化ベンゼンジアゾニウム","サリチル酸","フェノール","トルエン"],"e":"アニリンは硫酸酸性のK₂Cr₂O₇で高度に酸化され、黒色のアニリンブラックになる。"},{"id":"d9-14","q":"次のうち、五酸化バナジウムとともに加熱すると、無水フタル酸が生成する物質はどれか。","a":"ナフタレン","w":["ベンゼン","アニリン","トルエン","フマル酸"],"e":"ナフタレンをV₂O₅触媒で酸化すると、片方の環が開いて無水フタル酸ができる。ベンゼンなら無水マレイン酸。"},{"id":"d9-15","q":"次のうち、過マンガン酸カリウムで酸化し、さらに加熱すると、無水フタル酸が生成するものはどれか。","a":"𝑜&#8209;キシレン","w":["𝑚&#8209;キシレン","𝑝&#8209;キシレン","トルエン","ベンゼン"],"e":"𝑜&#8209;キシレンを酸化すると隣どうしのメチル基が−COOHになってフタル酸になり、加熱すると脱水して無水フタル酸になる。𝑚&#8209;キシレン・𝑝&#8209;キシレンの酸化物は−COOHが離れていて無水物にならない。トルエンは安息香酸、ベンゼンはKMnO₄で酸化されない。"}]}]},{"key":"ali","label":"脂肪族","icon":"🧪","img":"../aliphatic-quest/assets/memo/","decks":[{"name":"No.1 構造式(名称当て)","items":[{"id":"d0-0","q":"名称を答えよ。","a":"1-プロパノール","w":["2-プロパノール","エタノール","2-メチル-2-プロパノール"],"e":"主鎖が炭素3つ（プロパン）で、1位(末端)の炭素に−OHがつくので1-プロパノール。2位(中央)につくと2-プロパノール。エタノールは炭素2つ、2-メチル-2-プロパノールは２位にメチル基がついた２‐プロパノール。","img":"1-プロパノール.jpg"},{"id":"d0-1","q":"名称を答えよ。","a":"2-プロパノール","w":["1-プロパノール","エタノール","2-メチル-2-ブタノール"],"e":"主鎖が炭素3つ（プロパン）で、2位(中央)の炭素に−OHがつくので2-プロパノール。1位(末端)につくと1-プロパノール。エタノールは炭素2つ、2-メチル-2-ブタノールは主鎖が炭素4つ（ブタン）。","img":"2-プロパノール.jpg"},{"id":"d0-2","q":"名称を答えよ。","a":"2-メチル-1-ブタノール","w":["3-メチル-1-ブタノール","2-メチル-2-ブタノール","3-メチル-2-ブタノール"],"e":"主鎖が炭素4つ（ブタン）で、1位(末端)に−OH、2位にメチル基がつくので2-メチル-1-ブタノール。3-メチル-1-ブタノールはメチル基が3位、〜-2-ブタノールは−OHが2位につく。","img":"2－メチルー1－ブタノール.jpg"},{"id":"d0-3","q":"名称を答えよ。","a":"2-メチル-2-ブタノール","w":["2-メチル-1-ブタノール","3-メチル-2-ブタノール","2-メチル-2-プロパノール"],"e":"主鎖が炭素4つ（ブタン）で、2位の炭素に−OHとメチル基の両方がつくので2-メチル-2-ブタノール。3-メチル-2-ブタノールはメチル基が隣の3位、2-メチル-2-プロパノールは主鎖が炭素3つ。","img":"2－メチルー2－ブタノール.jpg"},{"id":"d0-4","q":"名称を答えよ。","a":"2-メチル-2-プロパノール","w":["2-メチル-2-ブタノール","1-プロパノール","2-プロパノール"],"e":"主鎖が炭素3つ（プロパン）で、2位(中央)の炭素に−OHとメチル基がつくので2-メチル-2-プロパノール。2-メチル-2-ブタノールは主鎖が炭素4つ、1-・2-プロパノールはメチル基がない。","img":"2－メチルー2－プロパノール.jpg"},{"id":"d0-5","q":"名称を答えよ。","a":"3-メチル-1-ブタノール","w":["2-メチル-1-ブタノール","3-メチル-2-ブタノール","2-メチル-2-ブタノール"],"e":"主鎖が炭素4つ（ブタン）で、1位(末端)に−OH、3位にメチル基がつくので3-メチル-1-ブタノール。2-メチル-1-ブタノールはメチル基が2位、〜-2-ブタノールは−OHが2位につく。","img":"3－メチルー1－ブタノール.jpg"},{"id":"d0-6","q":"名称を答えよ。","a":"3-メチル-2-ブタノール","w":["3-メチル-1-ブタノール","2-メチル-2-ブタノール","2-メチル-1-ブタノール"],"e":"主鎖が炭素4つ（ブタン）で、2位に−OH、3位にメチル基がつくので3-メチル-2-ブタノール。2-メチル-2-ブタノールは−OHとメチル基が同じ2位、〜-1-ブタノールは−OHが1位(末端)につく。","img":"3－メチルー2－ブタノール.jpg"},{"id":"d0-7","q":"名称を答えよ。","a":"アセトアルデヒド","w":["ホルムアルデヒド","アセトン","酢酸"],"e":"CH₃CHO。メチル基にアルデヒド基（−CHO）がついたアセトアルデヒド。ホルムアルデヒドはHCHO、アセトンはC=Oの両側がメチル基（ケトン）、酢酸は−CHOの代わりに−COOH。","img":"アセトアルデヒド.jpg"},{"id":"d0-8","q":"名称を答えよ。","a":"アセトン","w":["アセトアルデヒド","2-プロパノール","無水酢酸"],"e":"CH₃COCH₃。カルボニル基（C=O）の両側にメチル基がついたケトンでアセトン。アセトアルデヒドは片側がH（−CHO）、2-プロパノールはC=Oの代わりにC−OH、無水酢酸は−CO−O−CO−。","img":"アセトン.jpg"},{"id":"d0-9","q":"名称を答えよ。","a":"エタノール","w":["1-プロパノール","2-プロパノール","メタノール"],"e":"C₂H₅OH。炭素2つに−OHがついたエタノール。メタノールは炭素1つ、1-・2-プロパノールは炭素3つ。","img":"エタノール.jpg"},{"id":"d0-10","q":"名称を答えよ。","a":"ギ酸","w":["酢酸","ホルムアルデヒド","無水酢酸"],"e":"HCOOH。カルボキシ基にHがついたギ酸（アルデヒド基ももつ）。酢酸はHの代わりにメチル基、ホルムアルデヒドはHCHO、無水酢酸は酢酸2分子から水がとれたもの。","img":"ギ酸.jpg"},{"id":"d0-11","q":"名称を答えよ。","a":"シス-2-ブテン","w":["プロペン","塩化ビニル","ビニルアルコール"],"e":"主鎖が炭素4つで2位に二重結合があり、両端のメチル基が同じ側にあるのでシス-2-ブテン。プロペンは炭素3つ、塩化ビニル・ビニルアルコールはClや−OHをもつ。","img":"シス‐2-ブテン.jpg"},{"id":"d0-12","q":"名称を答えよ。","a":"ビニルアルコール","w":["塩化ビニル","プロペン","アセトアルデヒド"],"e":"CH₂=CH−OH。ビニル基に−OHがついたビニルアルコール（不安定で、すぐアセトアルデヒドになる）。塩化ビニルは−OHの代わりにCl、プロペンは−OHの代わりにメチル基。","img":"ビニルアルコール.jpg"},{"id":"d0-13","q":"名称を答えよ。","a":"プロペン","w":["塩化ビニル","ビニルアルコール","シス-2-ブテン"],"e":"CH₂=CH−CH₃。炭素3つで二重結合を1つもつアルケンなのでプロペン（プロピレン）。塩化ビニル・ビニルアルコールはメチル基の代わりにClや−OH。","img":"プロペン.jpg"},{"id":"d0-14","q":"名称を答えよ。","a":"ホルムアルデヒド","w":["アセトアルデヒド","ギ酸","アセトン"],"e":"HCHO。最も簡単なアルデヒドでホルムアルデヒド。アセトアルデヒドはHの代わりにメチル基、ギ酸は−CHOの代わりに−COOH、アセトンはケトン。","img":"ホルムアルデヒド.jpg"},{"id":"d0-15","q":"名称を答えよ。","a":"塩化ビニル","w":["ビニルアルコール","プロペン","シス-2-ブテン"],"e":"CH₂=CHCl。ビニル基にClがついた塩化ビニル（ポリ塩化ビニルの原料）。ビニルアルコールはClの代わりに−OH、プロペンはClの代わりにメチル基。","img":"塩化ビニル.jpg"},{"id":"d0-16","q":"名称を答えよ。","a":"無水酢酸","w":["酢酸","酢酸エチル","アセトン"],"e":"(CH₃CO)₂O。酢酸2分子から水がとれて−O−で結ばれた無水酢酸。酢酸はCH₃COOH、酢酸エチルはCH₃COOC₂H₅、アセトンはCH₃COCH₃。","img":"無水酢酸.jpg"},{"id":"d0-17","q":"名称を答えよ。","a":"酢酸","w":["ギ酸","無水酢酸","酢酸エチル"],"e":"CH₃COOH。メチル基にカルボキシ基がついた酢酸。ギ酸はメチル基の代わりにH、無水酢酸は酢酸2分子から水がとれたもの、酢酸エチルは−OHのHがエチル基になったエステル。","img":"酢酸.jpg"},{"id":"d0-18","q":"名称を答えよ。","a":"酢酸エチル","w":["酢酸","無水酢酸","ギ酸"],"e":"CH₃COOC₂H₅。酢酸とエタノールがエステル結合（−COO−）でつながった酢酸エチル。酢酸は−COOH、無水酢酸は−CO−O−CO−、ギ酸はHCOOH。","img":"酢酸エチル.jpg"}]},{"name":"No.2 アルコール・エーテルの性質","items":[{"id":"d1-0","q":"メタノールは何性か。","a":"中性","w":["酸性","塩基性","両性"],"e":"アルコールの−OHはほとんど電離しないので中性。NaOHのOH⁻（水酸化物イオン）とは別物。"},{"id":"d1-1","q":"エタノールは何性か。","a":"中性","w":["酸性","塩基性","両性"],"e":"アルコールの−OHはほとんど電離しないので中性。Naとは反応するが、酸性ではない。"},{"id":"d1-2","q":"エタノールは130℃で(ア)し、(イ)が生成する。","a":"ア：分子間脱水　イ：ジエチルエーテル","w":["ア：分子内脱水　イ：ジエチルエーテル","ア：分子間脱水　イ：エチレン","ア：分子内脱水　イ：エチレン"],"e":"130℃では2分子のエタノールから水がとれる分子間脱水が起こり、ジエチルエーテルができる（2C₂H₅OH→C₂H₅OC₂H₅＋H₂O）。160℃なら分子内脱水でエチレン。"},{"id":"d1-3","q":"エタノールは160℃で(ア)し、(イ)が生成する。","a":"ア：分子内脱水　イ：エチレン","w":["ア：分子内脱水　イ：ジエチルエーテル","ア：分子間脱水　イ：エチレン","ア：分子間脱水　イ：ジエチルエーテル"],"e":"160℃では1分子の中で水がとれる分子内脱水が起こり、エチレンができる（C₂H₅OH→C₂H₄＋H₂O）。130℃なら分子間脱水でジエチルエーテル。"},{"id":"d1-4","q":"2-プロパノールは分子内脱水すると(ア)が生成する。","a":"プロペン","w":["エチレン","アセチレン","ジエチルエーテル"],"e":"分子内脱水でC=Cができ、炭素3つのアルケン、プロペンになる。炭素骨格は変わらないので炭素2つのエチレン・アセチレンにはならない。エーテルは分子間脱水でできる。"},{"id":"d1-5","q":"分子内脱水のときに抜けるのは、ヒドロキシ基(-OH)と、(ア)である。","a":"ヒドロキシ基が結合している炭素の隣の炭素に結合している水素","w":["ヒドロキシ基が結合している炭素についている水素","ヒドロキシ基が結合している炭素の隣の水素","もう一分子のヒドロキシ基の水素"],"e":"分子内脱水では、−OHと、その炭素の隣の炭素についたHがとれて、その間にC=Cができる。−OHのついた炭素自身のHがとれても二重結合はできない。"},{"id":"d1-6","q":"分子間脱水のときに抜けるのは、ヒドロキシ基(-OH)と、(ア)である。","a":"もう一分子のヒドロキシ基の水素","w":["ヒドロキシ基が結合している炭素についている水素","ヒドロキシ基が結合している炭素の隣の水素","ヒドロキシ基が結合している炭素の隣の炭素に結合している水素"],"e":"分子間脱水では、一方の−OHと、もう一分子の−OHのHがとれて水になり、−O−（エーテル結合）でつながる。"},{"id":"d1-7","q":"アルコールは(ア)と反応し、(イ)が生成する。また同時にナトリウムアルコキシドが生成する。","a":"ア：金属ナトリウム　イ：水素","w":["ア：金属ナトリウム　イ：酸素","ア：ナトリウムイオン　イ：水素","ア：ナトリウムイオン　イ：酸素"],"e":"2R−OH＋2Na→2R−ONa＋H₂。単体の金属ナトリウムと反応して水素を出す（アルコールの検出）。ナトリウムイオンでは反応しない。酸素は出ない。"},{"id":"d1-8","q":"ジエチルエーテルは何性か。","a":"中性","w":["酸性","塩基性","両性"],"e":"エーテルは電離する部分をもたないので中性。−OHももたないので、Naとも反応しない。"},{"id":"d1-9","q":"ジエチルエーテルは水と","a":"混ざらない","w":["任意の割合で混和"],"e":"ジエチルエーテルは水と混ざりにくく、有機物をよく溶かすので抽出の溶媒に使う。水と任意に混ざるのは低級アルコールやアセトン。"},{"id":"d1-10","q":"エタノールは水と","a":"任意の割合で混和","w":["混ざらない"],"e":"エタノールの−OHが水と水素結合するので、水と任意の割合で混ざる。炭素数が多くなる（6以上）と混ざらなくなる。"}]},{"name":"No.3 アルコールの級数・価数","items":[{"id":"d2-0","q":"メタノールは何級アルコールか。","a":"1級アルコール","w":["4級アルコール","2級アルコール","3級アルコール"],"e":"級数は−OHのついた炭素に結合している炭素の数で決まる。メタノールは0だが1級とする。4級アルコールは存在しない（炭素の結合は4本で、1本は−OH）。"},{"id":"d2-1","q":"エタノールは何級アルコールか。","a":"1級アルコール","w":["4級アルコール","2級アルコール","3級アルコール"],"e":"CH₃CH₂OH。−OHのついた炭素に炭素が1つ結合しているので1級。4級アルコールは存在しない。"},{"id":"d2-2","q":"1-プロパノールは何級アルコールか。","a":"1級アルコール","w":["4級アルコール","2級アルコール","3級アルコール"],"e":"CH₃CH₂CH₂OH。−OHが1位(末端)の炭素につき、その炭素に結合している炭素は1つなので1級。"},{"id":"d2-3","q":"2-プロパノールは何級アルコールか。","a":"2級アルコール","w":["1級アルコール","4級アルコール","3級アルコール"],"e":"CH₃CH(OH)CH₃。−OHのついた2位(中央)の炭素に炭素が2つ結合しているので2級。"},{"id":"d2-4","q":"2-ブタノールは何級アルコールか。","a":"2級アルコール","w":["1級アルコール","4級アルコール","3級アルコール"],"e":"CH₃CH(OH)CH₂CH₃。−OHのついた2位の炭素に炭素が2つ結合しているので2級。"},{"id":"d2-5","q":"2-メチル-2-プロパノールは何級アルコールか。","a":"3級アルコール","w":["1級アルコール","2級アルコール","4級アルコール"],"e":"(CH₃)₃COH。−OHのついた2位の炭素にメチル基が3つ結合しているので3級。"},{"id":"d2-6","q":"2-メチル-2-ブタノールは何級アルコールか。","a":"3級アルコール","w":["1級アルコール","2級アルコール","4級アルコール"],"e":"−OHのついた2位の炭素に、炭素が3つ（メチル基2つとエチル基）結合しているので3級。"},{"id":"d2-7","q":"3-メチル-2-ブタノールは何級アルコールか。","a":"2級アルコール","w":["1級アルコール","4級アルコール","3級アルコール"],"e":"CH₃CH(OH)CH(CH₃)₂。−OHのついた2位の炭素に炭素が2つ結合しているので2級。メチル基は隣の3位についているので級数には関係しない。"},{"id":"d2-8","q":"1-ブタノールは何級アルコールか。","a":"1級アルコール","w":["4級アルコール","2級アルコール","3級アルコール"],"e":"CH₃CH₂CH₂CH₂OH。−OHが1位(末端)の炭素につき、結合している炭素は1つなので1級。"},{"id":"d2-9","q":"メタノールは何価のアルコールか。","a":"1価","w":["2価","3価","4価"],"e":"価数は−OHの数。メタノールCH₃OHは−OHが1つなので1価。"},{"id":"d2-10","q":"エタノールは何価のアルコールか。","a":"1価","w":["2価","3価","4価"],"e":"価数は−OHの数。エタノールC₂H₅OHは−OHが1つなので1価。"},{"id":"d2-11","q":"2-プロパノールは何価のアルコールか。","a":"1価","w":["2価","3価","4価"],"e":"価数は−OHの数。2-プロパノールの「2」は−OHの位置で、−OHは1つなので1価（級数は2級）。"},{"id":"d2-12","q":"1-プロパノールは何価のアルコールか。","a":"1価","w":["2価","3価","4価"],"e":"価数は−OHの数。1-プロパノールは−OHが1つなので1価。"},{"id":"d2-13","q":"エチレングリコールは何価のアルコールか。","a":"2価","w":["1価","3価","4価"],"e":"エチレングリコールHOCH₂CH₂OH（1,2-エタンジオール）は−OHが2つなので2価。"},{"id":"d2-14","q":"グリセリンは何価のアルコールか。","a":"3価","w":["2価","1価","4価"],"e":"グリセリン（1,2,3-プロパントリオール）は−OHが3つなので3価。油脂の成分。"},{"id":"d2-15","q":"2-メチル-2-プロパノールは何価のアルコールか。","a":"1価","w":["2価","3価","4価"],"e":"価数は−OHの数。2-メチル-2-プロパノールは−OHが1つなので1価（級数は3級）。級数と価数を混同しないこと。"}]},{"name":"No.4 アルコールの酸化","items":[{"id":"d3-0","q":"メタノールCH₃OHの酸化を穏やかに行うと何が生成するか。","a":"ホルムアルデヒド","w":["アセトアルデヒド","ベンズアルデヒド","酸化されない","アセトン"],"e":"1級アルコールを穏やかに酸化するとアルデヒドになる。メタノールCH₃OHからはホルムアルデヒドHCHO。炭素骨格は変わらないので、炭素2つ以上の物質にはならない。"},{"id":"d3-1","q":"エタノールを穏やかに酸化すると何が生成するか。","a":"アセトアルデヒド","w":["ホルムアルデヒド","ベンズアルデヒド","酸化されない","アセトン"],"e":"エタノールは1級アルコールなので、穏やかに酸化するとアルデヒドのアセトアルデヒド。アセトンは2級アルコールの2-プロパノールから。"},{"id":"d3-2","q":"2-プロパノールを穏やかに酸化すると何が生成するか。","a":"アセトン","w":["ホルムアルデヒド","ベンズアルデヒド","酸化されない","アセトアルデヒド"],"e":"2-プロパノールは2級アルコールなので、酸化するとケトンのアセトン。アルデヒドにはならない。"},{"id":"d3-3","q":"第1級アルコールを穏やかに酸化すると何が生成するか。","a":"アルデヒド","w":["ケトン","カルボン酸","酸化されない","エーテル"],"e":"1級アルコール→アルデヒド→カルボン酸。穏やかに酸化すると1段階目のアルデヒドで止まる。ケトンは2級アルコールから。"},{"id":"d3-4","q":"第2級アルコールを穏やかに酸化すると何が生成するか。","a":"ケトン","w":["アルデヒド","カルボン酸","酸化されない","エーテル"],"e":"2級アルコールを酸化するとケトンになる。−OHのついた炭素にHが1つしかないので、アルデヒドやカルボン酸にはならない。"},{"id":"d3-5","q":"第3級アルコールを穏やかに酸化すると何が生成するか。","a":"酸化されない","w":["アルデヒド","カルボン酸","ケトン","エーテル"],"e":"3級アルコールは−OHのついた炭素にHがないので、酸化されない（されにくい）。"},{"id":"d3-6","q":"アルデヒドを酸化すると何が生成するか。","a":"カルボン酸","w":["アルデヒド","酸化されない","ケトン","エーテル"],"e":"アルデヒドは酸化されやすく、−CHOにOが入ってカルボン酸（−COOH）になる。"},{"id":"d3-7","q":"ケトンを酸化すると何が生成するか。","a":"酸化されない","w":["アルデヒド","カルボン酸","第2級アルコール","エーテル"],"e":"ケトンはカルボニル基の両側が炭素で、酸化されにくい（還元性を示さない）。"},{"id":"d3-8","q":"カルボン酸を酸化すると何が生成するか。","a":"酸化されない","w":["アルデヒド","ケトン","第1級アルコール","エーテル"],"e":"カルボン酸は酸化の最終段階なので、それ以上酸化されない（ギ酸だけは例外で還元性をもつ）。"},{"id":"d3-9","q":"アルデヒドを還元すると何が生成するか。","a":"第1級アルコール","w":["還元されない","カルボン酸","第2級アルコール","第3級アルコール"],"e":"酸化でできた物質を還元すると元に戻る。アルデヒドは1級アルコールの酸化でできるので、還元すると1級アルコール。"},{"id":"d3-10","q":"ケトンを還元すると何が生成するか。","a":"第2級アルコール","w":["還元されない","カルボン酸","第1級アルコール","第3級アルコール"],"e":"ケトンは2級アルコールの酸化でできるので、還元すると2級アルコールに戻る。"},{"id":"d3-11","q":"アルコールを酸化すると、炭素骨格は","a":"変化しない","w":["変化する"],"e":"酸化還元反応では炭素骨格は変化しない。Hがとれるか、Oが入るだけ。"},{"id":"d3-12","q":"通常酸化されないアルコールは","a":"第3級アルコール","w":["第1級アルコール","第2級アルコール"],"e":"3級アルコールは−OHのついた炭素にHがないので、通常は酸化されない。1級・2級は酸化される。"},{"id":"d3-13","q":"第1級アルコールを十分に酸化したとき、得られる物質は","a":"カルボン酸","w":["アルデヒド","酸化されない","ケトン","エーテル"],"e":"1級アルコールを十分に酸化すると、アルデヒドを経てカルボン酸まで進む。穏やかな酸化ならアルデヒドで止まる。"},{"id":"d3-14","q":"酸化してアセトアルデヒドが得られるのは","a":"エタノール","w":["メタノール","1-プロパノール","2-プロパノール","存在しない"],"e":"アセトアルデヒドCH₃CHO（炭素2つ）は、炭素2つの1級アルコール、エタノールの酸化で得られる。メタノールからはホルムアルデヒド、1-プロパノールからはプロピオンアルデヒド。"},{"id":"d3-15","q":"酸化してホルムアルデヒドが得られるのは","a":"メタノール","w":["エタノール","1-プロパノール","2-プロパノール","存在しない"],"e":"ホルムアルデヒドHCHO（炭素1つ）は、メタノールの酸化で得られる。炭素骨格は変わらないので、炭素2つ以上のアルコールからはできない。"},{"id":"d3-16","q":"酸化してアセトンが得られるのは","a":"2-プロパノール","w":["エタノール","1-プロパノール","メタノール","存在しない"],"e":"アセトン（炭素3つのケトン）は、炭素3つの2級アルコール、2-プロパノールの酸化で得られる。1-プロパノールは1級なのでアルデヒドになる。"},{"id":"d3-17","q":"十分に酸化したとき酢酸が得られるのは","a":"エタノール","w":["メタノール","1-プロパノール","2-プロパノール","存在しない"],"e":"酢酸CH₃COOH（炭素2つ）は、エタノール→アセトアルデヒド→酢酸 と酸化して得られる。メタノールからはギ酸、1-プロパノールからはプロピオン酸。"},{"id":"d3-18","q":"酸化してギ酸が得られるのは","a":"メタノール","w":["エタノール","1-プロパノール","2-プロパノール","存在しない"],"e":"ギ酸HCOOH（炭素1つ）は、メタノール→ホルムアルデヒド→ギ酸 と酸化して得られる。"}]},{"name":"No.5 アルデヒド・ケトン","items":[{"id":"d4-0","q":"ホルムアルデヒドの37%の水溶液を何というか。","a":"ホルマリン","w":["ヨードホルム","モルホリン"],"e":"ホルムアルデヒドの約37％水溶液がホルマリン（防腐剤）。ヨードホルムCHI₃はヨードホルム反応でできる黄色の固体。モルホリンは別の有機化合物（アミン）。"},{"id":"d4-1","q":"ホルムアルデヒドは常温で","a":"気体","w":["液体","固体"],"e":"ホルムアルデヒドは分子量が小さく（30）、常温で刺激臭のある気体。だから水溶液（ホルマリン）にして使う。"},{"id":"d4-2","q":"ホルムアルデヒドは何性か。","a":"中性","w":["酸性","塩基性"],"e":"アルデヒドは電離する部分をもたないので中性。酸化されるとカルボン酸（酸性）のギ酸になる。"},{"id":"d4-3","q":"ホルムアルデヒドは何を持つか。","a":"還元力","w":["酸化力"],"e":"アルデヒド基は酸化されやすいので、相手を還元する力（還元性）をもつ。銀鏡反応・フェーリング反応を示す。"},{"id":"d4-5","q":"アセトアルデヒドは何性か。","a":"中性","w":["酸性","塩基性"],"e":"アルデヒドは電離する部分をもたないので中性。酸化されると酢酸（酸性）になる。"},{"id":"d4-6","q":"アセトアルデヒドは","a":"酸化されやすい","w":["還元されやすい"],"e":"アルデヒド基は酸化されやすく、自身は酸化されて酢酸になる（その分、相手を還元する）。"},{"id":"d4-7","q":"次のうち、刺激臭がないものを選べ。","a":"アセトン","w":["ホルムアルデヒド","アセトアルデヒド"],"e":"アセトンは芳香（特有のにおい）をもつ液体で、刺激臭ではない。ホルムアルデヒド・アセトアルデヒドは刺激臭。"},{"id":"d4-8","q":"次のうち、2級アルコールの酸化で得られるものを選べ。","a":"アセトン","w":["ホルムアルデヒド","アセトアルデヒド","酢酸"],"e":"2級アルコールを酸化するとケトンになるので、アセトン（2-プロパノールの酸化）。ホルムアルデヒド・アセトアルデヒドは1級アルコールから、酢酸はさらに酸化したもの。"},{"id":"d4-9","q":"アセトアルデヒドの工業的製法で、用いる原料はどれか。","a":"エチレン","w":["アセチレン","エタノール","メタノール"],"e":"工業的にはエチレンを触媒（PdCl₂・CuCl₂）で酸化して作る（ワッカー法）。2C₂H₄＋O₂→2CH₃CHO。昔はアセチレンへの水付加（水銀触媒）だったが、水俣病の原因となった。"},{"id":"d4-10","q":"アセトアルデヒドの工業的製法で用いる触媒の組み合わせのうち、正しいものはどれか。","a":"PdCl₂、CuCl₂","w":["SnCl₂、PdCl₂","FeCl₂、PdCl₂","FeCl₂、CuCl₂"],"e":"ワッカー法の触媒は塩化パラジウム(Ⅱ)PdCl₂と塩化銅(Ⅱ)CuCl₂。SnCl₂・FeCl₂は使わない。"},{"id":"d4-11","q":"アセトンは水と混ざるか。","a":"任意の割合で混和","w":["混ざらない"],"e":"アセトンは水と任意の割合で混ざる。そのため水と分離できず、抽出の溶媒には使えない。"},{"id":"d4-12","q":"アセトンの実験室的製法は酢酸カルシウムをどうするか。","a":"乾留","w":["溶融塩電解","分留","還元","酸化"],"e":"酢酸カルシウムを乾留（空気を断って加熱）するとアセトンが得られる。(CH₃COO)₂Ca→CH₃COCH₃＋CaCO₃。分留は沸点の差で分ける操作。"}]},{"name":"No.6 カルボン酸・エステル","items":[{"id":"d5-0","q":"カルボン酸は何性か。","a":"酸性","w":["中性","塩基性"],"e":"カルボキシ基の一部が電離してH⁺を出すので、弱酸性を示す。"},{"id":"d5-1","q":"カルボン酸は何と反応して二酸化炭素を発生するか。","a":"炭酸水素ナトリウム","w":["金属ナトリウム","フェーリング液","石灰水"],"e":"カルボン酸は炭酸より強い酸なので、NaHCO₃から弱酸の炭酸を追い出し、CO₂が発生する（カルボン酸の検出）。金属ナトリウムとは反応するがH₂が出る。フェーリング液はアルデヒドの検出、石灰水はCO₂の検出に使う。"},{"id":"d5-2","q":"ギ酸は常温で","a":"液体","w":["気体","固体"],"e":"ギ酸は刺激臭のある無色の液体。分子間で水素結合するため、分子量のわりに沸点が高い。"},{"id":"d5-3","q":"ギ酸は何を持つか。","a":"還元力","w":["酸化力"],"e":"ギ酸HCOOHは分子中にアルデヒド基をもつので還元性をもち、銀鏡反応を示す。"},{"id":"d5-4","q":"酢酸は常温で","a":"液体","w":["気体","固体"],"e":"酢酸は刺激臭のある無色の液体（融点約17℃）。"},{"id":"d5-5","q":"酢酸は0℃で","a":"固体","w":["液体","気体"],"e":"純粋な酢酸の融点は約17℃なので、0℃では固体。冬に凍るので氷酢酸という。"},{"id":"d5-6","q":"炭素数2までのカルボン酸の特徴として、当てはまらないものはどれか。","a":"酸化力がある","w":["分子間で水素結合を形成する","二量体を形成する","(同分子量の有機物と比べ)融点が高い","刺激臭がある"],"e":"ギ酸・酢酸は分子間で水素結合して二量体をつくり、融点・沸点が高く、刺激臭がある。酸化力はない（ギ酸はむしろ還元性）。"},{"id":"d5-7","q":"次のうち、加熱しても分子内脱水しないものを選べ。","a":"フマル酸","w":["マレイン酸","フタル酸"],"e":"フマル酸はトランス型で、2つの−COOHが離れているため分子内脱水しない。マレイン酸（シス型）やフタル酸は−COOHが近く、加熱で酸無水物になる。"},{"id":"d5-8","q":"次のうち、ジカルボン酸でないものを1つ選べ。","a":"乳酸","w":["マレイン酸","フタル酸","フマル酸","テレフタル酸"],"e":"乳酸CH₃CH(OH)COOHは−COOHが1つのヒドロキシ酸。マレイン酸・フマル酸・フタル酸・テレフタル酸は−COOHを2つもつジカルボン酸。"},{"id":"d5-9","q":"エステルは何性か。","a":"中性","w":["酸性","塩基性"],"e":"エステルは電離する部分をもたないので中性。−COOHはエステル結合に変わっている。"},{"id":"d5-10","q":"低分子のエステルはどのようなにおいを持つことが多いか。","a":"果実臭","w":["腐卵臭","刺激臭","特異臭"],"e":"分子量の小さいエステルは芳香・果実臭をもつものが多い（香料に使う）。腐卵臭はH₂S、刺激臭はアルデヒドやカルボン酸など。"},{"id":"d5-11","q":"酢酸エチルは何性か。","a":"中性","w":["酸性","塩基性"],"e":"酢酸エチルはエステルなので中性。酢酸の−COOHがエステル結合になり、電離しない。"},{"id":"d5-12","q":"エステルは何と何から合成されるか。","a":"アルコールとカルボン酸","w":["アルコールとアルデヒド","アルデヒドとカルボン酸","エーテルとアルコール","エーテルとケトン"],"e":"カルボン酸とアルコールが脱水縮合してエステルができる（エステル化）。アルデヒドやエーテルからはできない。"},{"id":"d5-13","q":"エステルを加水分解すると何が得られるか。","a":"アルコールとカルボン酸","w":["アルコールとアルデヒド","アルデヒドとケトン","エーテルとアルコール","エーテルとケトン"],"e":"加水分解はエステル化の逆反応なので、カルボン酸とアルコールに戻る。"},{"id":"d5-14","q":"次のうち不可逆なものを選べ。","a":"けん化","w":["酸による加水分解","エステル化"],"e":"けん化では生じたカルボン酸がNaOHと中和して塩になるので、逆反応が起こらず不可逆。エステル化と酸による加水分解は平衡反応（可逆）。"},{"id":"d5-15","q":"次のうち可逆なものを選べ。","a":"酸による加水分解","w":["けん化","無水酢酸を用いたエステル化"],"e":"酸による加水分解はエステル化の逆反応で、平衡反応（可逆）。けん化と無水酢酸を用いたエステル化は、逆反応がほぼ起こらない。"}]},{"name":"No.7 エステル化・けん化","items":[{"id":"d6-0","q":"酢酸とエタノールのエステル化で得られるものはなにか。","a":"酢酸エチル","w":["酢酸エタノール","酢酸エチレン","酢酸エテン"],"e":"エステルは「カルボン酸名＋アルコールのアルキル基名」。酢酸＋エタノール（エチル基）で酢酸エチル。「酢酸エタノール」「酢酸エチレン」「酢酸エテン」という物質名はない。"},{"id":"d6-1","q":"酢酸とメタノールのエステル化で得られるものはなにか。","a":"酢酸メチル","w":["酢酸メタノール","酢酸メチレン","メタクリル酸"],"e":"酢酸＋メタノール（メチル基）で酢酸メチル。「酢酸メタノール」「酢酸メチレン」という物質名はない。メタクリル酸は別のカルボン酸。"},{"id":"d6-2","q":"ギ酸とエタノールのエステル化で得られるものはなにか。","a":"ギ酸エチル","w":["酢酸メチル","ギ酸メチル","酢酸エチル"],"e":"ギ酸＋エタノール（エチル基）でギ酸エチル。カルボン酸名とアルキル基名をそのまま組み合わせる。"},{"id":"d6-3","q":"ギ酸とメタノールのエステル化で得られるものはなにか。","a":"ギ酸メチル","w":["酢酸メチル","酢酸エチル","ギ酸エチル"],"e":"ギ酸＋メタノール（メチル基）でギ酸メチル。"},{"id":"d6-4","q":"酢酸と2-プロパノールのエステル化で得られるものはなにか。","a":"酢酸イソプロピル","w":["酢酸プロピル","酢酸エチル","酢酸メチル"],"e":"2-プロパノールのアルキル基はイソプロピル基（−CH(CH₃)₂）なので酢酸イソプロピル。1-プロパノールならプロピル基で酢酸プロピル。"},{"id":"d6-5","q":"酢酸と1-プロパノールのエステル化で得られるものはなにか。","a":"酢酸プロピル","w":["酢酸イソプロピル","酢酸エチル","酢酸メチル"],"e":"1-プロパノールのアルキル基はプロピル基（−CH₂CH₂CH₃）なので酢酸プロピル。2-プロパノールならイソプロピル基。"},{"id":"d6-6","q":"酢酸エチルを加水分解して得られるものはどれか。","a":"エタノール","w":["エチレン","エタン","エチレングリコール"],"e":"加水分解するとカルボン酸とアルコールに戻る。酢酸エチルからは酢酸とエタノール。エチレン・エタン・エチレングリコールは名前が似ているだけ。"},{"id":"d6-7","q":"酢酸メチルを加水分解して得られるものはどれか。","a":"メタノール","w":["メチレン","メタン","メタクリル酸"],"e":"酢酸メチルを加水分解すると酢酸とメタノール。「メチレン」はCH₂の基の名前で物質ではない。メタンは炭化水素、メタクリル酸は別のカルボン酸。"},{"id":"d6-8","q":"酢酸エチルを酸で加水分解して得られるものはどれか。","a":"酢酸とエタノール","w":["酢酸ナトリウムとエタノール","酢酸とナトリウムエトキシド"],"e":"酸による加水分解はエステル化の逆反応で、酢酸とエタノールが生じる。酢酸ナトリウムができるのはNaOHによるけん化。"},{"id":"d6-9","q":"酢酸メチルを酸で加水分解して得られるものはどれか。","a":"酢酸とメタノール","w":["酢酸ナトリウムとメタノール","酢酸とナトリウムメトキシド","酢酸ナトリウムとナトリウムメトキシド"],"e":"酸による加水分解では酢酸とメタノールが生じる。ナトリウム塩ができるのはけん化。ナトリウムメトキシドはメタノール＋Na単体でできるもの。"},{"id":"d6-10","q":"酢酸エチルをけん化して得られるものはどれか。","a":"酢酸ナトリウムとエタノール","w":["酢酸とエタノール","酢酸とナトリウムエトキシド"],"e":"けん化（NaOHによる加水分解）では、生じた酢酸がNaOHで中和されて酢酸ナトリウムになり、エタノールが残る。アルコールはNaOHと反応しないのでナトリウムエトキシドにはならない。"},{"id":"d6-11","q":"酢酸メチルをけん化して得られるものはどれか。","a":"酢酸ナトリウムとメタノール","w":["酢酸とメタノール","酢酸とナトリウムメトキシド","酢酸ナトリウムとナトリウムメトキシド"],"e":"けん化では酢酸ナトリウムとメタノールが生じる。メタノールはNaOHでは中和されないので、ナトリウムメトキシドにはならない。"}]},{"name":"No.8 検出反応まとめ","items":[{"id":"d7-0","q":"次のうち、金属ナトリウムと反応して水素を発生するものはどれか。","a":"1-プロパノール","w":["アセトン","アセトアルデヒド","酢酸エチル"],"e":"−OHをもつ物質はNaと反応してH₂を出す。1-プロパノールはアルコール。アセトン・アセトアルデヒド・酢酸エチルは−OHをもたない。"},{"id":"d7-1","q":"次のうち、金属ナトリウムと反応して水素を発生するものはどれか。","a":"2-プロパノール","w":["ホルムアルデヒド","ギ酸メチル","ジエチルエーテル"],"e":"2-プロパノールは−OHをもつのでNaと反応しH₂を出す。ホルムアルデヒド・ギ酸メチル・ジエチルエーテルは−OHをもたない。"},{"id":"d7-2","q":"次のうち、金属ナトリウムと反応して水素を発生するものはどれか。","a":"酢酸","w":["エチルメチルエーテル","無水酢酸","ギ酸プロピル"],"e":"酢酸のカルボキシ基も−O−Hをもつので、Naと反応してH₂を出す。エーテル・無水酢酸・エステルは−OHをもたない。"},{"id":"d7-3","q":"次のうち、金属ナトリウムと反応して水素を発生しないものはどれか。","a":"アセトン","w":["エタノール","メタノール","2-プロパノール","酢酸"],"e":"アセトンはケトンで−OHをもたないのでNaと反応しない。アルコールと酢酸は−O−Hをもつので反応する。"},{"id":"d7-4","q":"次のうち、金属ナトリウムと反応して水素を発生しないものはどれか。","a":"酢酸エチル","w":["エタノール","ギ酸","2-プロパノール","酢酸"],"e":"酢酸エチルはエステルで−OHをもたないので反応しない。ギ酸・酢酸（−COOH）やアルコールは−O−Hをもつので反応する。"},{"id":"d7-5","q":"次のうち、金属ナトリウムと反応して水素を発生しないものはどれか。","a":"アセトアルデヒド","w":["エタノール","2-プロパノール","1-プロパノール","酢酸"],"e":"アセトアルデヒドは−OHをもたないので反応しない。アルコールと酢酸は−O−Hをもつので反応する。"},{"id":"d7-6","q":"次のうち、金属ナトリウムと反応して水素を発生しないものはどれか。","a":"ジエチルエーテル","w":["エタノール","メタノール","2-プロパノール","酢酸"],"e":"ジエチルエーテルは−OHをもたないのでNaと反応しない（アルコールとの区別に使う）。"},{"id":"d7-7","q":"次のうち、銀鏡反応陽性のものはどれか。","a":"アセトアルデヒド","w":["エタノール","メタノール","酢酸","酢酸エチル"],"e":"銀鏡反応はアルデヒド基（−CHO）をもつ物質で陽性。アセトアルデヒドはもつ。アルコール・酢酸・酢酸エチルはもたない。"},{"id":"d7-8","q":"次のうち、銀鏡反応陽性のものはどれか。","a":"ホルムアルデヒド","w":["エタノール","メタノール","酢酸","酢酸エチル"],"e":"ホルムアルデヒドHCHOはアルデヒド基をもつので銀鏡反応陽性。アルコール・酢酸・酢酸エチルはもたない。"},{"id":"d7-9","q":"次のうち、銀鏡反応陽性のものはどれか。","a":"ギ酸エチル","w":["エタノール","メタノール","酢酸","酢酸エチル"],"e":"ギ酸エチルHCOOC₂H₅は、ギ酸由来のH−C(=O)−の部分にアルデヒド基の構造をもつので銀鏡反応陽性。酢酸エチルはもたない。"},{"id":"d7-10","q":"次のうち、銀鏡反応陰性のものはどれか。","a":"エタノール","w":["ギ酸","アセトアルデヒド","ホルムアルデヒド","ギ酸エチル"],"e":"エタノールはアルデヒド基をもたないので陰性。ギ酸・ギ酸エチルはH−C(=O)−の構造をもち、アルデヒドとともに陽性。"},{"id":"d7-11","q":"次のうち、銀鏡反応陰性のものはどれか。","a":"酢酸","w":["ギ酸","アセトアルデヒド","ホルムアルデヒド","ギ酸メチル"],"e":"酢酸はアルデヒド基をもたないので陰性。ギ酸だけはカルボン酸でもアルデヒド基をもつので陽性になる。"},{"id":"d7-12","q":"次のうち、フェーリング反応陽性のものはどれか。","a":"アセトアルデヒド","w":["エタノール","メタノール","酢酸","酢酸エチル"],"e":"フェーリング反応もアルデヒド基で陽性（赤色のCu₂Oが沈殿）。アセトアルデヒドはもつ。アルコール・酢酸・エステルはもたない。"},{"id":"d7-13","q":"次のうち、フェーリング反応陽性のものはどれか。","a":"ホルムアルデヒド","w":["エタノール","メタノール","酢酸","酢酸エチル"],"e":"ホルムアルデヒドはアルデヒド基をもつのでフェーリング反応陽性（赤色のCu₂O）。"},{"id":"d7-14","q":"次のうち、フェーリング反応陽性のものはどれか。","a":"ギ酸","w":["エタノール","メタノール","酢酸","酢酸エチル"],"e":"ギ酸はアルデヒド基をもつので還元性があり、フェーリング液を還元する。酢酸はもたない。"},{"id":"d7-15","q":"次のうち、フェーリング反応陰性のものはどれか。","a":"エタノール","w":["ギ酸エチル","アセトアルデヒド","ホルムアルデヒド"],"e":"エタノールはアルデヒド基をもたないので陰性。ギ酸エチル・アセトアルデヒド・ホルムアルデヒドはアルデヒド基の構造をもつ。"},{"id":"d7-16","q":"次のうち、フェーリング反応陰性のものはどれか。","a":"酢酸","w":["ギ酸","アセトアルデヒド","ホルムアルデヒド"],"e":"酢酸はアルデヒド基をもたないので陰性。ギ酸はアルデヒド基をもつので陽性。"},{"id":"d7-17","q":"次のうち、炭酸水素ナトリウムを加えたときに、二酸化炭素を発生するものはどれか。","a":"酢酸","w":["エタノール","アセトアルデヒド","酢酸エチル","ジエチルエーテル"],"e":"NaHCO₃でCO₂を出すのは−COOHをもつカルボン酸（弱酸の遊離）。酢酸だけが当てはまる。アルコール・アルデヒド・エステル・エーテルは酸性ではない。"},{"id":"d7-18","q":"次のうち、炭酸水素ナトリウムを加えたときに、二酸化炭素を発生するものはどれか。","a":"ギ酸","w":["メタノール","ホルムアルデヒド","酢酸エチル","ジメチルエーテル"],"e":"ギ酸はカルボン酸なのでNaHCO₃と反応してCO₂を出す。メタノール・ホルムアルデヒド・エステル・エーテルは中性。"},{"id":"d7-19","q":"次のうち、ヨードホルム反応陽性のものはどれか。","a":"アセトアルデヒド","w":["ホルムアルデヒド","メタノール","酢酸","酢酸エチル"],"e":"ヨードホルム反応はCH₃CO−（アセチル基）か、酸化されてそうなるCH₃CH(OH)−をもつと陽性。アセトアルデヒドCH₃CHOはもつ。ホルムアルデヒド・メタノールはCH₃CO−がない。酢酸・酢酸エチルは隣がOなので陰性。"},{"id":"d7-20","q":"次のうち、ヨードホルム反応陽性のものはどれか。","a":"アセトン","w":["ホルムアルデヒド","メタノール","酢酸","酢酸エチル"],"e":"アセトンCH₃COCH₃はアセチル基をもつので陽性。酢酸・酢酸エチルはC=Oの隣がOなので陰性。"},{"id":"d7-21","q":"次のうち、ヨードホルム反応陽性のものはどれか。","a":"エタノール","w":["ホルムアルデヒド","メタノール","酢酸","酢酸エチル"],"e":"エタノールCH₃CH₂OHは酸化されるとCH₃CHO（アセチル基）になるCH₃CH(OH)−構造をもつので陽性。メタノールは炭素1つでこの構造がない。"},{"id":"d7-22","q":"次のうち、ヨードホルム反応陽性のものはどれか。","a":"2-プロパノール","w":["ギ酸","1-プロパノール","酢酸","酢酸エチル"],"e":"2-プロパノールCH₃CH(OH)CH₃は酸化されるとアセトンになるので陽性。1-プロパノールは−OHが1位(末端)にありCH₃CH(OH)−をもたない。ギ酸・酢酸・酢酸エチルは陰性。"},{"id":"d7-23","q":"次のうち、ヨードホルム反応陽性のものはどれか。","a":"2-ブタノール","w":["ギ酸","1-ブタノール","酢酸","酢酸エチル"],"e":"2-ブタノールCH₃CH(OH)CH₂CH₃はCH₃CH(OH)−をもつので陽性。1-ブタノールは−OHが1位(末端)なので陰性。"},{"id":"d7-24","q":"次のうち、ヨードホルム反応陰性のものはどれか。","a":"酢酸","w":["アセトアルデヒド","アセトン","エタノール","2-プロパノール"],"e":"酢酸はCH₃CO−をもつが、C=Oの隣がO（−OH）なので反応しない。アセトアルデヒド・アセトン・エタノール・2-プロパノールは陽性。"},{"id":"d7-25","q":"次のうち、ヨードホルム反応陰性のものはどれか。","a":"メタノール","w":["アセトアルデヒド","アセトン","エタノール","2-プロパノール"],"e":"メタノールは炭素1つで、CH₃CO−もCH₃CH(OH)−もつくれないので陰性。エタノール・2-プロパノールは酸化されてアセチル基になるので陽性。"}]}]},{"key":"ino","label":"無機","icon":"⚗️","img":"","decks":[{"name":"No.1 アルカリ金属","items":[{"id":"ak0","q":"アルカリ金属は原子番号が大きくなるほど、原子半径が(ア)なり、イオン化エネルギーが(イ)なる。","a":"（ア）大きく　（イ）小さく","w":["（ア）大きく　（イ）大きく","（ア）小さく　（イ）大きく","（ア）小さく　（イ）小さく"],"e":"周期表の下の元素ほど電子殻が増えて原子半径が大きくなり、最外殻電子が原子核から遠く引きつけが弱いので、イオン化エネルギーは小さくなる（陽イオンになりやすい）。"},{"id":"ak1","q":"ナトリウムの単体の製法は？","a":"食塩の溶融塩電解","w":["アンモニアソーダ法","食塩とコークスを混ぜて高炉で還元","陽イオン交換膜法"],"e":"Naはイオン化傾向が大きく、水溶液を電気分解すると水が先に還元されてしまう。そこでNaClを融かして電気分解する（溶融塩電解）。アンモニアソーダ法はNa₂CO₃、陽イオン交換膜法はNaOHの製法。"},{"id":"ak2","q":"アルカリ金属の単体はやわらかく、融点が低く、密度も小さい。保存方法は？","a":"灯油中に保存","w":["ポリエチレン容器で保存","褐色ビンで保存","水中に保存"],"e":"アルカリ金属は水や空気中の酸素と激しく反応するので、灯油（石油）中に保存する。水中に保存するのは黄リン、褐色ビンは光で分解する物質、ポリエチレン容器はフッ化水素酸など。"},{"id":"ak3","q":"アルカリ金属の単体は(ア)と激しく反応し、(イ)を発生する。","a":"(ア)水　(イ)水素","w":["(ア)水酸化ナトリウム　(イ)水素","(ア)水素　(イ)水","(ア)酸素　(イ)水酸化ナトリウム"],"e":"アルカリ金属は冷水と激しく反応し、H₂を出す（2Na＋2H₂O→2NaOH＋H₂）。水酸化ナトリウムは生成物で、反応相手ではない。"},{"id":"ak4","q":"アルカリ金属の酸化物は(ア)酸化物で、水と容易に反応し、(イ)を生成する。","a":"(ア)塩基性　(イ)水酸化物","w":["(ア)酸性　(イ)オキソ酸","(ア)塩基性　(イ)オキソ酸","(ア)酸性　(イ)水酸化物"],"e":"金属の酸化物は塩基性酸化物。水と反応して水酸化物（塩基）になる（Na₂O＋H₂O→2NaOH）。オキソ酸ができるのは酸性酸化物（非金属の酸化物）。"},{"id":"ak5","q":"アルカリ金属の水酸化物は強い塩基性を示し、(ア)を吸収し、(イ)を生成する。","a":"(ア)二酸化炭素　(イ)炭酸塩","w":["(ア)酸素　(イ)酸化物","(ア)二酸化炭素　(イ)酸化物","(ア)酸素　(イ)炭酸塩"],"e":"強塩基は酸性酸化物のCO₂を吸収して炭酸塩になる（2NaOH＋CO₂→Na₂CO₃＋H₂O）。酸素とは反応しない。"},{"id":"ak6","q":"水酸化ナトリウムの工業的製法は何か。","a":"イオン交換膜法","w":["アンモニアソーダ法","食塩の溶融塩電解","接触法","ハーバー・ボッシュ法"],"e":"NaOHは陽イオン交換膜で仕切って食塩水を電気分解して作る（イオン交換膜法）。陰極側でH₂OがH₂とOH⁻になり、Na⁺が膜を通ってきてNaOHになる。アンモニアソーダ法はNa₂CO₃、溶融塩電解はNa単体。"},{"id":"ak7","q":"炭酸ナトリウムの工業的製法は？","a":"アンモニアソーダ法","w":["イオン交換膜法","食塩の溶融塩電解","接触法","ハーバー・ボッシュ法"],"e":"Na₂CO₃はアンモニアソーダ法（ソルベー法）で作る。イオン交換膜法はNaOH、接触法は硫酸、ハーバー・ボッシュ法はNH₃。"},{"id":"ak8","q":"飽和の食塩水にアンモニアを吸収させてから二酸化炭素を吹き込むと、（ア）が生成し、その後(ア)を加熱すると、(イ)が生成する。","a":"(ア)炭酸水素ナトリウム　(イ)炭酸ナトリウム","w":["(ア)炭酸ナトリウム　(イ)炭酸水素ナトリウム","(ア)水酸化ナトリウム　(イ)炭酸ナトリウム","(ア)炭酸ナトリウム　(イ)水酸化ナトリウム"],"e":"溶解度の小さいNaHCO₃が先に析出し（NaCl＋NH₃＋CO₂＋H₂O→NaHCO₃＋NH₄Cl）、それを加熱するとNa₂CO₃になる（2NaHCO₃→Na₂CO₃＋CO₂＋H₂O）。順番が逆にはならない。"},{"id":"ak9","q":"水酸化ナトリウムの固体は(ア)があり、また空気中の(イ)を吸収する。","a":"(ア)潮解性　(イ)二酸化炭素","w":["(ア)潮解性　(イ)酸素","(ア)風解性　(イ)酸素","(ア)風解性　(イ)二酸化炭素"],"e":"NaOHの固体は潮解性（空気中の水を吸って溶ける）をもち、さらにCO₂を吸収してNa₂CO₃になる。風解は水和水を失う現象で、Na₂CO₃・10H₂Oなどで起こる。O₂とは反応しない。"},{"id":"ak10","q":"炭酸水素ナトリウムNaHCO₃は水に溶かすと何性を示すか。","a":"塩基性","w":["酸性","中性"],"e":"NaHCO₃は弱酸（炭酸）と強塩基（NaOH）からできた塩なので、水溶液は弱い塩基性（HCO₃⁻＋H₂O⇄H₂CO₃＋OH⁻）。"},{"id":"ak11","q":"炭酸ナトリウムは何の原料として用いられるか。","a":"ガラス","w":["肥料","ベーキングパウダー","セッコウ","X線の造影剤"],"e":"Na₂CO₃はガラスの原料（ケイ砂SiO₂と反応させる）。肥料は過リン酸石灰など、ベーキングパウダーはNaHCO₃、セッコウはCaSO₄・2H₂O、X線造影剤はBaSO₄。"},{"id":"ak12","q":"炭酸ナトリウム十水和物を空気中に放置すると、どのような現象が起きるか。","a":"風解","w":["潮解","融解","昇華"],"e":"Na₂CO₃・10H₂Oは空気中で水和水を失い一水和物になる（風解）。潮解は空気中の水を吸って溶けること（NaOH・CaCl₂）。昇華は固体→気体。"},{"id":"ak13","q":"アルカリ金属の中で、(ア)はイオン半径が小さく、密度が小さいため、小型で軽量化しやすく、単位重量当たりの電池容量を増やすことができる。とくにスマートフォンや電気自動車には(ア)を用いた(イ)が二次電池として使われている。","a":"(ア)リチウム　(イ）リチウムイオン電池","w":["(ア)ナトリウム　(イ）ナトリウムイオン電池","(ア)ナトリウム　(イ）ナトリウム電池","(ア)リチウム　(イ）リチウム電池"],"e":"Liは最も軽い金属で、リチウムイオン電池は軽く電圧が高い（約4V）二次電池。リチウム電池は一次電池なので、充電して使う二次電池には当たらない。"},{"id":"ak14","q":"炎色反応を示す元素と色の組み合わせが正しいものを選べ。","a":"リチウム Li：赤　 カリウム　K :赤紫","w":["リチウム Li：赤　 ナトリウム　Na :赤紫","カリウム K：青　 ナトリウム　Na :黄","カリウムK :青　ナトリウム　Na:赤","リチウム Li：緑　 ナトリウム　Na :黄"],"e":"炎色反応は Li 赤、Na 黄、K 赤紫。Naが赤紫、Kが青、Liが緑などは誤り（緑はCu・Ba、青はCs）。"}]},{"name":"No.2 アルカリ土類金属","items":[{"id":"ae0","q":"アルカリ土類金属は周期表の(ア)族に属する元素である。価電子数は(イ)である。","a":"（ア）２　（イ）２","w":["（ア）１　（イ）1","（ア）１7　（イ）17","（ア）１8　（イ）０"],"e":"アルカリ土類金属は2族で、価電子は2個（2価の陽イオンになる）。1族はアルカリ金属、17族はハロゲン、18族は貴ガス。"},{"id":"ae1","q":"アルカリ土類金属の単体であるカルシウムは(ア)と激しく反応し、(イ)を発生する。","a":"(ア)水　(イ)水素","w":["(ア)水酸化ナトリウム　(イ)水素","(ア)水素　(イ)水","(ア)酸素　(イ)水酸化カルシウム"],"e":"Caは冷水と反応し、H₂を出してCa(OH)₂になる（Ca＋2H₂O→Ca(OH)₂＋H₂）。NaOHとは反応しない。"},{"id":"ae2","q":"塩化カルシウムは潮解性があり、(ア)剤として用いられる。 また溶解による発熱量が大きく、凝固点降下の影響も大きいため、(イ)剤として用いられる。","a":"(ア)乾燥　(イ)融雪","w":["(ア)酸化　(イ)還元","(ア)融雪　(イ)乾燥","(ア)還元　(イ)酸化"],"e":"CaCl₂は潮解性があり、乾燥剤として用いられる。溶けるときの発熱と凝固点降下で雪をとかすので融雪剤に使う。これは酸化・還元ではない。"},{"id":"ae3","q":"アルカリ土類金属の酸化物の融点はアルカリ金属の酸化物の融点と比べ(ア)。これはアルカリ土類金属の陽イオンの方が、電荷が(イ)ためである。","a":"(ア)高い　(イ)大きい","w":["(ア)低い　(イ)小さい","(ア)低い　(イ)大きい","(ア)高い　(イ)小さい"],"e":"イオン間のクーロン力は電荷に比例する。2族のイオンは＋2で1族の＋1より電荷が大きく、結合が強いので融点が高い。"},{"id":"ae4","q":"酸化カルシウムCaOは(ア)と呼ばれ、水に溶かすと激しく発熱し、水酸化カルシウムCa(OH)₂になる。水酸化カルシウムは(イ)と呼ばれる。","a":"(ア)生石灰　(イ)消石灰","w":["(ア)消石灰　(イ)生石灰"],"e":"CaO＝生石灰（水を加えると発熱）、Ca(OH)₂＝消石灰（水溶液が石灰水）。"},{"id":"ae5","q":"アルカリ土類金属の酸化物は(ア)酸化物で、水と容易に反応し、(イ)を生成する。","a":"(ア)塩基性　(イ)水酸化物","w":["(ア)酸性　(イ)オキソ酸","(ア)塩基性　(イ)オキソ酸","(ア)酸性　(イ)水酸化物"],"e":"金属の酸化物は塩基性酸化物で、水と反応して水酸化物になる（CaO＋H₂O→Ca(OH)₂）。オキソ酸ができるのは酸性酸化物（非金属の酸化物）。"},{"id":"ae6","q":"生石灰を水に溶かすと何が生成するか。","a":"消石灰","w":["石灰石","ソーダ石灰","大理石","セッコウ"],"e":"生石灰CaO＋H₂O→Ca(OH)₂（消石灰）。石灰石・大理石はCaCO₃、セッコウはCaSO₄・2H₂O、ソーダ石灰はCaOとNaOHの混合物。"},{"id":"ae7","q":"石灰石を加熱すると固体として何が生成するか。","a":"生石灰","w":["消石灰","大理石","ソーダ石灰","セッコウ"],"e":"石灰石CaCO₃を加熱すると CaCO₃→CaO＋CO₂ で、固体として生石灰CaOが残る。消石灰はCa(OH)₂、大理石はCaCO₃そのもの。"},{"id":"ae8","q":"石灰水は何の水溶液か","a":"水酸化カルシウム","w":["炭酸カルシウム","硫酸カルシウム","塩化カルシウム"],"e":"石灰水は水酸化カルシウムCa(OH)₂の水溶液。CaCO₃・CaSO₄は水に溶けにくい。CaCl₂は溶けるが石灰水とは呼ばない。"},{"id":"ae9","q":"石灰水に二酸化炭素を通じると何が生成するか。","a":"炭酸カルシウム","w":["水酸化カルシウム","酸化カルシウム","塩化カルシウム"],"e":"Ca(OH)₂＋CO₂→CaCO₃＋H₂O。水に溶けないCaCO₃ができて白く濁る。"},{"id":"ae10","q":"石灰水に二酸化炭素を通じると炭酸カルシウムが生成する。ここにさらに二酸化炭素を通じるとどうなるか。","a":"炭酸水素カルシウムが生成し溶解する。","w":["水酸化カルシウムが生成し、沈殿する。","水酸化カルシウムが生成し、溶解する。","炭酸水素カルシウムが生成し沈殿する。"],"e":"CaCO₃＋H₂O＋CO₂→Ca(HCO₃)₂。炭酸水素カルシウムは水に溶けるので、濁りが消える。水酸化カルシウムには戻らない。"},{"id":"ae11","q":"CaSO₄・2H₂Oは(ア)の主成分である。これを焼くと、CaSO₄・1/２H₂Oとあらわされる(イ)となる。(イ)に適量の水を加えると、体積を増しながら硬化して、再び(ア)となる。","a":"(ア)セッコウ　(イ)焼きセッコウ","w":["(ア)焼きセッコウ　(イ)セッコウ"],"e":"CaSO₄・2H₂Oがセッコウ。焼いて水和水を減らしたCaSO₄・½H₂Oが焼きセッコウ。水を加えると固まってセッコウに戻る（ギプスに利用）。"},{"id":"ae12","q":"生石灰CaOとコークスCを炉に入れて加熱すると(ア)が生成し、(ア)を水に溶かすと(イ)が発生する。","a":"(ア)カーバイド　(イ)アセチレン","w":["(ア)カーバイド　(イ)炭酸カルシウム","(ア)炭酸カルシウム　(イ)カーバイド","(ア)アセチレン　(イ)カーバイド"],"e":"CaO＋3C→CaC₂＋CO でカーバイドができ、CaC₂＋2H₂O→Ca(OH)₂＋C₂H₂ でアセチレンが出る。CaCO₃はこの反応では生成しない。"},{"id":"ae13","q":"X線の造影剤として用いられるのはどれか","a":"BaSO₄","w":["Ba(OH)₂","CaSO₄・2H₂O","CaCl₂"],"e":"BaSO₄は水にも酸にも溶けず、X線を通さないので造影剤に使う。Ba(OH)₂は水に溶けて有毒、CaSO₄・2H₂Oはセッコウ、CaCl₂は乾燥剤・融雪剤。"},{"id":"ae14","q":"過リン酸石灰は何と何の混合物か。","a":"リン酸二水素カルシウムと硫酸カルシウム","w":["リン酸と石灰石","硫酸とリン酸カルシウム","リン酸カルシウムと石灰石"],"e":"過リン酸石灰はCa(H₂PO₄)₂（リン酸二水素カルシウム）とCaSO₄の混合物で、肥料に使う。「硫酸とリン酸カルシウム」は原料で、混合物の中身ではない。"}]},{"name":"No.3 アルミニウム","items":[{"id":"q19","q":"アルミニウムは周期表の(ア)族に属する元素である。価電子数は(イ)である。","a":"(ア）１３　（イ）３","w":["(ア）3　（イ）３","(ア）１３　（イ）１３","(ア）3　（イ）１３","(ア）１２　（イ）２"],"e":"Alは13族で、価電子は3個（Al³⁺になる）。3族・12族ではない。族番号13と価電子数を混同しないこと（13族は族番号−10＝価電子数）。"},{"id":"q20","q":"アルミニウムは（ア）酸化物である。","a":"両性","w":["酸化","還元","塩基性","酸性"],"e":"Alは酸とも塩基とも反応する両性元素（ああすんなり：Al Zn Sn Pb）なので、酸化物Al₂O₃も両性酸化物。「酸化」「還元」は酸化物の分類ではない。"},{"id":"q21","q":"アルミニウムの単体は常温で(ア)と反応し、(イ)を発生する。","a":"(ア）濃水酸化ナトリウム水溶液　（イ）水素","w":["(ア）水（イ）水素","(ア）濃硝酸（イ）水素","(ア）濃水酸化ナトリウム水溶液（イ）酸素","(ア）濃硝酸（イ）二酸化窒素"],"e":"Alは両性金属なので濃NaOHaqと反応してH₂を出す（2Al＋2NaOH＋6H₂O→2Na[Al(OH)₄]＋3H₂）。常温の水とは表面の酸化被膜のため反応せず、濃硝酸では不動態になる。酸素は発生しない。"},{"id":"q22","q":"アルミニウムの単体は濃硝酸を加えると(ア)となり、侵されなくなる(一般に反応しないとされる)。","a":"不動態","w":["半導体","絶縁体","不導体","不動熊"],"e":"濃硝酸で表面にち密な酸化被膜ができ、それ以上反応しない状態を不動態という。半導体・絶縁体・不導体は電気の通しやすさの言葉。「熊」は選ぶな。"},{"id":"q23","q":"アルミニウムの表面を人口的に酸化して、ち密な酸化被膜を付けた製品を（ア）という。","a":"アルマイト","w":["ジュラルミン","アルミナ","ボーキサイト","ステンレス鋼"],"e":"Alの表面を人工的に酸化して被膜をつけたものがアルマイト。ジュラルミンはAl合金、アルミナはAl₂O₃、ボーキサイトはAlの原料鉱石、ステンレス鋼はFe・Cr・Niの合金。"},{"id":"q24","q":"ジュラルミンはアルミニウムと（ア）と（イ）とマンガンの合金である。","a":"(ア）銅（イ）マグネシウム","w":["(ア）銅（イ）鉄","(ア）マグネシウム（イ）クロム","(ア）鉄（イ）マグネシウム","(ア）銅（イ）クロム"],"e":"ジュラルミンはAlにCu・Mg（＋Mn）を加えた合金。軽くて強く航空機に使う。鉄やクロムは入らない（Fe・Cr・Niはステンレス鋼）。"},{"id":"q25","q":"（ア） に不純物としてCr³⁺を含むとルビー、Fe³⁺(もしくはTi³⁺)を含むとサファイヤとして産出する。","a":"酸化アルミニウム","w":["水酸化アルミニウム","酸化鉄","塩化アルミニウム","ミョウバン"],"e":"酸化アルミニウムAl₂O₃にCr³⁺が混じるとルビー、Fe³⁺やTi³⁺が混じるとサファイア。宝石は硬い酸化物の結晶で、水酸化物・塩化物・ミョウバンではない。"},{"id":"q26","q":"ミョウバンに含まれない元素はどれか、1つ選べ","a":"N","w":["S","Al","K","O"],"e":"ミョウバンはAlK(SO₄)₂・12H₂O。含まれる元素はAl・K・S・O・H で、Nは含まない。"},{"id":"q27","q":"ミョウバンの水和水の数はいくつか","a":"12","w":["1","5","10","16"],"e":"ミョウバンはAlK(SO₄)₂・12H₂Oで、水和水は12。5はCuSO₄・5H₂O、10はNa₂CO₃・10H₂Oの水和水の数。"},{"id":"q28","q":"単体のアルミニウムの原料となる鉱物はどれか","a":"ボーキサイト","w":["ジュラルミン","アルミナ","アルマイト","氷晶石"],"e":"Alの原料鉱石はボーキサイト（Al₂O₃・nH₂O）。これを精製したアルミナ(Al₂O₃)を電解する。ジュラルミン・アルマイトはAl製品、氷晶石は電解時の融剤。"},{"id":"q29","q":"単体のアルミニウムの製造時(溶融塩電解時)に酸化アルミニウムとともに入れるものは何か","a":"氷晶石","w":["ボーキサイト","ジュラルミン","アルミナ","蛍石"],"e":"Al₂O₃は融点が約2054℃と高いので、融点約1000℃の氷晶石Na₃AlF₆に溶かして低温で溶融塩電解する。蛍石はCaF₂で、HFの原料。"},{"id":"q30","q":"単体のアルミニウムを生成する際、陽極で発生する気体はなにか。","a":"CO","w":["H₂","O₂","Cl₂","NO"],"e":"陽極では O²⁻ が酸化されるが、炭素電極と反応して CO（や CO₂）になる（C＋O²⁻→CO＋2e⁻）。O₂のまま出てこない。H₂やCl₂は原料に含まれない元素なので出ない。"}]},{"name":"No.4 鉄","items":[{"id":"q94","q":"鉄は常温で塩酸と反応し、(ア)が発生する。","a":"水素","w":["塩素","塩化水素","酸素","水"],"e":"Feは水素よりイオン化傾向が大きいので、希塩酸と反応してH₂を出しFe²⁺になる（Fe³⁺にはならない）。Cl⁻は酸化されないのでCl₂は出ない。"},{"id":"q95","q":"トタンは鉄の表面を何で覆ったものか","a":"亜鉛","w":["スズ","銅","クロム","アルミニウム"],"e":"鉄の表面を亜鉛Znでめっきしたものがトタン、スズSnでめっきしたものがブリキ。"},{"id":"q96","q":"ブリキは鉄の表面を何で覆ったものか","a":"スズ","w":["銅","クロム","アルミニウム"],"e":"鉄の表面をスズSnでめっきしたものがブリキ、亜鉛Znでめっきしたものがトタン。"},{"id":"q97","q":"鉄、クロム、ニッケルの合金は何と呼ばれるか。","a":"ステンレス鋼","w":["アルマイト","ジュラルミン","ボーキサイト"],"e":"Fe・Cr・Niの合金はステンレス鋼（さびにくい）。アルマイトはAlの酸化被膜製品、ジュラルミンはAl合金、ボーキサイトはAlの鉱石。"},{"id":"q98","q":"鉄(Ⅱ)イオンの色は？","a":"淡緑色","w":["黄褐色","赤褐色","緑白色","無色"],"e":"Fe²⁺は淡緑色、Fe³⁺は黄褐色。赤褐色はFe(OH)₃、緑白色はFe(OH)₂の沈殿の色。"},{"id":"q99","q":"鉄(Ⅲ)イオンの色は？","a":"黄褐色","w":["淡緑色","赤褐色","緑白色","無色"],"e":"Fe³⁺は黄褐色、Fe²⁺は淡緑色。赤褐色はFe(OH)₃、緑白色はFe(OH)₂の沈殿の色。"},{"id":"q100","q":"Fe(OH)₂の色は？","a":"緑白色","w":["淡緑色","赤褐色","黒色","白色"],"e":"Fe(OH)₂は緑白色、Fe(OH)₃は赤褐色の沈殿。淡緑色はFe²⁺（溶液）の色。"},{"id":"q101","q":"Fe(OH)₃の色は？","a":"赤褐色","w":["淡緑色","緑白色","黒色","白色"],"e":"Fe(OH)₃は赤褐色、Fe(OH)₂は緑白色の沈殿。淡緑色はFe²⁺（溶液）の色。"},{"id":"q102","q":"K₃[Fe(CN)₆](ヘキサシアノ鉄(III)酸カリウム)は(ア)と反応し、(イ)の沈殿を生じる。","a":"(ア)Fe²⁺　(イ)濃青色","w":["(ア)Fe³⁺　(イ)濃青色","(ア)Fe²⁺　(イ)血赤色","(ア)Fe³⁺　(イ)血赤色","(ア)Fe²⁺　(イ)青白色"],"e":"K₃[Fe(CN)₆]（Fe(Ⅲ)の錯体）は、もう片方のFe²⁺と反応して濃青色沈殿（ターンブルブルー）。Ⅱ・Ⅲが「逆の組み合わせ」で濃青色になる。血赤色はFe³⁺＋KSCN。"},{"id":"q103","q":"KSCNは(ア)と反応し、(イ)になる。","a":"(ア)Fe³⁺　(イ)血赤色","w":["(ア)Fe²⁺　(イ)濃青色","(ア)Fe³⁺　(イ)濃青色","(ア)Fe²⁺　(イ)血赤色","(ア)Fe²⁺　(イ)青白色"],"e":"KSCNはFe³⁺と反応して血赤色の溶液になる。Fe²⁺とは反応しない。濃青色はヘキサシアニド鉄酸カリウムとの反応。"},{"id":"q104","q":"磁鉄鉱の化学式は？","a":"Fe₃O₄","w":["FeO","Fe₂O₃","FeO₂"],"e":"磁鉄鉱はFe₃O₄（黒さびと同じ）、赤鉄鉱はFe₂O₃（赤さびと同じ）。FeO₂という酸化鉄は通常存在しない。"},{"id":"q105","q":"赤鉄鉱の化学式は？","a":"Fe₂O₃","w":["FeO","Fe₃O₄","FeO₂"],"e":"赤鉄鉱はFe₂O₃（赤さびと同じ）、磁鉄鉱はFe₃O₄。FeO₂という酸化鉄は通常存在しない。"},{"id":"q106","q":"酸化鉄を(ア)や石灰石と共に(イ)に入れ、熱風を吹き込むと順に還元される。","a":"(ア)コークス(イ)高炉","w":["(ア)コークス(イ)転炉","(ア)カーバイド(イ)高炉","(ア)カーバイド(イ)転炉"],"e":"鉄鉱石はコークスC・石灰石と高炉（溶鉱炉）に入れる。コークスが燃えてできたCOが酸化鉄を還元する。転炉は銑鉄から鋼を作る炉。カーバイドはCaC₂。"},{"id":"q107","q":"酸化鉄の還元は(ア)で行い、銑鉄を得る。これを(イ)に移し鋼を得る。","a":"(ア)高炉(イ)転炉","w":["(ア)転炉(イ)高炉","(ア)高炉(イ)溶鉱炉","(ア)溶鉱炉(イ)高炉"],"e":"高炉で鉄鉱石を還元して銑鉄、それを転炉に移して鋼にする。溶鉱炉は高炉の別名なので、「高炉→溶鉱炉」は同じ炉の言いかえで誤り。"},{"id":"q108","q":"酸化鉄の還元で得られた鉄を(ア)といい、炭素を4%ほど含むためもろく、加工しにくい。これを転炉に移し、炭素を除いたものを(イ)という。これは炭素を0.02～2%含む。","a":"(ア)銑鉄(イ)鋼","w":["(ア)鋼(イ)銑鉄","(ア)鋼(イ)ステンレス鋼","(ア)銑鉄(イ)ステンレス鋼"],"e":"高炉で得た炭素約4％の鉄が銑鉄（もろい）。転炉でO₂を吹き込み炭素を除いたものが鋼（丈夫）。ステンレス鋼はFe・Cr・Niの合金。"},{"id":"q109","q":"純度をあげるために、銑鉄を(ア)に入れ、(イ)を送り込む。","a":"(ア)転炉(イ)酸素","w":["(ア)転炉(イ)二酸化炭素","(ア)高炉(イ)酸素","(ア)高炉(イ)二酸化炭素"],"e":"銑鉄を転炉に入れ、酸素を吹き込んで炭素をCO₂として除き鋼にする。CO₂を送り込んでも炭素は除けない。高炉は鉄鉱石を還元する炉。"},{"id":"q110","q":"鉄の製錬中に、鉄鉱石中の不純物が主にケイ酸塩として出てくる。これを何というか。","a":"スラグ","w":["銑鉄","鋼","ステンレス鋼","ダスト"],"e":"鉄鉱石中のケイ酸塩などの不純物は、石灰石由来のCaOと反応してCaSiO₃などになり除かれる。これがスラグ。銑鉄・鋼は鉄そのもの。"}]},{"name":"No.5 銅","items":[{"id":"q123","q":"銅イオンは(ア)と（イ）をとる","a":"（ア）＋１（イ）＋２","w":["（ア）＋2（イ）＋３","（ア）＋１（イ）＋３","（ア）＋２（イ）＋４","（ア）＋１（イ）＋４"],"e":"銅は＋1（Cu₂Oなど）と＋2（CuO、Cu²⁺）をとる。＋3・＋4はとらない。"},{"id":"q124","q":"全元素中、銅の（ア）は銀についで二番目である。銀より安価で電線に用いられる。","a":"電気伝導性","w":["密度","融点","延性","展性"],"e":"銅の電気伝導性はAgに次いで2番目で、Agより安いので電線に使う。展性・延性はAu・Agに次いで3番目。"},{"id":"q125","q":"銅の展性・延性は全元素中何番目か","a":"3番目","w":["1番目","2番目","4番目","7番目"],"e":"展性・延性は Au＞Ag＞Cu の順で、銅は3番目。電気伝導性はAgに次いで2番目なので混同しないこと。"},{"id":"q126","q":"酸化銅(Ⅰ)は(ア)、酸化銅(Ⅱ)は(イ)である。","a":"（ア）赤色（イ）黒色","w":["（ア）赤色（イ）白色","（ア）白色（イ）黒色","（ア）黒色（イ）赤色","（ア）黒色（イ）白色"],"e":"酸化銅(Ⅰ)Cu₂Oは赤色（フェーリング反応の沈殿）、酸化銅(Ⅱ)CuOは黒色（銅を空気中で加熱）。白色の酸化銅はない。"},{"id":"q127","q":"銅を湿った空気中に放置すると何が得られるか。","a":"緑青","w":["青緑","黄緑","緑黄","青紫"],"e":"銅を湿った空気中に置くと、CO₂・H₂Oと反応して緑青（ろくしょう）ができる。他の選択肢は色の名前で、物質名ではない。"},{"id":"q128","q":"硫酸銅五水和物は（ア）、無水物は（イ）である。","a":"（ア）青色（イ）白色","w":["（ア）白色（イ）白色","（ア）青色（イ）青色","（ア）青色（イ黒色","（ア）黒色（イ）青色"],"e":"CuSO₄・5H₂Oは青色、加熱して水和水を失った無水物CuSO₄は白色。逆に白→青の変化は水の検出に使う。黒色はCuO。"},{"id":"q129","q":"銅と亜鉛の合金を何というか。","a":"黄銅","w":["赤銅","青銅","白銅","緑銅"],"e":"Cu＋Zn＝黄銅（真鍮・ブラス）、Cu＋Sn＝青銅（ブロンズ）、Cu＋Ni＝白銅。「緑銅」という合金はない（赤銅はCu＋Auの合金で高校範囲外）。"},{"id":"q130","q":"銅とスズの合金を何というか。","a":"青銅","w":["赤銅","黄銅","白銅","緑銅"],"e":"Cu＋Sn＝青銅（ブロンズ）、Cu＋Zn＝黄銅、Cu＋Ni＝白銅。「緑銅」という合金はない。"},{"id":"q131","q":"銅とニッケルの合金を何というか。","a":"白銅","w":["赤銅","青銅","黄銅","緑銅"],"e":"Cu＋Ni＝白銅（50円・100円玉）、Cu＋Zn＝黄銅、Cu＋Sn＝青銅。「緑銅」という合金はない。"},{"id":"q132","q":"銅の合金の名前と、用途の組み合わせとして、誤っているものはどれか。","a":"白銅、楽器","w":["ブラス、五円玉","青銅、ブロンズ像","白銅、50円玉","真鍮、五円玉"],"e":"白銅（Cu＋Ni）は50円・100円玉。楽器に使うのは黄銅（真鍮・ブラス）。ブラス・真鍮は黄銅の別名で五円玉に使う。"},{"id":"q133","q":"銅の合金の名前と、用途の組み合わせとして、誤っているものはどれか。","a":"黄銅、10円玉","w":["ブラス、五円玉","青銅、ブロンズ像","白銅、100円玉","真鍮、五円玉"],"e":"10円玉は青銅（ブロンズ）。黄銅（真鍮・ブラス）は五円玉や楽器。白銅は50円・100円玉。"},{"id":"q134","q":"銅の合金の名前と、用途の組み合わせとして、誤っているものはどれか。","a":"青銅、50円玉","w":["ブラス、五円玉","青銅、ブロンズ像","白銅、100円玉","真鍮、五円玉"],"e":"50円玉は白銅（Cu＋Ni）。青銅はブロンズ像や10円玉。ブラス・真鍮は黄銅の別名で五円玉。"},{"id":"q135","q":"銅（Ⅱ）イオンを含む水溶液にアンモニア水を”少量”加えると(ア)が沈殿する。(ア)の色は（イ）である。","a":"（ア）水酸化銅（イ）青白色","w":["（ア）水酸化銅（イ）深青色","（ア）水酸化銅（イ）濃青色","（ア）テトラアンミン銅イオン（イ）青白色","（ア）テトラアンミン銅イオン（イ）深青色"],"e":"少量のアンモニア水ではOH⁻が生じ、青白色のCu(OH)₂が沈殿する。過剰に加えると深青色の[Cu(NH₃)₄]²⁺になって溶ける。"},{"id":"q136","q":"銅（Ⅱ）イオンを含む水溶液にアンモニア水を”多量”加えると(ア)が生成する。(ア)の水溶液の色は（イ）である。","a":"（ア）テトラアンミン銅イオン（イ）深青色","w":["（ア）水酸化銅（イ）深青色","（ア）水酸化銅（イ）濃青色","（ア）テトラアンミン銅イオン（イ）青白色","（ア）水酸化銅（イ）青白色"],"e":"過剰のアンモニア水でCu(OH)₂が溶け、深青色のテトラアンミン銅(Ⅱ)イオン[Cu(NH₃)₄]²⁺になる。青白色は少量のときの沈殿Cu(OH)₂の色。"},{"id":"q137","q":"純度約99％の銅を何というか。","a":"粗銅","w":["純銅","黄銅","青銅"],"e":"黄銅鉱を還元して得た約99％の銅が粗銅。電解精錬で99.99％以上にしたものが純銅。黄銅・青銅は合金。"},{"id":"q138","q":"純度約99.99％の銅を何というか。","a":"純銅","w":["粗銅","白銅","黄銅"],"e":"電解精錬で得た99.99％以上の銅が純銅。粗銅は約99％。白銅・黄銅は合金。"},{"id":"q139","q":"銅の電解精錬では、陽極になにを用いるか","a":"粗銅","w":["純銅","黄銅","青銅","白銅"],"e":"電解精錬では陽極に粗銅、陰極に純銅を使う。陽極で粗銅のCuが溶け出し、陰極に純銅が析出する。他は合金。"},{"id":"q140","q":"銅の電解精錬では粗銅に含まれる（ア）は溶液中に溶けだし、（イ）は陽極泥となって沈殿する。（ア）（イ）の組み合わせとして、最も適当なものを選べ。","a":"(ア)ニッケル(イ)銀","w":["(ア)ニッケル(イ)亜鉛","(ア)銀(イ)ニッケル","(ア)金(イ)銀","(ア)銅(イ)銅"],"e":"Cuよりイオン化傾向が大きい金属（Ni・Znなど）はイオンとして溶け出し、小さい金属（Ag・Au）は陽極泥になる。亜鉛も溶け出す側、金・銀は両方とも陽極泥。"},{"id":"q141","q":"銅の電解精錬ではイオン化傾向の小さい金属は酸化されず、そのまま電極下に沈む。これを何というか","a":"陽極泥","w":["陰極泥","スラグ","粗銅","純銅"],"e":"イオン化傾向の小さいAu・Agなどは酸化されず、陽極の下にたまる。これを陽極泥という。「陰極泥」はない。スラグは鉄の製錬で出る不純物。"}]},{"name":"No.6 銀・クロム","items":[{"id":"q112","q":"銀イオンは(ア)をとる","a":"（ア）＋１","w":["（ア）＋2","（ア）＋３","（ア）＋４"],"e":"銀は主に＋1（Ag⁺）をとる。「Ag⁺、2+じゃないよ」。"},{"id":"q113","q":"全元素中、銀の（ア）は最も高い。","a":"電気伝導性","w":["密度","融点","延性","展性"],"e":"銀は電気伝導性（と熱伝導性）が全金属で最大。密度・融点はもっと大きい金属がある（例：融点はW）。展性・延性の最大はAu。"},{"id":"q114","q":"銀の展性・延性は全元素中何番目か","a":"２番目","w":["1番目","３番目","4番目","7番目"],"e":"展性・延性は Au＞Ag＞Cu の順で、銀は2番目。1番目は金。"},{"id":"q115","q":"銀のハロゲン化物は（ア）をもち、写真の現像に使われる。（イ）で保存する。","a":"（ア）感光性（イ）褐色ビン","w":["（ア）酸化力（イ）ガラスビン","（ア）自然発火性（イ）水中","（ア）水に入れると発火する性質（イ）灯油中","（ア）ガラスを溶かす性質（イ）ポリエチレン容器"],"e":"銀のハロゲン化物は光で分解する感光性があり、写真に使う。光を防ぐため褐色ビンに保存。ガラスを溶かすのはHF（ポリエチレン容器）、自然発火は黄リン（水中）、水と反応するのはNa（灯油（石油）中）。"},{"id":"q116","q":"AgFは(ア)で水に（イ）。","a":"(ア)黄色(イ)溶ける","w":["(ア)白色(イ)溶ける","(ア)淡黄色(イ)溶ける","(ア)黄色(イ)溶けない","(ア)白色(イ)溶けない"],"e":"ハロゲン化銀のうちAgFだけは水に溶ける黄色の固体。AgClは白、AgBrは淡黄、AgIは黄色の沈殿。"},{"id":"q117","q":"AgClは(ア)で水に（イ）。","a":"(ア)白色(イ)溶けない","w":["(ア)白色(イ)溶ける","(ア)淡黄色(イ)溶ける","(ア)黄色(イ)溶けない","(ア)黄色(イ)溶ける"],"e":"AgClは白色沈殿で水に溶けない（アンモニア水には錯イオンをつくって溶ける）。淡黄色はAgBr、黄色はAgI。水に溶けるのはAgFだけ。"},{"id":"q118","q":"AgIはNH₃過剰でも溶けず、（ア）を加えると溶ける。","a":"チオ硫酸ナトリウム","w":["水酸化ナトリウム","塩酸","硫酸","塩化ナトリウム"],"e":"AgIは過剰のNH₃でも溶けないが、チオ硫酸ナトリウムを加えると[Ag(S₂O₃)₂]³⁻をつくって溶ける。塩酸・NaClではCl⁻が加わるだけ、NaOHではAg₂Oができる方向。"},{"id":"q119","q":"Cr³⁺を含む水溶液は何色か","a":"緑色","w":["青色","橙赤色","黄褐色","黄色"],"e":"Cr³⁺は緑色。橙赤色はCr₂O₇²⁻、黄色はCrO₄²⁻、黄褐色はFe³⁺、青色はCu²⁺。"},{"id":"q120","q":"Cr₂O₇²⁻を含む水溶液は何色か","a":"橙赤色","w":["青色","緑色","黄褐色","黄色"],"e":"二クロム酸イオンCr₂O₇²⁻は橙赤色（酸性で存在、酸化剤）。塩基性にすると黄色のCrO₄²⁻になる。緑色はCr³⁺。"},{"id":"q121","q":"CrO₄²⁻を含む水溶液は何色か","a":"黄色","w":["青色","緑色","黄褐色","橙赤色"],"e":"クロム酸イオンCrO₄²⁻は黄色（塩基性で存在）。酸性にすると橙赤色のCr₂O₇²⁻になる。緑色はCr³⁺。"},{"id":"q122","q":"クロム、アルミ、鉄、ニッケルなどは、硝酸に溶けない。(ア)になるためである。","a":"不動態","w":["絶縁体","半導体","不働熊","不動体"],"e":"Al・Fe・Ni・Crは濃硝酸で表面にち密な酸化被膜ができ、不動態になる。絶縁体・半導体は電気の通しやすさの言葉。「不働熊」「不動体」は存在しない語。"}]},{"name":"No.7-1 ハロゲン（単体）","items":[{"id":"nm12","q":"ハロゲンは周期表の第何族の元素か。","a":"17","w":["1","2","18"],"e":"ハロゲン（F・Cl・Br・I）は17族。1族はアルカリ金属、2族はアルカリ土類金属、18族は貴ガス。"},{"id":"nm13","q":"ハロゲンがもつ価電子の数はいくつか。","a":"7","w":["6","1","17"],"e":"17族なので価電子は7個。あと1個電子をもらって1価の陰イオン（X⁻）になりやすい。族番号17をそのまま答えないこと。"},{"id":"nm14","q":"ハロゲンの単体について説明したものとして正しいものを選べ。","a":"二原子分子であり、有色・有毒である。","w":["単原子分子であり、有色・有毒である。","二原子分子であり、無色・無毒である。","二原子分子であり、有色・無毒である。"],"e":"ハロゲンの単体はすべて二原子分子（F₂・Cl₂…）で、有色・有毒（刺激臭）。単原子分子なのは貴ガス。"},{"id":"nm15","q":"ハロゲンの単体の融点・沸点について説明したものとして正しいものを選べ。","a":"分子量が大きいほど高い。","w":["分子量が大きいほど小さい。","分子量に依らずそれぞれほぼ同じ値となる。"],"e":"分子量が大きいほど分子間力（ファンデルワールス力）が強く、融点・沸点が高い。そのためF₂・Cl₂は気体、Br₂は液体、I₂は固体。"},{"id":"nm16","q":"ハロゲンの単体で酸化力が最も強いのは次のうちどれか。","a":"F₂","w":["Cl₂","Br₂","I₂"],"e":"酸化力は F₂＞Cl₂＞Br₂＞I₂。周期表の上ほど原子が小さく、電子を引きつけやすい。"},{"id":"nm17","q":"常温・常圧で液体のものはどれか。","a":"Br₂","w":["F₂","Cl₂","I₂"],"e":"常温で液体の単体は臭素Br₂と水銀Hgだけ。F₂・Cl₂は気体、I₂は固体。"},{"id":"nm18","q":"常温・常圧で固体のものはどれか。","a":"I₂","w":["F₂","Cl₂","Br₂"],"e":"ハロゲンの単体で常温で固体なのはI₂（昇華性あり）。F₂・Cl₂は気体、Br₂は液体。"},{"id":"nm19","q":"常温・常圧の状態で、淡黄色のものはどれか。","a":"F₂","w":["Cl₂","Br₂","I₂"],"e":"F₂は淡黄色、Cl₂は黄緑色、Br₂は赤褐色、I₂は黒紫色。下の元素ほど色が濃くなる。"},{"id":"nm20","q":"常温・常圧の状態で、黄緑色のものはどれか。","a":"Cl₂","w":["F₂","Br₂","I₂"],"e":"Cl₂は黄緑色。F₂は淡黄色、Br₂は赤褐色、I₂は黒紫色。"},{"id":"nm21","q":"常温・常圧の状態で、赤褐色のものはどれか。","a":"Br₂","w":["F₂","Cl₂","I₂"],"e":"Br₂は赤褐色の液体。F₂は淡黄色、Cl₂は黄緑色、I₂は黒紫色。"},{"id":"nm22","q":"常温・常圧の状態で、黒紫色のものはどれか。","a":"I₂","w":["F₂","Cl₂","Br₂"],"e":"I₂は黒紫色の固体。F₂は淡黄色、Cl₂は黄緑色、Br₂は赤褐色。"},{"id":"nm23","q":"次のうち、一般に反応が起こらないのはどちらか。","a":"I₂ + 2KBr → Br₂ + 2KI","w":["Cl₂ + 2KBr → Br₂ + 2KCl"],"e":"ハロゲン単体は、自分より酸化力の弱いハロゲンのイオンだけを酸化できる。I₂はBr₂より酸化力が弱いのでBr⁻を酸化できない。Cl₂はBr⁻を酸化できるので反応は起こる。"},{"id":"nm24","q":"ヨウ素デンプン反応は、デンプン水溶液をヨウ素を溶かした[A]水溶液（[B]色の液体）に入れると、[C]色になる反応である。A～Cの空欄について正しい組み合わせを選べ。","a":"A：ヨウ化カリウム　B：褐　C：青紫","w":["A：ヨウ化カリウム　B：青紫　C：褐","A：ヨウ化カリウム　B：無　C：青紫","A：ヨードホルム　B：褐　C：青紫"],"e":"I₂は水に溶けにくいが、KI水溶液にはI₃⁻となって溶け、褐色の液体になる。デンプンと青紫色になる（ヨウ素デンプン反応）。ヨードホルムCHI₃は黄色の有機化合物で別物。"},{"id":"nm25","q":"フッ素と水の反応について、正しいものはどれか。","a":"フッ化水素と酸素が生成。","w":["反応しない。","フッ化水素と過酸化水素が生成。","フッ化水素と水素及び酸素が生成。"],"e":"F₂は酸化力が非常に強く、水の酸素を酸化してO₂を出す（2F₂＋2H₂O→4HF＋O₂）。過酸化水素や水素は生じない。"},{"id":"nm26","q":"塩素の製法は、実験室では[A]に[B]を加えて加熱する。このとき、1molの塩素を得るために[C]molの[B]が必要である。A～Cの空欄について正しい組み合わせを選べ。","a":"A：酸化マンガン(Ⅳ)　B：濃塩酸　C：4","w":["A：酸化マンガン(Ⅳ)　B：希塩酸　C：2","A：塩化ナトリウム　B：希塩酸　C：2","A：塩化ナトリウム　B：濃塩酸　C：4","A：酸化マンガン(Ⅳ)　B：濃塩酸　C：2"],"e":"MnO₂＋4HCl→MnCl₂＋2H₂O＋Cl₂。Cl₂を1mol得るのにHClは4mol必要。MnO₂の酸化力は弱めなので濃塩酸を使い加熱する。NaClは塩化水素の原料。"},{"id":"nm27","q":"塩素の製法は、実験室では高度さらし粉[A]に塩酸を加えて加熱する。このとき、塩素・水及び[B]が生成する。なお、高度さらし粉の代わりに、さらし粉[C]を用いても良い。A～Cの空欄について正しい組み合わせを選べ。","a":"A：Ca(ClO)₂・2H₂O　B：塩化カルシウム　C：CaCl(ClO)・H₂O","w":["A：CaCl(ClO)・H₂O　B：塩化カルシウム　C：Ca(ClO)₂・2H₂O","A：CaCl(ClO)・2H₂O　B：塩化カルシウム　C：Ca(ClO)₂・H₂O","A：Ca(ClO)₂・2H₂O　B：水酸化カルシウム　C：CaCl(ClO)・H₂O","A：Ca(ClO)₂・H₂O　B：水酸化カルシウム　C：CaCl(ClO)・2H₂O"],"e":"高度さらし粉はCa(ClO)₂・2H₂O、さらし粉はCaCl(ClO)・H₂O。塩酸と反応してCl₂・水・塩化カルシウムを生じる（Caは塩酸と反応して塩化物になる）。水和水の数の入れ替えに注意。"},{"id":"nm28","q":"塩素水中では、塩素の一部が水と反応し、[A]と[B]を生じる。[B]は強い酸化作用があり、[C]効果のため、水道水やプールの水等に使用される。A～Cの空欄について正しい組み合わせを選べ。","a":"A：HCl　B：HClO　C：漂白・殺菌","w":["A：HClO　B：HCl　C：漂白・殺菌","A：HCl　B：HClO₃　C：漂白・殺菌","A：HClO₃　B：HCl　C：漂白・殺菌","A：HCl　B：HClO　C：脱水・吸湿"],"e":"Cl₂＋H₂O⇄HCl＋HClO。次亜塩素酸HClOは強い酸化作用をもち、漂白・殺菌に使う。HClO₃は塩素酸。脱水・吸湿は濃硫酸の性質。"}]},{"name":"No.7-2 ハロゲン（化合物）","items":[{"id":"nm29","q":"次のハロゲン化水素のうち、弱酸はどれ。","a":"HF","w":["HCl","HBr","HI"],"e":"HFだけが弱酸。Fは小さく電気陰性度が大きいので、H−Fの結合が強く電離しにくい（水素結合も影響）。HCl・HBr・HIは強酸。"},{"id":"nm30","q":"次のハロゲン化水素のうち、最も強い酸はどれ。","a":"HI","w":["HCl","HBr","HF"],"e":"酸の強さは HF≪HCl＜HBr＜HI。下の元素ほど原子が大きくH−Xの結合が弱いので、H⁺を放しやすい。"},{"id":"nm31","q":"次のハロゲン化水素のうち、沸点が最も高い(約20℃)のものはどれ。","a":"HF","w":["HCl","HBr","HI"],"e":"HFは分子量が最小だが、分子間に水素結合をつくるので沸点が高い（約20℃）。他は分子量が大きいほど沸点が高くなるが、HFよりは低い。"},{"id":"nm32","q":"ハロゲン化水素のうち、[A]はガラスを溶かすため、[B]に保存する。A・Bの空欄について正しい組み合わせを選べ。","a":"A：HF　B：ポリエチレン製の容器","w":["A：HF　B：褐色のビン","A：HF　B：水中","A：HI　B：ポリエチレン製の容器","A：HI　B：褐色のビン"],"e":"フッ化水素酸HFはガラス(SiO₂)を溶かすので、ポリエチレン容器に保存する。褐色ビンは光で分解する物質（硝酸・AgBrなど）、水中は黄リン。"},{"id":"nm33","q":"フッ化水素の製法は、実験室では[A]に[B]を加えて加熱する。[B]を用いるのは、[B]の[C]の性質を利用するためである。A～Cの空欄について正しい組み合わせを選べ。","a":"A：ホタル石　B：濃硫酸　C：不揮発性の酸","w":["A：ホタル石　B：希硫酸　C：強酸","A：ホタル石　B：濃硫酸　C：酸化作用","A：水ガラス　B：濃硫酸　C：不揮発性の酸","A：水ガラス　B：希硫酸　C：強酸"],"e":"ホタル石CaF₂に濃硫酸を加えて加熱する。不揮発性の酸（濃硫酸）が揮発性の酸（HF）を追い出す反応。希硫酸では加熱しても追い出せない。水ガラスはケイ酸ナトリウム。"},{"id":"nm34","q":"フッ化水素の製法は、実験室では[A]に[B]を加えて加熱する。副生成物として、[C]が生じる。A～Cの空欄について正しい組み合わせを選べ。","a":"A：蛍石　B：濃硫酸　C：硫酸カルシウム","w":["A：蛍石　B：希硫酸　C：硫酸カルシウム","A：大理石　B：濃硫酸　C：硫酸カルシウム","A：大理石　B：濃硝酸　C：硝酸カルシウム","A：CaF　B：濃硝酸　C：硝酸カルシウム"],"e":"CaF₂＋H₂SO₄→CaSO₄＋2HF。副生成物は硫酸カルシウム。大理石はCaCO₃でFを含まない。「CaF」はCaが2価なので存在しない（正しくはCaF₂）。"},{"id":"nm35","q":"フッ化水素酸により石英[A]が溶けると、[B]が生じる。A・Bの空欄について正しい組み合わせを選べ。","a":"A：SiO₂　B：H₂SiF₆(ヘキサフルオロケイ酸)","w":["A：SiO₄　B：H₂SiF₆(ヘキサフルオロケイ酸)","A：SiO₂　B：H₂Si₂F₆(ヘキサフルオロケイ酸)","A：SiO₂　B：H₂SiF₄(ヘキサフルオロケイ酸)","A：SiO₄　B：H₂Si₂F₆(ヘキサフルオロケイ酸)"],"e":"石英はSiO₂（SiO₄はケイ酸塩の単位で別物）。HFと反応してヘキサフルオロケイ酸H₂SiF₆ができる。ヘキサ＝6なのでFは6個、Siは1個。"},{"id":"nm36","q":"塩化水素の製法は、実験室では塩化ナトリウムに[A]を加えて加熱する。[A]を用いるのは、[A]の[B]の性質を利用するためであり、塩化水素と同時に[C]が生じる。A～Cの空欄について正しい組み合わせを選べ。","a":"A：濃硫酸　B：不揮発性の酸　C：硫酸水素ナトリウム","w":["A：濃硫酸　B：酸化作用　C：硫酸水素ナトリウム","A：濃硫酸　B：酸化作用　C：硫酸ナトリウム","A：濃硫酸　B：不揮発性の酸　C：硫酸ナトリウム","A：希硫酸　B：強酸　C：硫酸ナトリウム"],"e":"不揮発性の濃硫酸が揮発性のHClを追い出す（NaCl＋H₂SO₄→NaHSO₄＋HCl）。H⁺を1つ渡すだけなので、硫酸ナトリウムではなく硫酸水素ナトリウムになる。酸化作用は関係しない。"},{"id":"nm37","q":"塩化水素はある気体を接触させると白煙を生じる。この気体として適当なものはどれ。","a":"アンモニア","w":["二酸化炭素","一酸化炭素","二酸化窒素"],"e":"HCl＋NH₃→NH₄Cl。生じた塩化アンモニウムの細かい固体が白煙に見える。酸性気体と塩基性気体の中和なので、相手は塩基性のNH₃だけ。"},{"id":"nm38","q":"次のハロゲン化銀のうち、水に溶けるのはどれ。","a":"AgF","w":["AgCl","AgBr","AgI"],"e":"ハロゲン化銀のうちAgFだけは水に溶ける（黄色の固体）。AgClは白、AgBrは淡黄、AgIは黄色の沈殿。"},{"id":"nm39","q":"AgClの沈殿の色はどれ。","a":"白","w":["淡黄","黄","黒"],"e":"AgClは白色、AgBrは淡黄色、AgIは黄色。下のハロゲンほど色が濃くなる。黒色はAg₂S。"},{"id":"nm40","q":"AgBrの沈殿の色はどれ。","a":"淡黄","w":["白","黄","黒"],"e":"AgBrは淡黄色。AgClは白色、AgIは黄色、黒色はAg₂S。"},{"id":"nm41","q":"AgIの沈殿の色はどれ。","a":"黄","w":["淡黄","白","黒"],"e":"AgIは黄色（NH₃過剰でも溶けない）。AgClは白色、AgBrは淡黄色。"},{"id":"nm42","q":"次のハロゲン化鉛の沈殿のうち、白色ではなく黄色のものはどれ。","a":"PbI₂","w":["PbF₂","PbCl₂","PbBr₂"],"e":"PbI₂は黄色沈殿。PbF₂・PbCl₂・PbBr₂は白色。ヨウ化物は色がつきやすい（AgIも黄色）。"}]},{"name":"No.8 酸素","items":[{"id":"nm114","q":"酸素は周期表の何族に属するか。","a":"16","w":["17","15","14"],"e":"酸素Oは16族（硫黄と同じ）。17族はハロゲン、15族はN・P。"},{"id":"nm115","q":"酸素がもつ価電子はどれ。","a":"6","w":["7","2","1"],"e":"16族なので価電子は6個。2個もらってO²⁻になりやすい（酸化数−2）。"},{"id":"nm116","q":"酸素の同素体は何か。","a":"オゾン（O₃)","w":["オゾン（O₄）","オキソニウム（O₃）","オキソニウム（O₄）"],"e":"酸素の同素体はオゾンO₃。O₄は高校の範囲では扱わない。オキソニウムはH₃O⁺（オキソニウムイオン）の名前で、同素体ではない。"},{"id":"nm117","q":"酸素の製法は、実験室では [ A ] に [ B ] を触媒として加える。副生成物は [ C ] である。A～Cに当てはまる組み合わせはどれか。","a":"A：過酸化水素　B：酸化マンガン(Ⅳ)、C：水","w":["A：過酸化水素　B：酸化バナジウム(Ⅴ)、C：水","A：水　B：酸化マンガン(Ⅳ)、C：水素","A：水　B：酸化バナジウム(Ⅴ)、C：水素","A：過酸化水素　B：酸化マンガン(Ⅳ)、C：水素"],"e":"2H₂O₂→2H₂O＋O₂（触媒MnO₂）。副生成物は水。水にMnO₂を加えても分解しない。V₂O₅は接触法の触媒。"},{"id":"nm118","q":"酸素の製法は、実験室では [ A ] に [ B ] を触媒として加える。副生成物は [ C ] である。A～Cに当てはまる組み合わせはどれか。","a":"A：KClO₃(塩素酸カリウム)　B：酸化マンガン(Ⅳ)、C：KCl","w":["A：KClO₃(塩素酸カリウム)　B：酸化バナジウム(V)、C：KCl","A：KClO₃(過塩素酸カリウム)　B：酸化マンガン(Ⅳ)、C：KCl","A：KClO₃(過塩素酸カリウム)　B：酸化バナジウム(V)、C：KCl"],"e":"2KClO₃→2KCl＋3O₂（触媒MnO₂）。KClO₃は塩素酸カリウム、過塩素酸カリウムはKClO₄。V₂O₅は接触法の触媒。"},{"id":"nm119","q":"オゾンの製法は、酸素中で[A]をおこなうか、酸素に強い[B]を照射して生成する。A・Bの空欄について正しい組み合わせを選べ。","a":"A：無声放電　B：紫外線","w":["A：無声放電　B：赤外線","A：乾留　B：赤外線","A：乾留　B：紫外線"],"e":"酸素中で無声放電を行うか、強い紫外線を当てるとO₃ができる（3O₂→2O₃）。成層圏のオゾン層も紫外線でできる。乾留は空気を断って加熱すること。"},{"id":"nm120","q":"オゾンの色として最も適当なものはどれか。","a":"淡青色","w":["深青色","黄緑色","淡黄色"],"e":"オゾンは淡青色・特異臭の気体。黄緑色はCl₂、淡黄色はF₂、深青色は[Cu(NH₃)₄]²⁺の溶液の色。"},{"id":"nm121","q":"オゾンは[A]臭をもつ、[B]毒の気体である。A・Bの空欄について正しい組み合わせを選べ。","a":"A：特異　B：有","w":["A：特異　B：無","A：腐乱　B：無","A：腐乱　B：有"],"e":"オゾンは特異臭（生ぐさいにおい）をもつ有毒気体。強い酸化作用があり殺菌に使う。腐卵臭はH₂S。"},{"id":"nm122","q":"水に溶けて[A]を生じたり、[B]と反応して塩を生じたりする酸化物を、[C]といい、例としてはCO₂、NO₂等がある。A～Cの空欄について正しい組み合わせを選べ。","a":"A：酸　B：塩基　C：酸性酸化物","w":["A：酸　B：塩基　C：塩基性酸化物","A：塩基　B：酸　C：酸性酸化物","A：塩基　B：酸　C：塩基性酸化物"],"e":"水に溶けて酸を生じたり、塩基と反応して塩をつくる酸化物が酸性酸化物（主に非金属の酸化物）。塩基性酸化物は水に溶けて塩基になり、酸と反応する（金属の酸化物）。"},{"id":"nm123","q":"二酸化窒素は次のうちどれ。","a":"酸性酸化物","w":["塩基性酸化物","両性酸化物"],"e":"NO₂は非金属の酸化物なので酸性酸化物（水に溶けて硝酸を生じる）。塩基性酸化物は主にアルカリ金属・アルカリ土類金属の酸化物。"},{"id":"nm124","q":"十酸化四リンは次のうちどれ。","a":"酸性酸化物","w":["塩基性酸化物","両性酸化物"],"e":"P₄O₁₀は非金属の酸化物なので酸性酸化物（水と反応してリン酸）。"},{"id":"nm125","q":"酸化マグネシウムは次のうちどれ。","a":"塩基性酸化物","w":["酸性酸化物","両性酸化物"],"e":"MgOは金属の酸化物なので塩基性酸化物。両性酸化物になるのは両性元素（Al・Zn・Sn・Pb）の酸化物。"},{"id":"nm126","q":"酸化鉄(Ⅲ)は次のうちどれ。","a":"塩基性酸化物","w":["酸性酸化物","両性酸化物"],"e":"Fe₂O₃は金属の酸化物で塩基性酸化物。Feは両性元素ではない（両性はAl・Zn・Sn・Pb）。"},{"id":"nm127","q":"両性酸化物は次のうちどれ。","a":"Al₂O₃","w":["SiO₂","CuO","BaO"],"e":"両性元素（ああすんなり：Al・Zn・Sn・Pb）の酸化物が両性酸化物なのでAl₂O₃。SiO₂は酸性酸化物、CuO・BaOは塩基性酸化物。"},{"id":"nm128","q":"両性酸化物は次のうちどれ。","a":"ZnO","w":["SO₂","CaO","MgO"],"e":"Znは両性元素なのでZnOは両性酸化物。SO₂は酸性酸化物、CaO・MgOは塩基性酸化物。"},{"id":"nm129","q":"塩素のオキソ酸である塩素酸はどれ。","a":"HClO₃","w":["HClO","HClO₂","HClO₄"],"e":"Oの数が少ない順に HClO 次亜塩素酸、HClO₂ 亜塩素酸、HClO₃ 塩素酸、HClO₄ 過塩素酸。「塩素酸」が基準でO₃。"},{"id":"nm130","q":"HClO₄の名称は。","a":"過塩素酸","w":["塩素酸","亜塩素酸","次亜塩素酸"],"e":"HClO₄は過塩素酸（塩素酸HClO₃よりOが1つ多い）。HClO₃ 塩素酸、HClO₂ 亜塩素酸、HClO 次亜塩素酸。"},{"id":"nm131","q":"次亜塩素酸の塩素の酸化数は[A]であり、塩素酸のそれは[B]である。酸化数が大きいほど、酸としての性質が[C]いので、[D]の方が強い酸である。A～Dの空欄について正しい組み合わせを選べ。","a":"A：+1　B：+5　C：強　D：塩素酸","w":["A：+1　B：+5　C：弱　D：次亜塩素酸","A：+1　B：+7　C：強　D：塩素酸","A：+1　B：+7　C：弱　D：次亜塩素酸"],"e":"HClOのClは＋1、HClO₃のClは＋5（＋7は過塩素酸HClO₄）。酸化数が大きくOが多いほど、O−H のH⁺が離れやすく強い酸になる。"}]},{"name":"No.9 硫黄","items":[{"id":"nm68","q":"硫黄は周期表の何族に属するか。","a":"16","w":["17","15","14"],"e":"硫黄Sは酸素と同じ16族。17族はハロゲン、15族はN・P、14族はC・Si。"},{"id":"nm69","q":"硫黄がもつ価電子はどれ。","a":"6","w":["7","2","17","16"],"e":"16族なので価電子は6個。あと2個もらってS²⁻になりやすい。族番号16・17をそのまま答えないこと。"},{"id":"nm70","q":"硫黄の同素体の中で、最も安定なものは[A]硫黄である。[A]の温度を上げていき、融解後250℃ほどにしたのち、水に入れて急冷することで[B]硫黄となる。A、Bの空欄について正しい組み合わせを選べ。","a":"A：斜方　B：ゴム状","w":["A：斜方　B：単斜","A：単斜　B：ゴム状","A：単斜　B：斜方","A：ゴム状　B：単斜"],"e":"最も安定なのは斜方硫黄。融かして250℃くらいにし、水に入れて急冷するとゴム状硫黄になる。単斜硫黄は融かした硫黄をゆっくり冷やしてできる。"},{"id":"nm71","q":"硫化水素は、[A]色・[B]臭の有毒の気体であり、火山ガスや温泉に含まれる。A・Bの空欄について正しい組み合わせを選べ。","a":"A：無　B：腐卵","w":["A：無　B：刺激","A：淡黄　B：腐卵","A：淡黄　B：刺激"],"e":"H₂Sは無色・腐卵臭（腐った卵のにおい）の有毒気体。腐卵臭はH₂Sだけ。刺激臭はSO₂やNH₃など。"},{"id":"nm72","q":"硫化水素は、水に溶けやすく[A]酸性を示す。また、強い[B]性を持ち、二酸化硫黄と反応し、[C]を生成する。A～Cの空欄について正しい組み合わせを選べ。","a":"A：弱　B：還元　C：硫黄の単体","w":["A：弱　B：還元　C：硫酸","A：弱　B：酸化　C：硫黄の単体","A：弱　B：酸化　C：硫酸","A：強　B：還元　C：硫黄の単体"],"e":"H₂Sは水に溶けて弱酸性。強い還元剤で、SO₂と反応して硫黄の単体が析出する（2H₂S＋SO₂→3S＋2H₂O）。硫酸にはならない。"},{"id":"nm73","q":"二酸化硫黄は、硫黄または[A](主成分[B])を燃焼して得られる。A・Bの空欄について正しい組み合わせを選べ。","a":"A：黄鉄鉱　B：FeS₂","w":["A：黄鉄鉱　B：FeS","A：赤鉄鉱　B：FeS","A：赤鉄鉱　B：FeS₂"],"e":"黄鉄鉱の主成分はFeS₂。燃やすとSO₂が出る。赤鉄鉱はFe₂O₃でSを含まない。FeSは硫化鉄(Ⅱ)で、H₂Sの発生に使う。"},{"id":"nm74","q":"1molの黄鉄鉱を燃焼させると、[ A ] molの二酸化硫黄が生じ、副生成物は [ B ] である。A・Bの空欄について正しい組み合わせを選べ。","a":"A：2、B：Fe₂O₃","w":["A：2、B：FeO","A：2、B：Fe₃O₄","A：1.5、B：Fe₂O₃","A：1.5、B：Fe₃O₄"],"e":"4FeS₂＋11O₂→2Fe₂O₃＋8SO₂。FeS₂ 1molからSO₂は2mol（Sが2個）。鉄は酸化されてFe₂O₃になる。"},{"id":"nm75","q":"二酸化硫黄は、実験室では[　　]と希硫酸を反応させて得られる。空欄に入る物質名はどれ。","a":"亜硫酸ナトリウム","w":["硫酸ナトリウム","銅の単体","硫酸水素ナトリウム"],"e":"Na₂SO₃＋H₂SO₄→Na₂SO₄＋H₂O＋SO₂（弱酸の遊離）。硫酸ナトリウム・硫酸水素ナトリウムは強酸の塩なのでSO₂は出ない。銅は熱濃硫酸でないと反応しない。"},{"id":"nm76","q":"二酸化硫黄は、実験室では[A]と[B]を反応させて得られる。A・Bの空欄について正しい組み合わせを選べ。","a":"A：銅の単体　B：熱濃硫酸","w":["A：銅の単体　B：濃硫酸(常温)","A：銅の単体　B：希硫酸","A：硫酸ナトリウム　B：濃硫酸(常温)","A：硫酸水素ナトリウム　B：濃硫酸(常温)"],"e":"Cu＋2H₂SO₄→CuSO₄＋2H₂O＋SO₂。熱濃硫酸の酸化作用で銅が溶ける。常温の濃硫酸・希硫酸では銅は溶けない。硫酸塩に濃硫酸を加えてもSO₂は出ない。"},{"id":"nm77","q":"二酸化硫黄は、[A]色・[B]臭の有毒の気体であり、腐食性をもつ。A・Bの空欄について正しい組み合わせを選べ。","a":"A：無　B：刺激","w":["A：無　B：腐卵","A：淡黄　B：腐卵","A：淡黄　B：刺激"],"e":"SO₂は無色・刺激臭の有毒気体。腐卵臭はH₂Sだけ。淡黄色の気体はF₂。"},{"id":"nm78","q":"二酸化硫黄は、水に溶け[A]を生じ、[B]酸性を示す。A・Bの空欄について正しい組み合わせを選べ。","a":"A：亜硫酸　B：弱","w":["A：亜硫酸　B：強","A：硫酸　B：強","A：硫酸　B：弱"],"e":"SO₂＋H₂O⇄H₂SO₃（亜硫酸）。亜硫酸は弱酸。硫酸にするにはさらに酸化が必要（H₂O₂など）。"},{"id":"nm79","q":"二酸化硫黄は、主に[A]としてはたらき、漂白剤などに用いられるが、強い[A]である[B]に対しては、[C]としてもはたらく。A～Cの空欄について正しい組み合わせを選べ。","a":"A：還元剤　B：H₂S　C：酸化剤","w":["A：還元剤　B：H₂O₂　C：酸化剤","A：酸化剤　B：H₂S　C：還元剤","A：酸化剤　B：H₂O₂　C：還元剤"],"e":"SO₂は主に還元剤（漂白に使う）。ただし、より強い還元剤であるH₂Sに対しては酸化剤としてはたらく。H₂O₂は酸化剤なので、SO₂は還元剤のまま。"},{"id":"nm80","q":"濃硫酸の工業的製法は、[A]と呼ばれ、触媒として[B]を用いる。A・Bの空欄について正しい組み合わせを選べ。","a":"A：接触法　B：V₂O₅","w":["A：接触法　B：Fe₃O₄","A：ハーバー法　B：Pt","A：ハーバー法　B：V₂O₅","A：オストワルト法　B：Fe₃O₄"],"e":"硫酸の製法は接触法で、触媒は酸化バナジウム(Ⅴ)V₂O₅。ハーバー法はNH₃（触媒Fe₃O₄）、オストワルト法は硝酸（触媒Pt）。"},{"id":"nm81","q":"接触法は、[A]を酸化バナジウム(V)を触媒に用いて[B]を生成し、[B]を濃硫酸に吸収させて[C]とし、希硫酸で薄めて濃硫酸を生成する。A～Cの空欄について正しい組み合わせを選べ。","a":"A：SO₂　B：SO₃　C：発煙硫酸","w":["A：SO₂　B：SO₃　C：熱濃硫酸","A：S　B：SO₂　C：熱濃硫酸","A：S　B：SO₂　C：発煙硫酸"],"e":"SO₂をV₂O₅触媒でSO₃にし、SO₃を濃硫酸に吸収させて発煙硫酸にしてから希硫酸で薄める。SO₃を直接水に入れると発熱が激しいため。熱濃硫酸は加熱した濃硫酸のこと。"},{"id":"nm82","q":"濃硫酸について説明したものとして、誤っているものはどれか。","a":"強酸性を示す。","w":["吸湿性を示し、乾燥剤として使われる。","脱水作用を示し、有機物から水を奪う。","不揮発性の酸であり、揮発性の酸の塩と反応し、揮発性の酸を生成させる。","加熱すると強い酸化作用を示す。"],"e":"濃硫酸は水が少なくほとんど電離しないので、強酸性を示さない（薄めた希硫酸が強酸）。吸湿性・脱水作用・不揮発性・熱濃硫酸の酸化作用はすべて正しい。"},{"id":"nm83","q":"[A]に銀を入れると、[B]の気体が発生する。これは[A]の[C]に依る反応である。A～Cの空欄について正しい組み合わせを選べ。","a":"A：熱濃硫酸　B：二酸化硫黄　C：酸化作用","w":["A：熱濃硫酸　B：二酸化硫黄　C：不揮発性","A：濃硫酸　B：三酸化硫黄　C：酸化作用","A：濃硫酸　B：二酸化硫黄　C：不揮発性"],"e":"熱濃硫酸の酸化作用でAgが溶け、硫酸自身はSO₂に還元される（2Ag＋2H₂SO₄→Ag₂SO₄＋2H₂O＋SO₂）。不揮発性は揮発性の酸を追い出すときの性質。SO₃は出ない。"},{"id":"nm84","q":"塩化ナトリウムに濃硫酸を作用させると、[A]と塩化水素が発生する。これは濃硫酸の[B]の性質に依る反応である。A・Bの空欄について正しい組み合わせを選べ。","a":"A：硫酸水素ナトリウム　B：不揮発性","w":["A：硫酸ナトリウム　B：不揮発性","A：硫酸水素ナトリウム　B：酸化作用","A：硫酸ナトリウム　B：酸化作用"],"e":"NaCl＋H₂SO₄→NaHSO₄＋HCl。不揮発性の濃硫酸が揮発性のHClを追い出す。H⁺を1つ渡すだけなので硫酸水素ナトリウム。酸化作用ではない。"},{"id":"nm85","q":"濃硫酸から希硫酸を作る際は、[A]に[B]を少しずつ加えて混ぜる。これは、[C]で水が瞬時に沸騰し液体がはねるのを防ぐためである。A～Cの空欄について正しい組み合わせを選べ。","a":"A：水　B：濃硫酸　C：溶解熱","w":["A：水　B：濃硫酸　C：蒸発熱","A：濃硫酸　B：水　C：蒸発熱","A：濃硫酸　B：水　C：溶解熱"],"e":"水に濃硫酸を少しずつ加える。濃硫酸の溶解熱が大きいので、濃硫酸に水を入れると水が一気に沸騰して飛び散る（突沸）。"}]},{"name":"No.10 窒素","items":[{"id":"nm86","q":"窒素は周期表の何族に属するか。","a":"15","w":["5","14","16"],"e":"窒素Nは15族（リンと同じ）。14族はC、16族はO。"},{"id":"nm87","q":"窒素がもつ価電子は次のうちどれ。","a":"5","w":["3","16","6","15"],"e":"15族なので価電子は5個。族番号15をそのまま答えないこと。"},{"id":"nm88","q":"窒素は、空気中に約 [ A ] %含まれ、工業的には [ B ] を [ C ] して得られる。A～Cに当てはまる組み合わせはどれか。","a":"A：78、B：液体空気、C：分留","w":["A：78、B：液体空気、C：抽出","A：20、B：液体空気、C：抽出","A：78、B：重油、C：分留"],"e":"N₂は空気中に約78％。液体空気を沸点の違いで分ける（分留）。抽出は溶媒への溶けやすさで分ける方法。20％くらいなのはO₂（約21％）。"},{"id":"nm89","q":"窒素は、実験室において、[ A ] （化学式：[ B ]）の熱分解（副生成物：[ C ]）により発生させることができる。A～Cに当てはまる組み合わせはどれか。","a":"A：亜硝酸アンモニウム、B：NH₄NO₂、C：水","w":["A：硝酸アンモニウム、B：NH₄NO₂、C：水","A：硝酸アンモニウム、B：(NH₄)₂NO₃、C：水","A：亜硝酸アンモニウム、B：NH₄NO₂、C：過酸化水素","A：硝酸アンモニウム、B：NH₄NO₃、C：過酸化水素"],"e":"亜硝酸アンモニウムNH₄NO₂の熱分解：NH₄NO₂→N₂＋2H₂O。硝酸アンモニウムはNH₄NO₃。(NH₄)₂NO₃は存在しない。過酸化水素はできない。"},{"id":"nm90","q":"ハーバー（・ボッシュ）法の反応として正しいのはどれ。","a":"窒素と水素から、アンモニアが生成される。","w":["アンモニアから、窒素と水素が生成される。","アンモニアを段階的酸化の後、水と反応させ、硝酸を得る。","硝酸から脱水させ、還元させてアンモニアを得る。"],"e":"ハーバー法はN₂＋3H₂⇄2NH₃（NH₃を作る方法）。アンモニアを酸化して硝酸を作るのはオストワルト法。"},{"id":"nm91","q":"ハーバー（・ボッシュ）法で用いられる触媒はどれ。","a":"四酸化三鉄(Fe₃O₄)","w":["白金(Pt)","酸化バナジウム(V)(V₂O₅)","炭素(C)"],"e":"ハーバー法の触媒は四酸化三鉄Fe₃O₄（鉄が主成分）。Ptはオストワルト法、V₂O₅は接触法。"},{"id":"nm92","q":"アンモニアは、実験室では [ A ] と強塩基の混合物を加熱させて得られる。強塩基を Ca(OH)₂ とした場合、[ B ] と [ C ] が副生成物として生じる。A～Cに当てはまる組み合わせはどれか。","a":"A：NH₄Cl、B：CaCl₂、C：H₂O","w":["A：NH₄Cl、B：Ca、C：HClO","A：NH₄Cl、B：Ca、C：HClO₃","A：N₂、B：Ca、C：O₂","A：NH₄Cl、B：CaCl(ClO)、C：H₂"],"e":"2NH₄Cl＋Ca(OH)₂→CaCl₂＋2H₂O＋2NH₃（弱塩基の遊離）。副生成物はCaCl₂と水だけ。HClOやH₂などは生じない。"},{"id":"nm93","q":"アンモニアの性質として正しいものはどれ。","a":"無色、刺激臭の気体。水溶液は弱塩基性。","w":["淡黄色、刺激臭の気体。水溶液は弱塩基性。","淡黄色、刺激臭の気体。水溶液は弱酸性。","淡黄色、刺激臭の気体。水に溶けない。","無色、腐乱臭の気体。水溶液は弱酸性。"],"e":"NH₃は無色・刺激臭の気体で、水によく溶けて弱塩基性。有色の気体はNO₂・Cl₂・F₂・O₃だけ。腐卵臭はH₂S。"},{"id":"nm94","q":"生成された気体がアンモニアであることを確認する方法として適切なものはどれ。","a":"上方置換で気体収集。濃塩酸を近づけて白煙が生成するかを確認。","w":["上方置換で気体収集。希硫酸を近づけて白煙が生成するかを確認。","上方置換で気体収集。塩化アンモニウムを近づけて白煙が生成するかを確認。","下方置換で気体収集。濃塩酸を近づけて白煙が生成するかを確認。","下方置換で気体収集。希硫酸を近づけて白煙が生成するかを確認。"],"e":"NH₃は水によく溶け空気より軽いので上方置換。濃塩酸（揮発したHCl）を近づけるとNH₄Clの白煙が出る。希硫酸は揮発しないので白煙は出ない。"},{"id":"nm95","q":"一酸化窒素について説明したものとして正しいものはどれ。","a":"水に溶けにくい気体。無色。空気中ですぐに酸化され二酸化窒素へ。","w":["水に溶けやすい気体。赤褐色。有毒。水に溶けると硝酸へ。","水に溶けにくい気体。赤褐色。空気中ですぐに酸化され二酸化窒素へ。","水に溶けやすい気体。無色。有毒。水に溶けると硝酸へ。","水に溶けやすい気体。無色。有毒。水に溶けると亜硝酸へ。"],"e":"NOは無色・水に溶けにくい気体で、空気中ですぐ酸化されてNO₂になる。赤褐色・水に溶けて硝酸になるのはNO₂の性質。"},{"id":"nm96","q":"二酸化窒素について説明したものとして正しいものはどれ。","a":"水に溶けやすい気体。赤褐色。有毒。水に溶けると硝酸へ。","w":["水に溶けにくい気体。無色。空気中ですぐに酸化され二酸化窒素へ。","水に溶けにくい気体。赤褐色。空気中ですぐに酸化され二酸化窒素へ。","水に溶けやすい気体。無色。有毒。水に溶けると硝酸へ。","水に溶けやすい気体。無色。有毒。水に溶けると亜硝酸へ。"],"e":"NO₂は赤褐色・有毒で水によく溶け、硝酸になる（3NO₂＋H₂O→2HNO₃＋NO）。無色・水に溶けにくい・空気で酸化されるのはNOの性質。"},{"id":"nm97","q":"一酸化窒素は、銅に [ A ] を反応させて、[ B ] 置換で捕集する。A・Bに当てはまる組み合わせはどれか。","a":"A：希硝酸、B：水上","w":["A：濃硝酸、B：下方","A：希硝酸、B：下方","A：濃硝酸、B：水上"],"e":"Cu＋希硝酸→NO。NOは水に溶けにくいので水上置換で集める（空気とも反応するので下方置換は不可）。濃硝酸ならNO₂。"},{"id":"nm98","q":"二酸化窒素は、銅に [ A ] を反応させて、[ B ] 置換で捕集する。A・Bに当てはまる組み合わせはどれか。","a":"A：濃硝酸、B：下方","w":["A：希硝酸、B：水上","A：希硝酸、B：下方","A：濃硝酸、B：水上"],"e":"Cu＋濃硝酸→NO₂。NO₂は水に溶けやすく空気より重いので下方置換。希硝酸ならNO。"},{"id":"nm99","q":"銅に希硝酸を加え反応させた。1.2molの銅を全て反応させたとき、希硝酸は [ A ] mol反応し、一酸化窒素は [ B ] mol生成する。A・Bに入る数値の組み合わせはどれか。","a":"A：3.2、B：0.8","w":["A：4.8、B：2.4","A：3.2、B：1.6","A：4.8、B：1.6","A：2.4、B：1.2"],"e":"3Cu＋8HNO₃→3Cu(NO₃)₂＋4H₂O＋2NO。Cu:HNO₃:NO＝3:8:2 なので、Cu 1.2molならHNO₃は1.2×8/3＝3.2mol、NOは1.2×2/3＝0.8mol。"},{"id":"nm100","q":"銅に濃硝酸を加え反応させた。1.2molの銅を全て反応させたとき、濃硝酸は [ A ] mol反応し、二酸化窒素は [ B ] mol生成する。A・Bに入る数値の組み合わせはどれか。","a":"A：4.8、B：2.4","w":["A：3.2、B：0.8","A：3.2、B：1.6","A：4.8、B：1.6","A：2.4、B：1.2"],"e":"Cu＋4HNO₃→Cu(NO₃)₂＋2H₂O＋2NO₂。Cu:HNO₃:NO₂＝1:4:2 なので、Cu 1.2molならHNO₃は4.8mol、NO₂は2.4mol。"},{"id":"nm101","q":"常温においては、二酸化窒素はある物質と平衡関係にある。この物質について説明したものとして正しいものはどれ。","a":"無色気体の四酸化二窒素","w":["無色気体の一酸化窒素及び酸素","赤褐色気体の四酸化二窒素","赤褐色気体の一酸化窒素及び酸素"],"e":"2NO₂⇄N₂O₄。NO₂は赤褐色、N₂O₄は無色。NOやO₂に分解するわけではない。"},{"id":"nm102","q":"硝酸の製法として最も適当なものはどれ。","a":"硝酸ナトリウムに濃硫酸を加えて加熱する。","w":["硝酸ナトリウムに希硫酸を加えて加熱する。","硝酸ナトリウムに濃塩酸を加えて加熱する。","硝酸ナトリウムに希塩酸を加えて加熱する。"],"e":"NaNO₃＋H₂SO₄→NaHSO₄＋HNO₃。不揮発性の濃硫酸で揮発性の硝酸を追い出す（加熱が必要）。希硫酸では追い出せない。塩酸は揮発性なので使えない。"},{"id":"nm103","q":"硝酸ナトリウムに濃硫酸を加えて加熱すると、硝酸と硫酸水素ナトリウムが生成する。この反応が生じる理由として、最も適当な濃硫酸の性質は次のうちどれ。","a":"不揮発性の酸","w":["強酸性","脱水作用","酸化作用"],"e":"揮発性の酸の塩に不揮発性の濃硫酸を加えて加熱すると、揮発性の酸（硝酸）が追い出される。強酸性・脱水作用・酸化作用はこの反応の理由ではない。"},{"id":"nm104","q":"オストワルト法の反応として正しいのはどれ。","a":"アンモニアを段階的酸化の後、水と反応させ、硝酸を得る。","w":["窒素と水素から、アンモニアが生成される。","アンモニアから、窒素と水素が生成される。","硝酸から脱水させ、還元させてアンモニアを得る。"],"e":"オストワルト法は、NH₃を酸化してNO→NO₂とし、水と反応させて硝酸にする方法。N₂とH₂からNH₃を作るのはハーバー法。"},{"id":"nm105","q":"オストワルト法で用いられる触媒はどれ。","a":"白金(Pt)","w":["四酸化三鉄(Fe₃O₄)","酸化バナジウム(V)(V₂O₅)","炭素(C)"],"e":"オストワルト法の触媒は白金Pt。Fe₃O₄はハーバー法、V₂O₅は接触法。"},{"id":"nm106","q":"オストワルト法の三段階の反応のうち、触媒を必要とする反応はどれ。","a":"4NH₃ + 5O₂ → 4NO + 6H₂O","w":["2NO + O₂ → 2NO₂","3NO₂ + H₂O → 2HNO₃ + NO"],"e":"触媒（Pt）が要るのは第1段階のNH₃の酸化（4NH₃＋5O₂→4NO＋6H₂O）だけ。NO→NO₂は空気中ですぐ進み、NO₂＋水も触媒なしで進む。"},{"id":"nm107","q":"オストワルト法の３つの化学反応式を１つの化学反応式にまとめると、どのような反応になるか。正しいものを選べ。","a":"アンモニアと酸素が硝酸と水になる。","w":["アンモニアと水が硝酸となる。","アンモニアと二酸化窒素が硝酸となる。","アンモニアと一酸化窒素が硝酸となる。"],"e":"3式からNOとNO₂を消去すると NH₃＋2O₂→HNO₃＋H₂O。原料はアンモニアと酸素だけで、硝酸と水ができる。"},{"id":"nm108","q":"次のうち、硝酸の説明として正しいものはどれ。","a":"無色、刺激臭の液体で、揮発性がある。","w":["褐色、刺激臭の液体で、揮発性がある。","無色、刺激臭の液体で、不揮発性である。","褐色、刺激臭の液体で、不揮発性である。","無色、無臭の液体で、揮発性がある。"],"e":"硝酸は無色・刺激臭の液体で、揮発性がある（だから濃硫酸で追い出して作れる）。光で分解すると淡黄色になるが、本来は無色。"},{"id":"nm109","q":"濃硝酸は、光により分解し [ A ] 色となるため、[ B ] に入れて冷暗所に保存する。A・Bに当てはまる組み合わせはどれか。","a":"A：淡黄、B：褐色びん","w":["A：無、B：褐色びん","A：淡黄、B：ポリエチレン製の容器","A：無、B：ポリエチレン製の容器"],"e":"濃硝酸は光で分解してNO₂を生じ、それが溶けて淡黄色になる。光を防ぐため褐色びんに入れる。ポリエチレン容器はガラスを溶かすフッ化水素酸用。"},{"id":"nm110","q":"希硝酸、濃硝酸、希塩酸、濃塩酸、希硫酸、濃硫酸の液性について、正しいものはどれ。","a":"濃硫酸のみ強酸ではない。残りは強酸。","w":["濃硝酸、濃硫酸のみ強酸ではない。残りは強酸。","濃塩酸、濃硫酸のみ強酸ではない。残りは強酸。","濃塩酸、濃硝酸、濃硫酸は強酸ではない。残りは強酸。"],"e":"濃硫酸は水が少なくほとんど電離しないので強酸性を示さない。濃硝酸・濃塩酸は水を十分含み電離するので強酸。"},{"id":"nm111","q":"硝酸は強い酸化作用をもつ。次のうち、硝酸によって溶かされる金属として正しいものはどれか。なお、水素よりもイオン化傾向の小さい金属は、順に Cu＞Hg＞Ag＞Pt＞Au である。","a":"Cu、Hg、Ag","w":["Cu、Hg","Cu","Cu、Hg、Ag、Pt"],"e":"硝酸は酸化力が強く、水素よりイオン化傾向の小さいCu・Hg・Agも溶かす。PtとAuは溶かせない（王水なら溶ける）。"},{"id":"nm112","q":"ある金属を濃硝酸に入れると、表面に薄い緻密な酸化被膜ができ、それ以上反応しなくなる。これを何というか。","a":"不動態","w":["不導体","不動体","不導態"],"e":"表面にち密な酸化被膜ができ反応が止まる状態が不動態（「動かない態」）。不導体は電気を通さない物質。「不動体」「不導態」は存在しない語。"},{"id":"nm113","q":"濃硝酸に入れると不動態を形成する金属として正しい組み合わせを選べ。","a":"Fe、Al、Ni","w":["Mg、Al、Fe","Pb、Ni、Fe","Pb、Sn、Ni","Al、Fe、Sn"],"e":"不動態になるのはFe・Al・Ni（とCr）。Mg・Pb・Snは不動態にならない（Pbは希硝酸に溶ける、Mgは激しく反応する）。"}]},{"name":"No.11 リン","items":[{"id":"nm43","q":"リンは周期表の何族に属するか。","a":"15","w":["14","13","12"],"e":"リンPは窒素と同じ15族。14族はC・Si、13族はAl、12族はZn。"},{"id":"nm44","q":"リンがもつ価電子数はどれ。","a":"5","w":["3","6","4"],"e":"15族なので価電子は5個。"},{"id":"nm45","q":"リンの同素体について。空気中で自然発火するのは [ A ] で、毒性が強いのは [ B ] で、分子式が P₄ として表されるのは [ C ] で、二硫化炭素へ溶けるのは [ D ] である。A～Dに当てはまる組み合わせはどれか。","a":"A:黄リン、B:黄リン、C:黄リン、D:黄リン","w":["A:黄リン、B:赤リン、C:赤リン、D:黄リン","A:黄リン、B:黄リン、C:黄リン、D:赤リン","A:赤リン、B:黄リン、C:黄リン、D:赤リン","A:赤リン、B:赤リン、C:赤リン、D:赤リン"],"e":"黄リンP₄は自然発火し、毒性が強く、CS₂に溶ける。だから水中に保存する。赤リンは毒性がなく自然発火しない（マッチの側薬）。A〜Dすべて黄リン。"},{"id":"nm46","q":"空気中でリンを燃焼させるとできるのはどれ。","a":"P₄O₁₀","w":["PO₄","P₂O₄","P₃O₄"],"e":"リンを燃やすと十酸化四リンP₄O₁₀（4P＋5O₂→P₄O₁₀）。組成式で書くとP₂O₅（五酸化二リン）。他の化学式は存在しない。"},{"id":"nm47","q":"十酸化四リンは、[ A ] 色の粉末で、強力な [ B ] として用いられる。A・Bに当てはまる組み合わせはどれか。","a":"A:白、B:乾燥剤","w":["A:白、B:還元剤","A:白、B:酸化剤","A:黒、B:還元剤","A:黒、B:酸化剤"],"e":"P₄O₁₀は白色の粉末で、水をよく吸うので強力な乾燥剤に使う。酸化剤・還元剤として使うものではない。"},{"id":"nm48","q":"十酸化四リンを乾燥剤として用いる場合に、適さないものはどれ。","a":"塩基性の気体","w":["中性の気体","酸性の気体"],"e":"P₄O₁₀は酸性の乾燥剤なので、塩基性の気体（NH₃）とは中和してしまい乾燥できない。中性・酸性の気体には使える。"},{"id":"nm49","q":"リン酸の製法として正しいものはどれ。","a":"十酸化四リンを水に溶かして加熱。","w":["黄リンを水に溶かして加熱。","赤リンを水に溶かして加熱。"],"e":"P₄O₁₀＋6H₂O→4H₃PO₄。酸性酸化物を水に溶かすとオキソ酸ができる。リンの単体は水に溶けない（黄リンは水中で保存するほど）。"},{"id":"nm50","q":"リン酸の結晶またはリン酸の水溶液の示す性質はどれ。","a":"結晶は潮解性をもつ。","w":["結晶は硬く融点が高い。","水溶液は強酸性。","水溶液は酸化作用をもつ。"],"e":"リン酸の結晶は潮解性をもつ（空気中の水を吸って溶ける）。リン酸は中程度の強さの酸で強酸ではなく、酸化作用もない。結晶の融点は低い（約42℃）。"}]},{"name":"No.12 炭素","items":[{"id":"nm51","q":"炭素は周期表の何族に属するか。","a":"14","w":["13","12","15"],"e":"炭素Cは14族（ケイ素と同じ）。13族はAl、15族はN・P。"},{"id":"nm52","q":"炭素のもつ価電子数はどれ。","a":"4","w":["3","5","8"],"e":"14族なので価電子は4個。4本の共有結合をつくる。"},{"id":"nm53","q":"炭素の同素体のうち、構造が層状でやわらかいものはどれ。","a":"黒鉛","w":["ダイヤモンド","フラーレン","カーボンナノチューブ"],"e":"黒鉛は層状構造で、層と層の間は弱い分子間力なのではがれやすく柔らかい（鉛筆の芯）。ダイヤモンドは立体網目で最も硬い。"},{"id":"nm54","q":"炭素の同素体のうち、構造が球状のものはどれ。","a":"フラーレン","w":["黒鉛","ダイヤモンド","カーボンナノチューブ"],"e":"フラーレンはサッカーボール状（球状）の分子。黒鉛は層状、ダイヤモンドは立体網目、カーボンナノチューブは筒状。"},{"id":"nm55","q":"炭素の同素体のうち、C₆₀ や C₇₀ と表記されるものはどれ。","a":"フラーレン","w":["黒鉛","ダイヤモンド","カーボンナノチューブ"],"e":"フラーレンはC₆₀・C₇₀などの分子式で表せる「分子」。黒鉛・ダイヤモンドは共有結合の結晶なので分子式ではなく C と書く。"},{"id":"nm56","q":"炭素の同素体のうち、電気を一切通さないもの（絶縁体）の組み合わせとして正しいものはどれ。","a":"ダイヤモンド、フラーレン","w":["ダイヤモンド、カーボンナノチューブ","フラーレン、カーボンナノチューブ","黒鉛、カーボンナノチューブ"],"e":"ダイヤモンドは価電子4個すべてを結合に使うので自由に動ける電子がなく絶縁体。フラーレンも絶縁体。黒鉛とカーボンナノチューブは自由に動ける電子があり電気を通す。"},{"id":"nm57","q":"黒鉛(グラファイト)のアモルファスを [ A ] と呼び、また網目構造の層１枚の構造を [ B ] と呼ぶ。これらは全て炭素の同素体である。A・Bに当てはまる組み合わせはどれか。","a":"A:無定形炭素、B:グラフェン","w":["A:グラフェン、B:無定形炭素","A:カーボンブラック、B:無定形炭素","A:グラフェン、B:カーボンブラック"],"e":"結晶になっていない（アモルファス）炭素が無定形炭素（すす・木炭・カーボンブラックなど）。黒鉛の層1枚がグラフェン。カーボンブラックは無定形炭素の一種。"},{"id":"nm58","q":"実験室における一酸化炭素の製法はどれ。","a":"ギ酸を濃硫酸で脱水する。","w":["アルコール発酵。","石灰石の強熱による熱分解。","石灰石に塩酸を加える。"],"e":"実験室ではギ酸を濃硫酸で脱水してCOを得る（HCOOH→CO＋H₂O）。石灰石の熱分解・石灰石＋塩酸はCO₂の製法、アルコール発酵もCO₂が出る。"},{"id":"nm59","q":"一酸化炭素の性質として正しいものはどれ。","a":"無色、無臭、有毒気体。水に溶けにくい。","w":["無色、刺激臭、有毒気体。水に溶けにくい。","無色、無臭、有毒気体。水に溶けやすい。","無色、刺激臭、有毒気体。水に溶けやすい。"],"e":"COは無色・無臭で水に溶けにくい有毒気体（一酸化炭素中毒）。においがないので気づきにくく危険。"},{"id":"nm60","q":"高温の一酸化炭素は [ A ] 作用が強いため、Fe₂O₃と反応させると、[ B ] が生じる。A・Bに当てはまる組み合わせはどれか。","a":"A:還元、B:Fe","w":["A:還元、B:FeCO₃","A:酸化、B:Fe","A:酸化、B:FeCO₃"],"e":"COはOを奪いやすく還元作用が強い。Fe₂O₃を還元してFeにし、自身はCO₂になる（Fe₂O₃＋3CO→2Fe＋3CO₂）。製鉄（高炉）の反応。"},{"id":"nm61","q":"生物の呼吸においては、[ A ] と酸素が反応し、二酸化炭素と [ B ] が生成する。このとき、酸素1molに対して、二酸化炭素は [ C ] mol生じる。A～Cに当てはまる組み合わせはどれか。","a":"A:C₆H₁₂O₆、B:水、C:1","w":["A:C₆H₁₂O₆、B:水、C:2","A:C₆H₁₀O₅、B:水、C:2","A:C₆H₁₀O₅、B:水、C:1","A:C₆H₁₂O₆、B:水素、C:2"],"e":"呼吸はグルコースC₆H₁₂O₆の燃焼と同じ：C₆H₁₂O₆＋6O₂→6CO₂＋6H₂O。O₂とCO₂の係数が同じなので1mol。C₆H₁₀O₅はデンプン・セルロースの単位。"},{"id":"nm62","q":"アルコール発酵により二酸化炭素が生成する反応は、[ A ] が、[ B ] と二酸化炭素に分解する反応である。A・Bに当てはまる組み合わせはどれか。","a":"A:C₆H₁₂O₆、B:C₂H₅OH","w":["A:C₆H₁₀O₅、B:C₂H₅OH","A:C₆H₁₂O₆、B:CH₃OH","A:C₆H₁₀O₅、B:CH₃OH"],"e":"アルコール発酵：C₆H₁₂O₆→2C₂H₅OH＋2CO₂。エタノールができる（メタノールではない）。C₆H₁₀O₅はデンプンの単位。"},{"id":"nm63","q":"CO₂の工業的製法は、[ A ](名称 [ B ] ) を強熱して熱分解させる。副生成物は[ C ]。A～ ～Cに当てはまる組み合わせはどれか。","a":"A:CaCO₃、B:石灰石、C:酸化カルシウム","w":["A:CaCO₃、B:消石灰、C:酸化カルシウム","A:CaCO₃、B:石灰石、C:カルシウム(単体)","A:Ca(OH)₂、B:消石灰、C:酸化カルシウム","A:Ca(OH)₂、B:石灰石、C:カルシウム(単体)"],"e":"石灰石CaCO₃を強熱するとCaO（酸化カルシウム）とCO₂になる。消石灰はCa(OH)₂で別物。Caの単体はイオン化傾向が大きく、熱分解ではできない。"},{"id":"nm64","q":"CO₂の実験室での製法は、炭酸塩、例えば石灰石や大理石 (主成分は、[ A ])に、塩酸を加えて発生させる。副生成物は[ B ]と水。A・Bに当てはまる組み合わせはどれか。","a":"A:CaCO₃、B:塩化カルシウム","w":["A:CaCO₃、B:塩素","A:MgCO₃、B:塩化マグネシウム","A:MgCO₃、B:塩素"],"e":"CaCO₃＋2HCl→CaCl₂＋H₂O＋CO₂（弱酸の遊離）。大理石・石灰石の主成分はCaCO₃。Cl⁻は酸化されないので塩素は出ない。"},{"id":"nm65","q":"石灰水で水に溶けているのはどれ。","a":"Ca(OH)₂","w":["CaO","CaCO₃"],"e":"石灰水は水酸化カルシウムCa(OH)₂の水溶液。CaOは水と反応してCa(OH)₂になり、CaCO₃は水に溶けない。"},{"id":"nm66","q":"CO₂を石灰水に通すと白濁する。白濁する要因となる物質はどれ。","a":"炭酸カルシウム","w":["酸化カルシウム","水酸化カルシウム"],"e":"Ca(OH)₂＋CO₂→CaCO₃＋H₂O。水に溶けないCaCO₃ができて白く濁る。Ca(OH)₂はもともと溶けている物質。"},{"id":"nm67","q":"二酸化炭素の固体の名称はどれ。","a":"ドライアイス","w":["フラーレン","グラフェン","グラファイト"],"e":"CO₂の固体はドライアイス（昇華性）。フラーレン・グラフェン・グラファイトは炭素の単体。"}]},{"name":"No.13 ケイ素","items":[{"id":"nm1","q":"ケイ素は周期表の何族に属するか。","a":"14","w":["15","16","13"],"e":"ケイ素Siは炭素と同じ14族。13族はAl、15族はN・P、16族はO・S。"},{"id":"nm2","q":"ケイ素がもつ価電子数はどれ。","a":"4","w":["5","3","6"],"e":"14族なので価電子は4個。炭素と同じく4本の共有結合をつくる。"},{"id":"nm3","q":"ケイ素は [ A ] 形の [ B ] 結合の結晶であるが、融点や硬度は [ A ] よりかなり低い。高純度のケイ素の結晶は、[ C ] である。A～Cに当てはまる組み合わせはどれか。","a":"A:ダイヤモンド、B:共有、C:半導体","w":["A:ダイヤモンド、B:イオン、C:半導体","A:ダイヤモンド、B:共有、C:シリカゲル","A:黒鉛、B:共有、C:シリカゲル","A:黒鉛、B:イオン、C:半導体"],"e":"Siはダイヤモンドと同じ構造の共有結合の結晶。高純度のSiは半導体で集積回路に使う。イオン結合ではない。シリカゲルはケイ酸から作る乾燥剤。"},{"id":"nm4","q":"二酸化ケイ素は、主に自然界では [ A ] として存在する。[ A ] の透明な結晶を [ B ] と呼び、砂状のものを [ C ] と呼ぶ。A~Cに当てはまる組み合わせはどれか。","a":"A:石英、B:水晶、C:ケイ砂","w":["A:石灰、B:石英、C:ソーダ灰","A:石英、B:石晶、C:ソーダ灰","A:石灰、B:石英、C:ケイ砂","A:石灰、B:水晶、C:ケイ砂"],"e":"SiO₂は天然では石英として存在し、透明な結晶が水晶、砂状のものがケイ砂。石灰はCa化合物、ソーダ灰は炭酸ナトリウム。「石晶」という語はない。"},{"id":"nm5","q":"二酸化ケイ素は安定な化合物であるが、[ A ] とは反応し、[ B ] が生成する。A・Bに当てはまる組み合わせはどれか。","a":"A:フッ化水素酸、B:H₂SiF₆","w":["A:フッ化水素酸、B:H₂SiF₄","A:濃硝酸、B:Si","A:濃硝酸、B:SiO₄"],"e":"SiO₂は安定だがフッ化水素酸とは反応してH₂SiF₆（ヘキサ＝6個のF）を生成（SiO₂＋6HF→H₂SiF₆＋2H₂O）。濃硝酸とは反応しない。"},{"id":"nm6","q":"二酸化ケイ素を融解させた後、冷却するとできるものはどれ。","a":"石英ガラス","w":["シリカゲル","水ガラス","グラファイト"],"e":"SiO₂を融かして冷やすと、結晶にならずに固まった石英ガラスになる。シリカゲルはケイ酸の脱水、水ガラスはケイ酸ナトリウム＋水、グラファイトは炭素。"},{"id":"nm7","q":"二酸化ケイ素は [ A ] のため、水酸化ナトリウムと反応して、[ B ](ケイ酸ナトリウム)を生成する。A・Bに当てはまる組み合わせはどれか。","a":"A:酸性酸化物、B:Na₂SiO₃","w":["A:酸性酸化物、B:Na₂SiO₄","A:塩基性酸化物、B:Na₂SiO₃","A:塩基性酸化物、B:Na₂SiO₄"],"e":"SiO₂は非金属の酸化物で酸性酸化物なので、塩基NaOHと反応してケイ酸ナトリウムNa₂SiO₃になる。Na₂SiO₄ではない（SiO₂＋2NaOH→Na₂SiO₃＋H₂O）。"},{"id":"nm8","q":"二酸化ケイ素やケイ酸塩を含むものとして誤っているものはどれか。","a":"ミョウバン","w":["ガラス","セメント","陶磁器"],"e":"ガラス・セメント・陶磁器はSiO₂やケイ酸塩が原料（セラミックス）。ミョウバンはAlK(SO₄)₂・12H₂OでSiを含まない。"},{"id":"nm9","q":"ケイ酸ナトリウムに水を加えて加熱すると得られるものはどれ。","a":"水ガラス","w":["石英ガラス","シリカゲル","ミョウバン"],"e":"ケイ酸ナトリウムに水を加えて加熱すると、粘り気の大きい水ガラスになる。石英ガラスはSiO₂を融かして冷やしたもの、シリカゲルはケイ酸の脱水。"},{"id":"nm10","q":"ケイ酸を加熱・脱水して得られるものはどれ。","a":"シリカゲル","w":["水ガラス","石英ガラス","ケイ砂"],"e":"ケイ酸H₂SiO₃を加熱・脱水すると多孔質のシリカゲルになる。水ガラスはケイ酸ナトリウム水溶液、ケイ砂は天然のSiO₂。"},{"id":"nm11","q":"シリカゲルの用途として正しいものはどれ。","a":"乾燥剤及び吸着剤","w":["乾燥剤及び酸化剤","乾燥剤及び還元剤","吸着剤及び酸化剤"],"e":"シリカゲルは多孔質で表面積が大きく、水などを吸着するので乾燥剤・吸着剤に使う。酸化剤・還元剤としての性質はない。"}]},{"name":"No.14-1 気体発生(1)","items":[{"id":"q31","q":"次の操作を行ったとき、発生する気体は何か。水にナトリウムの単体を加える。","a":"水素","w":["酸素","ナトリウム","発生しない"],"e":"アルカリ金属は冷水と激しく反応しH₂を出す（2Na＋2H₂O→2NaOH＋H₂）。Naは金属で気体ではない。酸素は出ない。"},{"id":"q32","q":"次の操作を行ったとき、発生する気体は何か。石灰石を加熱する。","a":"二酸化炭素","w":["酸素","水素","発生しない"],"e":"石灰石CaCO₃を加熱すると熱分解して CaCO₃→CaO＋CO₂。炭酸塩の熱分解ではCO₂が出る。O₂やH₂は出ない。"},{"id":"q33","q":"次の操作を行ったとき、発生する気体は何か。水酸化カルシウムと塩化アンモニウムを混合して加熱する。","a":"アンモニア","w":["水素","酸素","塩素","塩化水素"],"e":"NH₄Cl（弱塩基の塩）と強塩基Ca(OH)₂で弱塩基NH₃が遊離する（2NH₄Cl＋Ca(OH)₂→CaCl₂＋2H₂O＋2NH₃）。HClやCl₂は出ない（ClはCaCl₂として残る）。"},{"id":"q34","q":"次の操作を行ったとき、発生する気体は何か。炭酸水素ナトリウムを加熱する","a":"二酸化炭素","w":["水素","酸素","塩素","塩化水素"],"e":"NaHCO₃は加熱で分解する（2NaHCO₃→Na₂CO₃＋CO₂＋H₂O）。アンモニアソーダ法の工程の一つ。他の選択肢の元素は出てこない。"},{"id":"q35","q":"次の操作を行ったとき、発生する気体は何か。水にカルシウムの単体を加える。","a":"水素","w":["酸素","カルシウム","発生しない"],"e":"Caなどアルカリ土類金属も冷水と反応してH₂を出す（Ca＋2H₂O→Ca(OH)₂＋H₂）。Caは金属で気体ではない。酸素は出ない。"},{"id":"q36","q":"次の操作を行ったとき、発生する気体は何か。炭酸水素カルシウムを加熱する。","a":"二酸化炭素","w":["水素","酸素","発生しない"],"e":"Ca(HCO₃)₂を加熱するとCaCO₃に戻り、CO₂が出る（Ca(HCO₃)₂→CaCO₃＋H₂O＋CO₂）。鍾乳洞ができる原理と同じ。"},{"id":"q37","q":"次の操作を行ったとき、発生する気体は何か。生石灰とコークスを炉に入れて加熱する。","a":"一酸化炭素","w":["カーバイド","アセチレン","水素","二酸化炭素"],"e":"CaO＋3C→CaC₂＋CO。カーバイドCaC₂は固体なので気体ではない。アセチレンはカーバイドに水を加えたときに出る。高温での反応なのでCO₂ではなくCO。"},{"id":"q38","q":"次の操作を行ったとき、発生する気体は何か。カーバイドに水を加える。","a":"アセチレン","w":["エチレン","水素","酸素","二酸化炭素"],"e":"CaC₂＋2H₂O→Ca(OH)₂＋C₂H₂（アセチレン）。同時にできるのはCaOではなくCa(OH)₂。エチレンC₂H₄はエタノールの脱水で得る気体。"},{"id":"q39","q":"次の操作を行ったとき、発生する気体は何か。アルミニウムに濃水酸化ナトリウムを加える。","a":"水素","w":["酸素","発生しない"],"e":"Alは両性金属なので強塩基とも反応してH₂を出す（2Al＋2NaOH＋6H₂O→2Na[Al(OH)₄]＋3H₂）。酸素は出ない。"},{"id":"q40","q":"次の操作を行ったとき、発生する気体は何か。酸化アルミニウムの溶融塩電解(炭素電極)の陽極側。","a":"一酸化炭素","w":["水素","酸素","発生しない"],"e":"陽極ではO²⁻が炭素電極と反応して CO（や CO₂）が出る。電極が炭素なのでO₂のまま出てこない。H₂は陰極側でも出ない（陰極ではAlが析出）。"},{"id":"q41","q":"次の操作を行ったとき、発生する気体は何か。銀に希硝酸を加える。","a":"一酸化窒素","w":["二酸化窒素","水素","酸素","発生しない"],"e":"Agは希酸とは反応しないが、酸化力のある希硝酸には溶けてNOを出す。濃硝酸ならNO₂。H₂が出るのはイオン化傾向がHより大きい金属だけ。"},{"id":"q42","q":"次の操作を行ったとき、発生する気体は何か。銅に希硝酸を加える。","a":"一酸化窒素","w":["二酸化窒素","水素","酸素","発生しない"],"e":"3Cu＋8HNO₃→3Cu(NO₃)₂＋4H₂O＋2NO。希硝酸ならNO、濃硝酸ならNO₂（濃い方がOが多い）。Cuは水素よりイオン化傾向が小さいのでH₂は出ない。"},{"id":"q43","q":"次の操作を行ったとき、発生する気体は何か。銀に濃硝酸を加える。","a":"二酸化窒素","w":["一酸化窒素","水素","酸素","発生しない"],"e":"Agは酸化力のある濃硝酸に溶けてNO₂を出す。希硝酸ならNO。Agは水素よりイオン化傾向が小さいのでH₂は出ない。"},{"id":"q44","q":"次の操作を行ったとき、発生する気体は何か。銅に濃硝酸を加える。","a":"二酸化窒素","w":["一酸化窒素","水素","酸素","発生しない"],"e":"Cu＋4HNO₃→Cu(NO₃)₂＋2H₂O＋2NO₂。濃硝酸ならNO₂（赤褐色）、希硝酸ならNO。H₂は出ない。"},{"id":"q45","q":"次の操作を行ったとき、発生する気体は何か。銅に希硫酸を加える。","a":"発生しない","w":["二酸化硫黄","水素","酸素"],"e":"Cuは水素よりイオン化傾向が小さいので、酸化力のない希硫酸とは反応しない。SO₂が出るのは熱濃硫酸（酸化作用）のとき。"},{"id":"q46","q":"次の操作を行ったとき、発生する気体は何か。銅に濃硫酸を加えて加熱する。","a":"二酸化硫黄","w":["発生しない","水素","酸素"],"e":"熱濃硫酸は酸化作用をもつのでCuを溶かし、自身はSO₂に還元される（Cu＋2H₂SO₄→CuSO₄＋2H₂O＋SO₂）。希硫酸では反応しない。H₂は出ない。"},{"id":"q47","q":"次の操作を行ったとき、発生する気体は何か。銀に濃硫酸を加えて加熱する。","a":"二酸化硫黄","w":["発生しない","水素","酸素"],"e":"熱濃硫酸の酸化作用でAgも溶け、SO₂が出る（2Ag＋2H₂SO₄→Ag₂SO₄＋2H₂O＋SO₂）。H₂は出ない。"},{"id":"q48","q":"次の操作を行ったとき、発生する気体は何か。アルミニウムに濃硝酸を加える。","a":"発生しない","w":["二酸化窒素","一酸化窒素","水素","酸素"],"e":"Alは濃硝酸で表面にち密な酸化被膜ができて不動態になり、反応が進まない。不動態になる金属：Al・Fe・Ni・Cr。"},{"id":"q49","q":"次の操作を行ったとき、発生する気体は何か。鉄に濃硝酸を加える。","a":"発生しない","w":["二酸化窒素","一酸化窒素","水素","酸素"],"e":"Feは濃硝酸で不動態になり、反応が進まない。不動態になる金属：Al・Fe・Ni・Cr。希硝酸なら溶けてNOを出す。"},{"id":"q50","q":"次の操作を行ったとき、発生する気体は何か。アルミニウムに希硫酸を加える。","a":"水素","w":["発生しない","二酸化硫黄","三酸化硫黄"],"e":"Alは水素よりイオン化傾向が大きいので、希硫酸と反応してH₂を出しAl³⁺になる。希硫酸は酸化力がないのでSO₂は出ない。SO₃は接触法で作るもの。"}]},{"name":"No.14-2 気体発生(2)","items":[{"id":"q51","q":"次の操作を行ったとき、発生する気体は何か。フッ素と水を混合する。","a":"酸素","w":["水素","発生しない"],"e":"F₂は酸化力が非常に強く、水を酸化してO₂を出す（2F₂＋2H₂O→4HF＋O₂）。H₂は出ない。"},{"id":"q52","q":"次の操作を行ったとき、発生する気体は何か。さらし粉に塩酸を加え加熱する。","a":"塩素","w":["水素","酸素","発生しない"],"e":"さらし粉CaCl(ClO)・H₂O中のClO⁻と塩酸のCl⁻が反応してCl₂が出る（CaCl(ClO)・H₂O＋2HCl→CaCl₂＋2H₂O＋Cl₂）。"},{"id":"q53","q":"次の操作を行ったとき、発生する気体は何か。次亜塩素酸ナトリウムに塩酸を加える。","a":"塩素","w":["水素","酸素","発生しない"],"e":"NaClO中のClO⁻（Clの酸化数＋1）と塩酸のCl⁻（−1）が反応してCl₂（0）になる。「混ぜるな危険」の理由。"},{"id":"q54","q":"次の操作を行ったとき、発生する気体は何か。食塩に濃硫酸を加えて加熱する。","a":"塩化水素","w":["塩素","水素","酸素","発生しない"],"e":"不揮発性の濃硫酸を加えて加熱すると、揮発性のHClが追い出される（NaCl＋H₂SO₄→NaHSO₄＋HCl）。Cl⁻は酸化されないのでCl₂ではない。"},{"id":"q55","q":"次の操作を行ったとき、発生する気体は何か。蛍石に濃硫酸を加えて加熱する。","a":"フッ化水素","w":["二酸化硫黄","水素","酸素","硫化水素"],"e":"蛍石CaF₂＋H₂SO₄→CaSO₄＋2HF。揮発性酸（かつ弱酸）の遊離。濃硫酸が還元されるわけではないのでSO₂は出ない。H₂Sは硫化鉄から。"},{"id":"q56","q":"次の操作を行ったとき、発生する気体は何か。酸化マンガン(Ⅳ)に濃塩酸を加えて加熱する。","a":"塩素","w":["水素","塩化水素","発生しない","酸素"],"e":"MnO₂が酸化剤となり、濃塩酸のCl⁻を酸化してCl₂を出す（MnO₂＋4HCl→MnCl₂＋2H₂O＋Cl₂）。HClは原料側。H₂・O₂は出ない。"},{"id":"q57","q":"次の操作を行ったとき、発生する気体は何か。加熱した塩素酸カリウムに酸化マンガン(Ⅳ)を加える。","a":"酸素","w":["塩素","水素","オゾン","塩化水素"],"e":"2KClO₃→2KCl＋3O₂（MnO₂は触媒）。塩素はKClとして残るのでCl₂は出ない。オゾンは無声放電や紫外線で作る。"},{"id":"q58","q":"次の操作を行ったとき、発生する気体は何か。酸素に紫外線を照射する。","a":"オゾン","w":["クロロフルオロカーボン","ボソン","クメンヒドロペルオキシド"],"e":"酸素に紫外線や無声放電を当てるとオゾンO₃ができる（3O₂→2O₃）。クロロフルオロカーボン（フロン）はオゾン層を壊す物質、ボソンは素粒子の分類で物質名ではない、クメンヒドロペルオキシドはクメン法の中間体。"},{"id":"q59","q":"次の操作を行ったとき、発生する気体は何か。硫化鉄に硫酸を加える。","a":"硫化水素","w":["酸素","二酸化硫黄","三酸化硫黄","水素"],"e":"FeS＋H₂SO₄→FeSO₄＋H₂S。弱酸H₂Sの遊離で、酸化還元ではないのでSO₂・SO₃は出ない。H₂も出ない。"},{"id":"q60","q":"次の操作を行ったとき、発生する気体は何か。亜硫酸ナトリウムに希硫酸を加える。","a":"二酸化硫黄","w":["硫化水素","水素","三酸化硫黄"],"e":"Na₂SO₃＋H₂SO₄→Na₂SO₄＋SO₂＋H₂O。弱酸（亜硫酸）の遊離で、H₂SO₃がSO₂とH₂Oに分かれる。Sの酸化数＋4のままなので、H₂S（−2）やSO₃（＋6）にはならない。"},{"id":"q61","q":"次の操作を行ったとき、発生する気体は何か。黄鉄鉱を燃焼させる。","a":"二酸化硫黄","w":["三酸化硫黄","硫化水素","発生しない"],"e":"黄鉄鉱FeS₂を燃やすとSが酸化されてSO₂になる（4FeS₂＋11O₂→2Fe₂O₃＋8SO₂）。燃焼だけではSO₃まで進まない（触媒V₂O₅が必要）。"},{"id":"q62","q":"次の操作を行ったとき、発生する気体は何か。硫黄を燃焼させた後、さらに酸化バナジウム触媒下で酸素と反応させる。","a":"三酸化硫黄","w":["二酸化硫黄","硫化水素","発生しない"],"e":"接触法：S→SO₂（燃焼）→SO₃（V₂O₅触媒で酸化）。触媒下でさらにO₂と反応させるのでSO₃。"},{"id":"q63","q":"次の操作を行ったとき、発生する気体は何か。亜硝酸アンモニウムを加熱分解する。","a":"窒素","w":["亜硝酸","一酸化窒素","二酸化窒素","アンモニア"],"e":"NH₄NO₂→N₂＋2H₂O。NH₄⁺のN（−3）とNO₂⁻のN（＋3）の間で酸化還元が起こり、N₂（0）になる。亜硝酸は気体ではない。"},{"id":"q64","q":"次の操作を行ったとき、発生する気体は何か。塩化アンモニウムと水酸化ナトリウムの混合物を加熱する。","a":"アンモニア","w":["水素","塩素","塩化水素","発生しない"],"e":"弱塩基の塩NH₄Clに強塩基NaOHを加えると、弱塩基NH₃が遊離する。Ca(OH)₂のときと同じ。HClやCl₂は出ない。"},{"id":"q65","q":"次の操作を行ったとき、発生する気体は何か。ハーバー・ボッシュ法","a":"アンモニア","w":["硫酸","二酸化窒素","硝酸","塩化水素"],"e":"ハーバー・ボッシュ法はN₂＋3H₂⇄2NH₃（触媒Fe₃O₄）。硫酸は接触法、硝酸・NO₂はオストワルト法で作る。"},{"id":"q66","q":"次の操作を行ったとき、発生する気体は何か。アンモニアを白金触媒下、燃焼させる。","a":"一酸化窒素","w":["二酸化窒素","窒素","水素"],"e":"オストワルト法の第1段階：4NH₃＋5O₂→4NO＋6H₂O。このNOが空気でNO₂になり、水と反応して硝酸になる。N₂やH₂にはならない。"},{"id":"q67","q":"次の操作を行ったとき、発生する気体は何か。一酸化窒素を空気に触れさせる。","a":"二酸化窒素","w":["一酸化窒素","アンモニア","水素","四酸化二窒素"],"e":"NOは空気中ですぐ酸化されて赤褐色のNO₂になる（2NO＋O₂→2NO₂）。N₂O₄はNO₂が二量体になったもので、「放置したとき」の答え。"},{"id":"q68","q":"次の操作を行ったとき、発生する気体は何か。二酸化窒素を水に溶かす。(同時に硝酸が生じる)","a":"一酸化窒素","w":["アンモニア","水素","酸素","窒素"],"e":"3NO₂＋H₂O→2HNO₃＋NO（自己酸化還元）。NO₂のN（＋4）が＋5（HNO₃）と＋2（NO）に分かれる。"},{"id":"q69","q":"次の操作を行ったとき、発生する気体は何か。二酸化窒素を空気中で放置する。","a":"四酸化二窒素","w":["アンモニア","一酸化窒素","水素","窒素"],"e":"NO₂は2分子がくっついて無色のN₂O₄になる（2NO₂⇄N₂O₄）。NOに戻ったりN₂まで分解したりはしない。"}]},{"name":"No.14-3 気体発生(3)","items":[{"id":"q70","q":"次の操作を行ったとき、発生する気体は何か。ギ酸に濃硫酸を加えて加熱する。","a":"一酸化炭素","w":["水素","酸素","二酸化硫黄","二酸化炭素"],"e":"HCOOH→CO＋H₂O。濃硫酸の脱水作用でギ酸からH₂Oが奪われる。濃硫酸は還元されないのでSO₂は出ない。"},{"id":"q71","q":"次の操作を行ったとき、主に発生する気体は何か。コークスを高温で燃焼させる。","a":"一酸化炭素","w":["二酸化炭素","メタン","アセチレン"],"e":"コークスを高温で燃やすと不完全燃焼で主にCOができる（2C＋O₂→2CO）。CO₂もできるが、工業的なCOの製法として覚える。メタン・アセチレンは生成しない。"},{"id":"q72","q":"次の操作を行ったとき、発生する気体は何か。炭酸カルシウムを加熱する。","a":"二酸化炭素","w":["酸素","水素","発生しない"],"e":"CaCO₃→CaO＋CO₂（炭酸塩の熱分解）。CO₂の工業的製法。O₂・H₂は出ない。"},{"id":"q73","q":"次の操作を行ったとき、発生する気体は何か。炭酸カルシウムに塩酸を加える。","a":"二酸化炭素","w":["塩素","水素","酸素","発生しない"],"e":"CaCO₃＋2HCl→CaCl₂＋H₂O＋CO₂。強酸が弱酸（炭酸）を追い出す「弱酸の遊離」。Cl⁻は酸化されないのでCl₂は出ない。"},{"id":"q74","q":"次の操作を行ったとき、発生する気体は何か。過酸化水素水に二酸化マンガンを加える。","a":"酸素のみ","w":["水素のみ","酸素と水素","発生しない"],"e":"2H₂O₂→2H₂O＋O₂（MnO₂は触媒）。H₂O₂は分解して水と酸素になるだけで、水素は出ない。"},{"id":"q75","q":"次の操作を行ったとき、発生する気体は何か。エタノールにナトリウムの単体を加える。","a":"水素","w":["酸素","ナトリウム","エチレン","発生しない"],"e":"エタノールはヒドロキシ基（−OH）をもつので、Naと反応してH₂を出す（2C₂H₅OH＋2Na→2C₂H₅ONa＋H₂）。エチレンは脱水で出る気体。"},{"id":"q76","q":"次の操作を行ったとき、発生する気体は何か。ジエチルエーテルにナトリウムの単体を加える。","a":"発生しない","w":["酸素","ナトリウム","エチレン","水素"],"e":"ジエチルエーテルは−OHをもたないので、Naと反応しない。アルコールとエーテルの区別に使う。"},{"id":"q77","q":"次の操作を行ったとき、発生する気体は何か。硫酸酸性の過マンガン酸カリウムに過酸化水素を加える。","a":"酸素","w":["水素","二酸化硫黄","硫化水素","発生しない"],"e":"KMnO₄は強い酸化剤なので、H₂O₂は還元剤としてはたらきO₂を出す（H₂O₂→O₂＋2H⁺＋2e⁻）。普段は酸化剤のH₂O₂も、KMnO₄が相手だと還元剤になる。"},{"id":"q78","q":"次の操作を行ったとき、発生する気体は何か。硫酸酸性の過マンガン酸カリウムにシュウ酸を加える。","a":"二酸化炭素","w":["水素","二酸化硫黄","硫化水素","酸素"],"e":"シュウ酸(COOH)₂は還元剤で、KMnO₄に酸化されてCO₂になる（(COOH)₂→2CO₂＋2H⁺＋2e⁻）。"},{"id":"q79","q":"次の操作を行ったとき、発生する気体は何か。ヨウ化カリウム水溶液にオゾンを通じる。","a":"酸素","w":["ヨウ素","酸化カリウム","水酸化カリウム","ヨウ化水素"],"e":"O₃がI⁻を酸化してI₂ができ、O₃自身はO₂になる（2KI＋O₃＋H₂O→I₂＋2KOH＋O₂）。I₂は生成するが固体（溶液中）なので気体ではない。"},{"id":"q80","q":"次の操作を行ったとき、発生する気体は何か。鉄鉱石を一酸化炭素で還元する。","a":"二酸化炭素","w":["水素","酸素","発生しない"],"e":"COが酸化鉄からOを奪って還元し、自身はCO₂になる（Fe₂O₃＋3CO→2Fe＋3CO₂）。"},{"id":"q81","q":"次の操作を行ったとき、発生する気体は何か。二酸化ケイ素と炭酸ナトリウムを混ぜて加熱する。","a":"二酸化炭素","w":["ケイ酸","水素","酸素","発生しない"],"e":"SiO₂＋Na₂CO₃→Na₂SiO₃＋CO₂。酸性酸化物SiO₂が塩基（の塩）と反応し、CO₂が追い出される。ケイ酸は固体で、塩酸を加えたときにできる。"},{"id":"q82","q":"次の操作を行ったとき、発生する気体は何か。過酸化水素水に二酸化硫黄を加える。","a":"発生しない","w":["酸素","水素","二酸化硫黄","三酸化硫黄"],"e":"SO₂＋H₂O₂→H₂SO₄。SO₂が還元剤、H₂O₂が酸化剤としてはたらき、硫酸ができるだけで気体は出ない。"}]},{"name":"No.15 沈殿・イオン反応part1","items":[{"id":"q83","q":"Cu²⁺、Ag⁺のうち、塩酸を加えたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"AgCl　白色","w":["CuCl₂　白色","CuCl₂　褐色","AgCl　褐色"],"e":"塩化物は基本的に水に溶けるが、例外のAg⁺・Pb²⁺は白色沈殿（AgCl・PbCl₂）。CuCl₂は水に溶けるので沈殿しない。AgClは白色（褐色はAg₂O）。"},{"id":"q84","q":"Cu²⁺、Zn²⁺、Ba²⁺、Ag⁺のうち、塩酸を加えたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"AgCl　白色","w":["ZnCl₂　白色","CuCl₂　青色","BaCl₂　黄色","AgCl₂　白色"],"e":"Cl⁻で沈殿するのはAg⁺・Pb²⁺だけで、AgClは白色。ZnCl₂・CuCl₂・BaCl₂は水に溶ける。Agは1価なので「AgCl₂」は存在しない。"},{"id":"q85","q":"Pb²⁺、Sn²⁺のうち、塩酸を加えたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"PbCl₂　白色","w":["SnCl₂　白色","PbCl₂　黄色","SnCl₂　黄色"],"e":"Pb²⁺はCl⁻と白色沈殿PbCl₂をつくる（熱水には溶ける）。SnCl₂は水に溶ける。PbCl₂は黄色ではない（黄色はPbCrO₄やPbI₂）。"},{"id":"q86","q":"Zn²⁺、Sn²⁺、Ag⁺のうち、塩酸を加えたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"AgCl　白色","w":["SnCl₂　白色","AgCl　褐色","SnCl₂　黄色","ZnCl₂　白色"],"e":"Cl⁻で沈殿するのはAg⁺（とPb²⁺）。AgClは白色。SnCl₂・ZnCl₂は水に溶ける。"},{"id":"q87","q":"Pb²⁺、Cu²⁺のうち、硫酸を加えたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"PbSO₄　白色","w":["CuSO₄　白色","PbSO₄　青色","CuSO₄　青色"],"e":"SO₄²⁻で沈殿するのはBa²⁺・Ca²⁺・Pb²⁺（バカにするな硫酸）で、PbSO₄は白色。CuSO₄は水に溶ける（青いのは溶液や五水和物の色）。"},{"id":"q88","q":"Zn²⁺、Ca²⁺のうち、硫酸を加えたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"CaSO₄　白色","w":["ZnSO₄　白色","CaSO₄　黄色","ZnSO₄　黄色"],"e":"SO₄²⁻で沈殿するのはBa²⁺・Ca²⁺・Pb²⁺（バカにするな硫酸）。CaSO₄は白色。ZnSO₄は水に溶ける。"},{"id":"q89","q":"Ba²⁺、Ni²⁺のうち、硫酸を加えたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"BaSO₄　白色","w":["NiSO₄　白色","BaSO₄　黄色","NiSO₄　青色"],"e":"BaSO₄は白色沈殿（X線造影剤）。NiSO₄は水に溶ける。硫酸塩の沈殿はすべて白色で、黄色ではない（黄色はBaCrO₄）。"},{"id":"q90","q":"Pb²⁺、Na⁺のうち、炭酸アンモニウムを加えたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"PbCO₃　白色","w":["Na₂CO₃　白色","PbCO₃　黄色","Na₂CO₃　黄色"],"e":"炭酸塩はアルカリ金属以外では沈殿しやすく、PbCO₃は白色沈殿。Na⁺などアルカリ金属の塩はすべて水に溶ける。"},{"id":"q91","q":"K⁺、Ca²⁺のうち炭酸アンモニウムを加えたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"CaCO₃　白色","w":["K₂CO₃　白色","CaCO₃　黄色","K₂CO₃　黄色"],"e":"CO₃²⁻で沈殿するのはBa²⁺・Ca²⁺（バカにする炭酸）で、CaCO₃は白色。K⁺などアルカリ金属の塩は水に溶ける。"},{"id":"q92","q":"Ba²⁺、Na⁺のうち、硫酸を加えたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"BaSO₄　白色","w":["Na₂SO₄　白色","BaSO₄　黄色","Na₂SO₄　黄色"],"e":"SO₄²⁻で沈殿するのはBa²⁺・Ca²⁺・Pb²⁺（バカにするな硫酸）で、BaSO₄は白色。Na⁺の塩はすべて水に溶ける。"},{"id":"q93","q":"塩酸を加えたときに沈殿する陽イオンの組み合わせとして最も適当なものはどれか。1つ選べ。","a":"Pb²⁺、Ag⁺","w":["Ba²⁺、Ag⁺","Cu²⁺、Ag⁺","Pb²⁺、Ca²⁺","Pb²⁺、Cu²⁺"],"e":"塩化物の沈殿はAgCl・PbCl₂（・Hg₂Cl₂）だけ。Ba²⁺・Ca²⁺は硫酸・炭酸で沈殿するイオン、Cu²⁺の塩化物は水に溶ける。"}]},{"name":"No.16 沈殿・イオン反応part2","items":[{"id":"q142","q":"Ag⁺、Pb²⁺のうち、クロム酸カリウム水溶液を加えたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"Ag₂CrO₄　赤褐色","w":["PbCrO₄　赤褐色","Ag₂CrO₄　黄色","PbCrO₄　白色","Ag₂CrO₄　白色"],"e":"CrO₄²⁻と沈殿するのはAg⁺・Pb²⁺・Ba²⁺。Ag₂CrO₄は赤褐色、PbCrO₄・BaCrO₄は黄色。クロム酸塩の沈殿に白色はない。"},{"id":"q143","q":"Pb²⁺、Ba²⁺、Ag⁺のうち、クロム酸カリウムを加えたときに黄色沈殿を生じる物質の組み合わせとして正しいものはどれか。1つ選べ。","a":"PbCrO₄とBaCrO₄","w":["PbCrO₄とAg₂CrO₄","BaCrO₄とAg₂CrO₄","Ag₂CrO₄のみ"],"e":"PbCrO₄・BaCrO₄は黄色、Ag₂CrO₄は赤褐色。黄色沈殿はPbとBaの2つ。"},{"id":"q144","q":"Ba²⁺、Ag⁺のうち、クロム酸カリウム水溶液を加えたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"BaCrO₄　黄色","w":["Ag₂CrO₄　黄色","BaCrO₄　赤褐色","BaCrO₄　白色","Ag₂CrO₄　白色"],"e":"Ba²⁺もAg⁺もCrO₄²⁻と沈殿するが、BaCrO₄は黄色、Ag₂CrO₄は赤褐色。白色のクロム酸塩はない。"},{"id":"q145","q":"Cu²⁺、Zn²⁺のうち、水酸化ナトリウム水溶液を少量加えたときに沈殿する物質の化学式と色の組み合わせとして正しいものはどれか。1つ選べ。","a":"Cu(OH)₂　青白色","w":["Zn(OH)₂　青白色","Cu(OH)₂　白色","Zn(OH)₂　緑白色"],"e":"Cu(OH)₂は青白色の沈殿。Zn(OH)₂も少量のNaOHで沈殿するが白色（青白色ではない）。緑白色はFe(OH)₂。"},{"id":"q146","q":"Fe²⁺、Zn²⁺のうち、水酸化ナトリウム水溶液を少量加えたときに沈殿する物質の化学式と色の組み合わせとして正しいものはどれか。1つ選べ。","a":"Fe(OH)₂　緑白色","w":["Fe(OH)₂　青白色","Zn(OH)₂　青白色","Fe(OH)₂　白色","Zn(OH)₂　緑白色"],"e":"Fe(OH)₂は緑白色。Zn(OH)₂も沈殿するが白色。青白色はCu(OH)₂の色。"},{"id":"q147","q":"Fe³⁺、Ag⁺のうち、水酸化ナトリウム水溶液を少量加えたときに沈殿する物質の化学式と色の組み合わせとして正しいものはどれか。1つ選べ。","a":"Ag₂O　褐色","w":["Fe(OH)₃　褐色","Fe(OH)₃　白色","Fe(OH)₃　緑白色","Ag₂O　白色"],"e":"Ag⁺にOH⁻を加えるとAgOHはすぐAg₂O（褐色）に変わる。Fe(OH)₃も沈殿するが赤褐色で、白色・緑白色ではない（緑白色はFe(OH)₂）。"},{"id":"q148","q":"Cu²⁺、Fe³⁺のうち、水酸化ナトリウム水溶液を少量加えたときに沈殿する物質の化学式と色の組み合わせとして正しいものはどれか。1つ選べ。","a":"Fe(OH)₃　赤褐色","w":["Cu(OH)₂　赤褐色","Cu(OH)₂　緑白色","Fe(OH)₃　青白色","Fe(OH)₃　白色"],"e":"Fe(OH)₃は赤褐色。Cu(OH)₂も沈殿するが青白色で、赤褐色・緑白色ではない。"},{"id":"q149","q":"塩基性条件でも水酸化物の沈殿を生じない陽イオンの組み合わせとして最も適当なものはどれか。1つ選べ。","a":"Na⁺、K⁺","w":["Na⁺、Cu²⁺","K⁺、Fe³⁺","Cu²⁺、Fe³⁺"],"e":"アルカリ金属の水酸化物（NaOH・KOH）は水によく溶けるので沈殿しない。Cu²⁺はCu(OH)₂、Fe³⁺はFe(OH)₃の沈殿をつくる。"},{"id":"q150","q":"Cu²⁺、Ba²⁺のうち、酸性条件で硫化水素を通じたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"CuS　黒色","w":["BaS　黒色","CuS　白色","CuS　黄色","BaS　白色"],"e":"Cuはイオン化傾向が小さく、酸性でも硫化物CuS（黒色）が沈殿する。Ba²⁺は液性によらず硫化物の沈殿をつくらない。"},{"id":"q151","q":"Zn²⁺、Fe²⁺のうち、中性・塩基性条件で硫化水素を通じたときに沈殿する物質の化学式と色の組み合わせとして正しいものはどれか。1つ選べ。","a":"ZnS　白色","w":["FeS　白色","ZnS　黒色","FeS　淡桃色"],"e":"ZnSは白色（硫化物で唯一の白）。FeSも中性・塩基性で沈殿するが黒色。淡桃色はMnS。"},{"id":"q152","q":"Cu²⁺、Sn²⁺、Zn²⁺のうち、中性・塩基性条件で硫化水素を通じたときに沈殿する物質の化学式と色の組み合わせとして正しいものはどれか。1つ選べ。","a":"SnS　褐色","w":["ZnS　褐色","CuS　白色","ZnS　黄色","SnS　白色"],"e":"中性・塩基性では3つとも沈殿するが、色はSnS褐色・CuS黒色・ZnS白色。ZnSを褐色・黄色、CuSを白色とするのは誤り。"},{"id":"q153","q":"Cd²⁺、Zn²⁺のうち、酸性条件で硫化水素を通じたときに沈殿する物質の化学式と色はどれか。1つ選べ。","a":"CdS　黄色","w":["ZnS　黄色","CdS　白色","CdS　黒色","ZnS　白色"],"e":"Cdは酸性でも硫化物が沈殿する側で、CdSは黄色。ZnSは酸性では沈殿しない（中性・塩基性で白色）。"},{"id":"q154","q":"Fe²⁺、Cu²⁺、Ag⁺、Sn²⁺のうち、酸性条件で硫化水素を通じても沈殿を生じないのはどれか。1つ選べ。","a":"Fe²⁺","w":["Cu²⁺","Ag⁺","Sn²⁺"],"e":"イオン化傾向が中くらいのZn・Fe・Niは、中性・塩基性でしか硫化物が沈殿しない。Sn・Pb・Cu・Hg・Agは酸性でも沈殿する。"},{"id":"q155","q":"Li⁺、Al³⁺、Zn²⁺、Cu²⁺のうち、酸性条件で硫化水素を通じても沈殿を生じないものの組み合わせとして正しいものはどれか。1つ選べ。","a":"Li⁺、Al³⁺、Zn²⁺","w":["Li⁺、Cu²⁺","Al³⁺、Zn²⁺、Cu²⁺","4つとも沈殿を生じない"],"e":"Liは液性によらず沈殿しない。Alは硫化物をつくらない（塩基性で水酸化物になる）。Znは中性・塩基性でのみ沈殿。Cu²⁺は酸性でもCuSが沈殿する。"},{"id":"q156","q":"Pb²⁺、Zn²⁺、Ba²⁺のうち、中性条件で硫化水素を通じたときに沈殿するものはどれか。1つ選べ。","a":"ZnSとPbS","w":["すべて","ZnS","PbS","ZnSとBaS"],"e":"中性ならZn²⁺（ZnS白）もPb²⁺（PbS黒）も沈殿する。Ba²⁺は液性によらず硫化物が沈殿しない（イオン化傾向が大きい）。"}]},{"name":"No.17 錯イオンpart3","items":[{"id":"q157","q":"Ag⁺、Cu²⁺、Zn²⁺のうち、過剰のアンモニア水を加えたときに溶液が深青色になるのはどれか。1つ選べ。","a":"Cu²⁺","w":["Ag⁺","Zn²⁺","いずれも深青色になる"],"e":"NH₃過剰で錯イオンをつくるのはAg⁺・Zn²⁺・Cu²⁺だが、色がつくのは[Cu(NH₃)₄]²⁺（深青色）だけ。Ag・Znの錯イオンは無色。"},{"id":"q158","q":"Ag⁺水溶液に過剰のアンモニア水を加えたときに生じる錯イオンとその名称の組み合わせとして正しいものはどれか。1つ選べ。","a":"[Ag(NH₃)₂]⁺　ジアンミン銀(Ⅰ)イオン","w":["[Ag(NH₃)₄]⁺　テトラアンミン銀(Ⅰ)イオン","[Ag(NH₃)₂]⁺　テトラアンミン銀(Ⅰ)イオン","[Ag(NH₃)₄]⁺　ジアンミン銀(Ⅰ)イオン"],"e":"Ag⁺の配位数は2なので[Ag(NH₃)₂]⁺、2＝ジなのでジアンミン銀(Ⅰ)イオン。テトラ＝4。"},{"id":"q159","q":"Zn²⁺水溶液に過剰のアンモニア水を加えたときに生じる錯イオンの化学式と、その立体構造の組み合わせとして正しいものはどれか。1つ選べ。","a":"[Zn(NH₃)₄]²⁺　正四面体","w":["[Zn(NH₃)₄]²⁺　正方形(平面四角形)","[Zn(NH₃)₆]²⁺　正四面体","[Zn(NH₃)₄]²⁺　正八面体"],"e":"[Zn(NH₃)₄]²⁺（配位数4）は正四面体。同じ4配位でもCuは正方形。正八面体は6配位（Feなど）。"},{"id":"q160","q":"[Cu(NH₃)₄]²⁺、[Zn(NH₃)₄]²⁺のうち、正方形(平面四角形)の構造をとるのはどれか。1つ選べ。","a":"[Cu(NH₃)₄]²⁺","w":["[Zn(NH₃)₄]²⁺","どちらも正方形(平面四角形)","どちらも正四面体"],"e":"4配位でもCu²⁺は正方形（平面四角形）、Zn²⁺は正四面体。亜鉛と銅の錯体の形はよく問われる。"},{"id":"q161","q":"Al³⁺水溶液に過剰の水酸化ナトリウム水溶液を加えたときに生じる錯イオンの化学式と名称の組み合わせとして正しいものはどれか。1つ選べ。","a":"[Al(OH)₄]⁻　テトラヒドロキシドアルミン酸イオン","w":["[Al(OH)₄]³⁻　テトラヒドロキシドアルミン酸イオン","[Al(OH)₆]³⁻　ヘキサヒドロキシドアルミン酸イオン","[Al(OH)₄]⁻　テトラヒドロキシド亜鉛酸イオン"],"e":"Al³⁺（＋3）にOH⁻（−1）が4つで、全体は−1：[Al(OH)₄]⁻。名前はテトラヒドロキシドアルミン酸イオン（陰イオンなので「〜酸イオン」、Alだけ「アルミン」）。亜鉛酸はZnの場合。"},{"id":"q162","q":"Ag⁺、Al³⁺のうち、アンモニア水を過剰に加えたときに錯イオンを形成するものはどちらか。またその時の溶液の色は何色か。1つ選べ。","a":"Ag⁺　無色","w":["Ag⁺　深青色","Al³⁺　無色","Al³⁺　深青色"],"e":"Ag⁺はNH₃過剰で[Ag(NH₃)₂]⁺（無色）をつくる。Al³⁺はNH₃では錯イオンをつくらず、Al(OH)₃が沈殿したまま（OH⁻過剰なら溶ける）。深青色はCuの錯イオン。"},{"id":"q163","q":"Zn²⁺、Ca²⁺のうち、アンモニア水を過剰に加えたときに錯イオンを形成するものはどちらか。またその時の溶液の色は何色か。1つ選べ。","a":"Zn²⁺　無色","w":["Zn²⁺　深青色","Ca²⁺　無色","Ca²⁺　深青色"],"e":"Zn²⁺はNH₃過剰で[Zn(NH₃)₄]²⁺（無色）をつくる。Ca²⁺は錯イオンをつくらない。深青色はCuの錯イオン。"},{"id":"q164","q":"Cu²⁺、Fe³⁺のうち、アンモニア水を過剰に加えたときに錯イオンを形成するものはどちらか。またその時の溶液の色は何色か。1つ選べ。","a":"Cu²⁺　深青色","w":["Cu²⁺　無色","Fe³⁺　深青色","Fe³⁺　無色"],"e":"Cu²⁺はNH₃過剰で深青色の[Cu(NH₃)₄]²⁺をつくる。Fe³⁺はNH₃では錯イオンをつくらず、赤褐色のFe(OH)₃が沈殿したまま。"},{"id":"q165","q":"Al³⁺、Cu²⁺のうち、水酸化ナトリウム水溶液を過剰に加えたときに錯イオンを形成するものはどちらか。またその時の溶液の色は何色か。1つ選べ。","a":"Al³⁺　無色","w":["Al³⁺　深青色","Cu²⁺　無色","Cu²⁺　深青色"],"e":"NaOH過剰で溶けるのは両性元素（ああすんなり：Al Zn Sn Pb）で、Al³⁺は無色の[Al(OH)₄]⁻になる。Cu(OH)₂はNaOH過剰でも溶けない。"},{"id":"q166","q":"Sn²⁺、Ag⁺のうち、水酸化ナトリウム水溶液を過剰に加えたときに錯イオンを形成するものはどちらか。またその時の溶液の色は何色か。1つ選べ。","a":"Sn²⁺　無色","w":["Sn²⁺　白色","Ag⁺　無色","Ag⁺　褐色"],"e":"Snは両性元素なので、NaOH過剰で無色の[Sn(OH)₄]²⁻になる。錯イオンの溶液なので白色ではない。Ag⁺は褐色のAg₂Oが沈殿したまま。"},{"id":"q167","q":"Fe²⁺、Fe³⁺のうち、KSCN(チオシアン酸カリウム)を加えると反応するのはどちらか。またその時の溶液の色は何色か。1つ選べ。","a":"Fe³⁺　血赤色","w":["Fe²⁺　血赤色","Fe²⁺　深青色","Fe³⁺　深青色"],"e":"KSCNはFe³⁺と反応して血赤色の溶液になる。Fe²⁺とは反応しない。深青色（濃青色沈殿）はヘキサシアニド鉄酸カリウムとの反応。"},{"id":"q168","q":"Pb²⁺、Fe²⁺のうち、水酸化ナトリウム水溶液を過剰に加えたときに錯イオンを形成するものはどちらか。またその時の溶液の色は何色か。1つ選べ。","a":"Pb²⁺　無色","w":["Pb²⁺　緑白色","Fe²⁺　無色","Fe²⁺　緑白色"],"e":"Pbは両性元素なので、NaOH過剰で無色の[Pb(OH)₄]²⁻になる。Fe²⁺は緑白色のFe(OH)₂が沈殿したまま溶けない。"},{"id":"q169","q":"Zn²⁺、Cu²⁺のうち、水酸化ナトリウム水溶液を過剰に加えたときに錯イオンを形成するものはどちらか。またその時の溶液の色は何色か。1つ選べ。","a":"Zn²⁺　無色","w":["Zn²⁺　深青色","Cu²⁺　無色","Cu²⁺　深青色"],"e":"Znは両性元素なので、NaOH過剰で無色の[Zn(OH)₄]²⁻になる。Cu(OH)₂はNaOH過剰では溶けない（NH₃過剰なら深青色に）。"},{"id":"q170","q":"Ag⁺、Cu²⁺のうち、チオ硫酸ナトリウム水溶液を過剰に加えたときに錯イオンを形成するものはどちらか。またその時の溶液の色は何色か。1つ選べ。","a":"Ag⁺　無色","w":["Ag⁺　深青色","Cu²⁺　無色","Cu²⁺　深青色"],"e":"Ag⁺はチオ硫酸イオンと無色の[Ag(S₂O₃)₂]³⁻をつくる（写真の定着）。Cu²⁺はチオ硫酸で錯イオンをつくらない（高校範囲）。深青色はCuのアンミン錯イオン。"},{"id":"q171","q":"Zn²⁺、Al³⁺、Ag⁺、Cu²⁺、Sn²⁺のうち、アンモニア水を過剰に加えても、水酸化ナトリウム水溶液を過剰に加えても錯イオンを形成するものはどれか。1つ選べ。","a":"Zn²⁺","w":["Al³⁺","Ag⁺","Cu²⁺","Sn²⁺"],"e":"ZnはNH₃過剰で[Zn(NH₃)₄]²⁺、OH⁻過剰で[Zn(OH)₄]²⁻の両方をつくる。Al・SnはOH⁻だけ、Ag・CuはNH₃だけ。"}]}]},{"key":"pol","label":"高分子","icon":"🧬","img":"../polymer-quest/assets/memo/","decks":[{"name":"No.1 単糖の構造式","items":[{"id":"p1ae95d69","q":"名称を答えよ。","a":"α-グルコース","w":["β-グルコース","α-ガラクトース","α-マンノース","β-フルクトース"],"e":"1位のOHが下向きなのでα-グルコース（OHは酸素の左隣から「上下上下下」）。β-グルコースは1位のOHが上向き、α-ガラクトースは4位、α-マンノースは2位のOHが逆、β-フルクトースは五員環。","img":"α-グルコース.jpg"},{"id":"pd49d2916","q":"名称を答えよ。","a":"β-グルコース","w":["α-グルコース","β-ガラクトース","α-マンノース","β-フルクトース"],"e":"1位のOHが上向きなのでβ-グルコース。α-グルコースは1位のOHが下向き、β-ガラクトースは4位、α-マンノースは2位のOHが逆、β-フルクトースは五員環。","img":"β-グルコース.jpg"},{"id":"p36c05c7b","q":"名称を答えよ。","a":"グルコース","w":["フルクトース","ガラクトース","マンノース","マルトース"],"e":"鎖状で1位がアルデヒド基（−CHO）なのでグルコース（鎖状構造）。フルクトースは2位がケトン基、ガラクトース・マンノースはOHの向きが違う、マルトースは二糖。","img":"グルコース(鎖状構造).png"},{"id":"p42152c7e","q":"名称を答えよ。","a":"β-ガラクトース","w":["β-グルコース","α-ガラクトース","α-マンノース","α-グルコース"],"e":"1位のOHが上向き（β）で、β-グルコースと4位のOHの向きだけが逆なのでβ-ガラクトース（ラクトースの構成単糖）。β-グルコースは4位も同じ向き、α-ガラクトースは1位が下向き、α-マンノースは2位が逆。","img":"β-ガラクトース.png"},{"id":"p2e7c3b12","q":"名称を答えよ。","a":"α-マンノース","w":["α-グルコース","α-ガラクトース","β-グルコース","β-ガラクトース"],"e":"1位のOHが下向き（α）で、α-グルコースと2位のOHの向きだけが逆なのでα-マンノース。α-ガラクトースは4位が逆、β-グルコース・β-ガラクトースは1位が上向き。","img":"α-マンノース.jpg"},{"id":"p4e66be99","q":"名称を答えよ。","a":"β-フルクトース","w":["α-グルコース","β-グルコース","β-ガラクトース","α-マンノース"],"e":"五員環で、2位のOHが上向きなのでβ-フルクトース（スクロースの構成単糖）。グルコース・ガラクトース・マンノースはどれも六員環。","img":"β-フルクトース(五員環).jpg"},{"id":"p7ca1ceb8","q":"名称を答えよ。","a":"β-フルクトース","w":["β-グルコース","α-グルコース","α-マンノース","α-ガラクトース"],"e":"6位のOHと2位のCがつながった六員環のβ-フルクトース。環の酸素の隣の炭素にCH₂OHとOHが両方つく。グルコース・マンノース・ガラクトースは1位にOHとHがつく。","img":"β-フルクトース(六員環).jpg"},{"id":"pdcaec69a","q":"名称を答えよ。","a":"フルクトース","w":["グルコース","ガラクトース","マンノース","スクロース"],"e":"鎖状で2位がケトン基（C=O）なのでフルクトース（鎖状構造）。−CO−CH₂OH の構造が還元性を示す。グルコースは1位がアルデヒド基、スクロースは二糖。","img":"フルクトース(鎖状構造).png"},{"id":"p41d61955","q":"この単糖はβ-グルコースと比べて何位の炭素の立体配置が異なるか。","a":"4位","w":["2位","1位","3位","5位"],"e":"ガラクトースはグルコースと4位のOHの向きだけが逆。2位が逆なのはマンノース。1位が逆なのはα・βの違い。","img":"β-ガラクトース.png"},{"id":"pad5c03a7","q":"この単糖はα-グルコースと比べて何位の炭素の立体配置が異なるか。","a":"2位","w":["4位","1位","3位","5位"],"e":"マンノースはグルコースと2位のOHの向きだけが逆。4位が逆なのはガラクトース。1位が逆なのはα・βの違い。","img":"α-マンノース.jpg"},{"id":"p1ba4ca17","q":"この構造で還元性の原因となる官能基は何か。","a":"ホルミル基(アルデヒド基)","w":["ヒドロキシ基","カルボキシ基","ケトン基","エーテル結合"],"e":"鎖状のグルコースの1位にあるホルミル基（アルデヒド基、−CHO）が還元性の原因。ヒドロキシ基は還元性を示さない。ケトン基はフルクトースの鎖状構造にある。","img":"グルコース(鎖状構造).png"}]},{"name":"No.2 二糖の構造式","items":[{"id":"p0da25e4a","q":"名称を答えよ。","a":"マルトース","w":["セロビオース","トレハロース","ラクトース","スクロース"],"e":"α-グルコース2分子が1位と4位で結合したマルトース（還元性あり）。セロビオースはβ-グルコース2分子、ラクトースはβ-ガラクトース＋グルコース、スクロースはグルコース＋フルクトース、トレハロースは1位どうしで結合。","img":"マルトース.jpg"},{"id":"pf66e09f7","q":"名称を答えよ。","a":"セロビオース","w":["マルトース","ラクトース","スクロース","トレハロース"],"e":"β-グルコース2分子が1位と4位で結合したセロビオース（右側が上下反転している）。マルトースはα-グルコース2分子、ラクトースは左側がβ-ガラクトース。","img":"セロビオース.jpg"},{"id":"p1107936c","q":"名称を答えよ。","a":"スクロース","w":["マルトース","トレハロース","ラクトース","セロビオース"],"e":"α-グルコースとβ-フルクトース（五員環）が1位と2位で結合したスクロース（還元性なし）。他の二糖はどれもグルコースやガラクトースの六員環どうし。","img":"スクロース.jpg"},{"id":"p79671da8","q":"名称を答えよ。","a":"ラクトース","w":["セロビオース","マルトース","スクロース","トレハロース"],"e":"β-ガラクトースとグルコースが1位と4位で結合したラクトース。セロビオースと左側の4位のOHの向きだけが違う。マルトースはα-グルコース2分子。","img":"ラクトース.jpg"},{"id":"pebc36e25","q":"名称を答えよ。","a":"トレハロース","w":["マルトース","スクロース","セロビオース","ラクトース"],"e":"α-グルコース2分子が1位どうしで結合したトレハロース（還元性なし）。マルトースは1位と4位、スクロースはグルコースとフルクトース。","img":"トレハロース.png"},{"id":"p051b6bea","q":"この二糖を構成する単糖を答えよ。","a":"α-グルコース2分子","w":["β-グルコース2分子","α-グルコース＋β-フルクトース","β-ガラクトース＋グルコース","α-グルコース＋β-ガラクトース"],"e":"マルトースはα-グルコース2分子からなる（1,4-グリコシド結合）。β-グルコース2分子はセロビオース、α-グルコース＋β-フルクトースはスクロース、β-ガラクトース＋グルコースはラクトース。","img":"マルトース.jpg"},{"id":"pbb7c0391","q":"この二糖の単糖どうしの結合を答えよ。","a":"1,4-グリコシド結合","w":["1,2-グリコシド結合","1,1-グリコシド結合","1,6-グリコシド結合"],"e":"マルトースは1位と4位がつながった1,4-グリコシド結合。1,2-はスクロース、1,1-はトレハロース、1,6-はアミロペクチンの枝分かれ部分。","img":"マルトース.jpg"},{"id":"pe7dce2e6","q":"この二糖は還元性を示すか。","a":"あり","w":["なし"],"e":"マルトースは右側のグルコースのヘミアセタール構造（同じCにOHとORがつく）が残っていて、開環してアルデヒド基を生じるので還元性あり。","img":"マルトース.jpg"},{"id":"p17a92daf","q":"この二糖を構成する単糖を答えよ。","a":"β-グルコース2分子","w":["α-グルコース2分子","α-グルコース＋β-フルクトース","β-ガラクトース＋グルコース","α-グルコース＋β-ガラクトース"],"e":"セロビオースはβ-グルコース2分子からなる（1,4-グリコシド結合）。α-グルコース2分子はマルトースやトレハロース、α-グルコース＋β-フルクトースはスクロース。","img":"セロビオース.jpg"},{"id":"p2821927a","q":"この二糖の単糖どうしの結合を答えよ。","a":"1,4-グリコシド結合","w":["1,2-グリコシド結合","1,1-グリコシド結合","1,6-グリコシド結合"],"e":"セロビオースは1位と4位がつながった1,4-グリコシド結合。1,2-はスクロース、1,1-はトレハロース、1,6-はアミロペクチンの枝分かれ部分。","img":"セロビオース.jpg"},{"id":"p0ac09772","q":"この二糖は還元性を示すか。","a":"あり","w":["なし"],"e":"セロビオースは右側のグルコースのヘミアセタール構造が残っているので還元性あり。","img":"セロビオース.jpg"},{"id":"p61e0ea4a","q":"この二糖を構成する単糖を答えよ。","a":"α-グルコース＋β-フルクトース","w":["α-グルコース2分子","β-グルコース2分子","β-ガラクトース＋グルコース","α-グルコース＋β-ガラクトース"],"e":"スクロースはα-グルコースとβ-フルクトースからなる。α-グルコース2分子はマルトースやトレハロース、β-ガラクトース＋グルコースはラクトース。","img":"スクロース.jpg"},{"id":"p738656cd","q":"この二糖の単糖どうしの結合を答えよ。","a":"1,2-グリコシド結合","w":["1,4-グリコシド結合","1,1-グリコシド結合","1,6-グリコシド結合"],"e":"スクロースはグルコースの1位とフルクトースの2位がつながった1,2-グリコシド結合。1,4-はマルトース・セロビオース・ラクトース、1,1-はトレハロース。","img":"スクロース.jpg"},{"id":"p72854a14","q":"この二糖は還元性を示すか。","a":"なし","w":["あり"],"e":"スクロースはグルコースの1位とフルクトースの2位（どちらも還元性を生む部分）が結合に使われ、ヘミアセタール構造が残らないので還元性なし。","img":"スクロース.jpg"},{"id":"p1f0bba72","q":"この二糖を構成する単糖を答えよ。","a":"β-ガラクトース＋グルコース","w":["α-グルコース2分子","β-グルコース2分子","α-グルコース＋β-フルクトース","α-グルコース＋β-ガラクトース"],"e":"ラクトースはβ-ガラクトースとグルコースからなる。β-グルコース2分子はセロビオース、α-グルコース2分子はマルトースやトレハロース、α-グルコース＋β-フルクトースはスクロース。","img":"ラクトース.jpg"},{"id":"p66b35aef","q":"この二糖の単糖どうしの結合を答えよ。","a":"1,4-グリコシド結合","w":["1,2-グリコシド結合","1,1-グリコシド結合","1,6-グリコシド結合"],"e":"ラクトースは1位と4位がつながった1,4-グリコシド結合。1,2-はスクロース、1,1-はトレハロース、1,6-はアミロペクチンの枝分かれ部分。","img":"ラクトース.jpg"},{"id":"p70d617b2","q":"この二糖は還元性を示すか。","a":"あり","w":["なし"],"e":"ラクトースは右側のグルコースのヘミアセタール構造が残っているので還元性あり。","img":"ラクトース.jpg"},{"id":"p403fcd61","q":"この二糖を構成する単糖を答えよ。","a":"α-グルコース2分子","w":["β-グルコース2分子","α-グルコース＋β-フルクトース","β-ガラクトース＋グルコース","α-グルコース＋β-ガラクトース"],"e":"トレハロースはα-グルコース2分子からなる（1位どうしで結合）。マルトースも同じα-グルコース2分子だが1,4-結合。","img":"トレハロース.png"},{"id":"pb5c75ceb","q":"この二糖の単糖どうしの結合を答えよ。","a":"1,1-グリコシド結合","w":["1,4-グリコシド結合","1,2-グリコシド結合","1,6-グリコシド結合"],"e":"トレハロースは1位どうしがつながった1,1-グリコシド結合。1,4-はマルトースなど、1,2-はスクロース。","img":"トレハロース.png"},{"id":"pc71f94d6","q":"この二糖は還元性を示すか。","a":"なし","w":["あり"],"e":"トレハロースは両方のグルコースの1位（還元性を生む部分）が結合に使われ、ヘミアセタール構造が残らないので還元性なし。","img":"トレハロース.png"}]},{"name":"No.3 多糖","items":[{"id":"pcb969f81","q":"デンプンを構成する単糖は何か。","a":"α-グルコース","w":["β-グルコース","β-フルクトース","α-ガラクトース","β-ガラクトース"],"e":"デンプン（アミロース・アミロペクチン）はα-グルコースからなる。β-グルコースからなるのはセルロース。"},{"id":"pd7924965","q":"セルロースを構成する単糖は何か。","a":"β-グルコース","w":["α-グルコース","β-フルクトース","α-ガラクトース","β-ガラクトース"],"e":"セルロースはβ-グルコースからなる。α-グルコースからなるのはデンプンとグリコーゲン。"},{"id":"pb477af34","q":"α-グルコースからなる多糖をすべて選べ。","a":"アミロース・アミロペクチン・グリコーゲン","w":["セルロース"],"e":"アミロース・アミロペクチン・グリコーゲンはα-グルコースからなる。セルロースはβ-グルコースからなる。"},{"id":"pf90f87a6","q":"デンプンは何と何の混合物か。","a":"アミロースとアミロペクチン","w":["アミロースとグリコーゲン","アミロペクチンとセルロース","グリコーゲンとセルロース"],"e":"デンプンはアミロースとアミロペクチンの混合物。グリコーゲンは動物の多糖、セルロースは植物の細胞壁の多糖。"},{"id":"pf3c61fc3","q":"多糖類の分子式として正しいものはどれか。","a":"(C₆H₁₀O₅)ₙ","w":["C₆H₁₂O₆","C₁₂H₂₂O₁₁","(C₆H₁₂O₆)ₙ","(C₁₂H₂₂O₁₁)ₙ"],"e":"グルコースC₆H₁₂O₆が水を1分子ずつ失ってつながるので(C₆H₁₀O₅)ₙ。C₆H₁₂O₆は単糖、C₁₂H₂₂O₁₁は二糖。"},{"id":"p7f9a8c88","q":"多糖類は還元性を示すか。","a":"示さない","w":["示す"],"e":"多糖類は単糖が多数つながっていて、還元性を生む部分がほとんど残らないので還元性を示さない。"},{"id":"pc08bdfb9","q":"デンプンの成分のうち、温水に溶けるものはどれか。","a":"アミロース","w":["アミロペクチン"],"e":"アミロースは温水に溶ける。アミロペクチンは枝分かれが多く、温度によらず水に溶けにくい。"},{"id":"p1cef11fa","q":"デンプンの成分のうち、枝分かれが多く分子量が大きいものはどれか。","a":"アミロペクチン","w":["アミロース"],"e":"アミロペクチンは枝分かれが多く、分子量が大きい。アミロースは直鎖状で分子量が比較的小さい。"},{"id":"pf282b142","q":"デンプンの成分のうち、糖鎖が直鎖状で分子量が比較的小さいものはどれか。","a":"アミロース","w":["アミロペクチン"],"e":"アミロースは糖鎖が直鎖状で、分子量が比較的小さい。アミロペクチンは枝分かれが多く分子量が大きい。"},{"id":"p62258b96","q":"枝分かれ構造をもつ多糖をすべて選べ。","a":"アミロペクチン・グリコーゲン","w":["アミロース","セルロース"],"e":"アミロペクチンとグリコーゲンは1,6-グリコシド結合で枝分かれしている（グリコーゲンの方が多い）。アミロース・セルロースは直鎖状。"},{"id":"p87ef3631","q":"らせん構造をもつ多糖をすべて選べ。","a":"アミロース・アミロペクチン・グリコーゲン","w":["セルロース"],"e":"α-グルコースからなるアミロース・アミロペクチン・グリコーゲンはらせん構造をとる。セルロースはβ-グルコースからなり、まっすぐな直鎖状。"},{"id":"p85b09317","q":"糖鎖が直鎖状(枝分かれなし)の多糖をすべて選べ。","a":"アミロース・セルロース","w":["アミロペクチン","グリコーゲン"],"e":"アミロースとセルロースは枝分かれのない直鎖状。アミロペクチン・グリコーゲンは枝分かれがある。"},{"id":"p5d8f6ffc","q":"アミロースに含まれるグリコシド結合をすべて選べ。","a":"1,4-グリコシド結合","w":["1,6-グリコシド結合","1,2-グリコシド結合","1,1-グリコシド結合"],"e":"アミロースは枝分かれのない直鎖状なので、1,4-グリコシド結合だけ。1,6-はアミロペクチンなどの枝分かれ部分、1,2-はスクロース、1,1-はトレハロース。"},{"id":"p38b00f39","q":"アミロペクチンに含まれるグリコシド結合をすべて選べ。","a":"1,4-グリコシド結合・1,6-グリコシド結合","w":["1,2-グリコシド結合","1,1-グリコシド結合"],"e":"アミロペクチンは1,4-グリコシド結合でつながり、枝分かれ部分は1,6-グリコシド結合。1,2-はスクロース、1,1-はトレハロース。"},{"id":"p52950aab","q":"セルロースに含まれるグリコシド結合をすべて選べ。","a":"1,4-グリコシド結合","w":["1,6-グリコシド結合","1,2-グリコシド結合","1,1-グリコシド結合"],"e":"セルロースは枝分かれのない直鎖状なので、1,4-グリコシド結合だけ。"},{"id":"p080dab4d","q":"アミロペクチンなどの枝分かれ部分の結合はどれか。","a":"1,6-グリコシド結合","w":["1,4-グリコシド結合","1,2-グリコシド結合","1,1-グリコシド結合"],"e":"アミロペクチン・グリコーゲンの枝分かれ部分は1,6-グリコシド結合。主な鎖は1,4-グリコシド結合。"},{"id":"p738db918","q":"動物の筋肉や肝臓に多く含まれる多糖はどれか。","a":"グリコーゲン","w":["アミロース","アミロペクチン","セルロース"],"e":"グリコーゲンは動物の筋肉や肝臓に多く含まれる多糖。アミロース・アミロペクチンは植物のデンプン、セルロースは植物の細胞壁。"},{"id":"pa5c3c037","q":"植物の細胞壁の主成分となる多糖はどれか。","a":"セルロース","w":["アミロース","アミロペクチン","グリコーゲン"],"e":"セルロースは植物の細胞壁の主成分。アミロース・アミロペクチンはデンプン、グリコーゲンは動物の多糖。"},{"id":"pcd2ac02f","q":"冷水にも溶ける多糖はどれか。","a":"グリコーゲン","w":["アミロース","アミロペクチン","セルロース"],"e":"グリコーゲンは冷水にも溶ける。アミロースは温水に溶ける、アミロペクチンは溶けにくい、セルロースは溶けない。"},{"id":"pf099b7ed","q":"水にも有機溶媒にも溶けにくい多糖はどれか。","a":"セルロース","w":["アミロース","アミロペクチン","グリコーゲン"],"e":"セルロースは分子間に水素結合を多くつくって結晶構造になるので、水にも有機溶媒にも溶けにくい。アミロース・グリコーゲンは水に溶ける。"},{"id":"p6f544035","q":"植物の光合成でつくられ、種子や根に蓄えられる多糖はどれか。","a":"デンプン","w":["グリコーゲン","セルロース","マルトース","スクロース"],"e":"デンプンは植物の光合成でつくられ、種子や根に蓄えられる。グリコーゲンは動物、セルロースは細胞壁の成分。マルトース・スクロースは二糖。"},{"id":"p17abc029","q":"必要に応じてグルコースに分解され、動物のエネルギー源となる多糖はどれか。","a":"グリコーゲン","w":["アミロース","アミロペクチン","セルロース"],"e":"グリコーゲンは動物の肝臓や筋肉に蓄えられ、必要に応じてグルコースに分解されエネルギーになる。"}]},{"name":"No.4 糖の反応(ヨウ素デンプン反応・還元性)","items":[{"id":"pd2aa2891","q":"アミロースにヨウ素溶液を加えたときの色はどれか。","a":"青紫色","w":["赤紫色","赤褐色","呈色しない"],"e":"アミロースは長いらせん構造なので青紫色。らせんが短い・枝分かれが多いほど赤っぽくなり、アミロペクチンは赤紫色、グリコーゲンは赤褐色。"},{"id":"pe41bb60e","q":"アミロペクチンにヨウ素溶液を加えたときの色はどれか。","a":"赤紫色","w":["青紫色","赤褐色","呈色しない"],"e":"アミロペクチンは枝分かれが多く、らせんが短いので赤紫色。アミロースは青紫色、グリコーゲンは赤褐色。"},{"id":"p13b7efb4","q":"グリコーゲンにヨウ素溶液を加えたときの色はどれか。","a":"赤褐色","w":["青紫色","赤紫色","呈色しない"],"e":"グリコーゲンは枝分かれがさらに多く、らせんがより短いので赤褐色。アミロースは青紫色、アミロペクチンは赤紫色。"},{"id":"p1bc47c28","q":"セルロースにヨウ素溶液を加えたときの色はどれか。","a":"呈色しない","w":["青紫色","赤紫色","赤褐色"],"e":"セルロースはらせん構造をとらないので、ヨウ素が入り込めず呈色しない。"},{"id":"p877cb6eb","q":"ヨウ素デンプン反応を示す物質をすべて選べ。","a":"アミロース・アミロペクチン・グリコーゲン","w":["セルロース","マルトース"],"e":"らせん構造をもつアミロース・アミロペクチン・グリコーゲンはヨウ素デンプン反応を示す。セルロースはらせんをつくらず、マルトースは二糖でらせんにならない。"},{"id":"p3ee30b55","q":"ヨウ素デンプン反応で、ヨウ素分子が入り込むのはデンプンのどの部分か。","a":"らせん構造の内側","w":["枝分かれ部分","ヒドロキシ基の間","グリコシド結合の位置"],"e":"ヨウ素分子はデンプンのらせん構造の内側に入り込んで呈色する。"},{"id":"p81bc67ab","q":"セルロースがヨウ素デンプン反応を示さない理由はどれか。","a":"らせん構造をとらないから","w":["枝分かれが多いから","水に溶けやすいから","還元性がないから"],"e":"セルロースはβ-グルコースからなる直鎖状で、らせん構造をとらないのでヨウ素が入り込めない。"},{"id":"p423b39e2","q":"ヨウ素デンプン反応で呈色した溶液を加熱するとどうなるか。","a":"色が消える（冷やすと再び呈色）","w":["色が濃くなる","赤褐色の沈殿が生じる","変化しない"],"e":"加熱するとらせん構造がゆるんでヨウ素が外れ、色が消える。冷やすと再びらせんにヨウ素が入り、呈色する。"},{"id":"pfc235b68","q":"還元性を示す糖をすべて選べ。","a":"グルコース・フルクトース・マルトース・ラクトース","w":["スクロース","デンプン"],"e":"単糖（グルコース・フルクトース）と、ヘミアセタール構造が残る二糖（マルトース・ラクトース）は還元性あり。スクロースは還元性を生む部分が結合に使われている、デンプンは多糖で還元性なし。"},{"id":"pb5e86a1d","q":"還元性を示さない糖をすべて選べ。","a":"スクロース・トレハロース・デンプン","w":["マルトース","フルクトース","セロビオース"],"e":"スクロース（1,2-結合）とトレハロース（1,1-結合）は還元性を生む部分が結合に使われている。デンプンは多糖で還元性なし。マルトース・セロビオース・フルクトースは還元性あり。"},{"id":"p10d0d094","q":"糖の還元性を調べる反応をすべて選べ。","a":"銀鏡反応・フェーリング反応","w":["ヨウ素デンプン反応","ビウレット反応","ニンヒドリン反応"],"e":"還元性は銀鏡反応（Agが析出）とフェーリング反応（Cu₂Oの赤色沈殿）で調べる。ヨウ素デンプン反応はデンプン、ビウレット・ニンヒドリン反応はタンパク質・アミノ酸の検出。"},{"id":"p608aca49","q":"還元性のある糖をフェーリング液と加熱すると生じる沈殿はどれか。","a":"Cu₂O の赤色沈殿","w":["Ag の銀色の沈殿","CuO の黒色沈殿","Cu(OH)₂ の青白色沈殿"],"e":"フェーリング液のCu²⁺が還元されて、酸化銅(Ⅰ)Cu₂Oの赤色沈殿ができる。Agが析出するのは銀鏡反応。CuOは黒色、Cu(OH)₂は青白色。"},{"id":"p69bcd795","q":"スクロースが還元性を示さない理由はどれか。","a":"還元性を生む部分どうしがグリコシド結合に使われているから","w":["ホルミル基を2つもつから","水に溶けにくいから","分子量が大きいから"],"e":"スクロースはグルコースの1位とフルクトースの2位（還元性を生む部分）どうしで結合しているので、どちらも開環できず還元性を示さない。"},{"id":"p86dc574b","q":"スクロースを加水分解して得られる単糖の混合物を何というか。","a":"転化糖","w":["麦芽糖","果糖","乳糖","水あめ"],"e":"スクロースを加水分解して得られるグルコースとフルクトースの等量混合物を転化糖という。麦芽糖はマルトース、果糖はフルクトース、乳糖はラクトース。"},{"id":"pe4f2d85c","q":"転化糖は還元性を示すか。","a":"示す","w":["示さない"],"e":"転化糖はグルコースとフルクトースの混合物で、どちらも単糖なので還元性を示す。"}]},{"name":"No.5 糖の分解酵素","items":[{"id":"p8d7f8477","q":"デンプンを加水分解する酵素はどれか。","a":"アミラーゼ","w":["マルターゼ","インベルターゼ","ラクターゼ","セルラーゼ"],"e":"デンプンはアミラーゼ（だ液・すい液）で加水分解される。マルターゼはマルトース、インベルターゼはスクロース、ラクターゼはラクトース、セルラーゼはセルロースを分解する。"},{"id":"pf365713b","q":"デンプンをアミラーゼで加水分解したときの生成物をすべて選べ。","a":"マルトース","w":["グルコース","フルクトース","ガラクトース","セロビオース"],"e":"アミラーゼはデンプンをマルトースまで分解する（グルコースまでは分解しない）。グルコースにするにはマルターゼか希酸が必要。"},{"id":"p5ca858e5","q":"マルトースを加水分解する酵素はどれか。","a":"マルターゼ","w":["アミラーゼ","インベルターゼ","ラクターゼ","セルラーゼ"],"e":"マルトースはマルターゼで加水分解される。アミラーゼはデンプン、インベルターゼはスクロース、ラクターゼはラクトースを分解する。"},{"id":"p8d307320","q":"マルトースをマルターゼで加水分解したときの生成物をすべて選べ。","a":"グルコース","w":["フルクトース","ガラクトース","マルトース","セロビオース"],"e":"マルトースはα-グルコース2分子からなるので、加水分解するとグルコースだけになる。"},{"id":"p3921e1be","q":"スクロースを加水分解する酵素はどれか。","a":"インベルターゼ","w":["アミラーゼ","マルターゼ","ラクターゼ","セルラーゼ"],"e":"スクロースはインベルターゼ（スクラーゼ）で加水分解される。アミラーゼはデンプン、マルターゼはマルトース、ラクターゼはラクトースを分解する。"},{"id":"p71185f50","q":"スクロースをインベルターゼで加水分解したときの生成物をすべて選べ。","a":"グルコース・フルクトース","w":["ガラクトース","マルトース","セロビオース"],"e":"スクロースはグルコースとフルクトースからなるので、加水分解すると両方が等量できる（転化糖）。"},{"id":"p95caaf00","q":"ラクトースを加水分解する酵素はどれか。","a":"ラクターゼ","w":["アミラーゼ","マルターゼ","インベルターゼ","セルラーゼ"],"e":"ラクトースはラクターゼで加水分解される。アミラーゼはデンプン、マルターゼはマルトース、インベルターゼはスクロースを分解する。"},{"id":"p5eeb2119","q":"ラクトースをラクターゼで加水分解したときの生成物をすべて選べ。","a":"グルコース・ガラクトース","w":["フルクトース","マルトース","セロビオース"],"e":"ラクトースはβ-ガラクトースとグルコースからなるので、加水分解するとグルコースとガラクトースができる。"},{"id":"pd5c796c7","q":"セルロースを加水分解する酵素はどれか。","a":"セルラーゼ","w":["アミラーゼ","マルターゼ","インベルターゼ","ラクターゼ"],"e":"セルロースはセルラーゼで加水分解される。アミラーゼはデンプン、マルターゼはマルトース、インベルターゼはスクロース、ラクターゼはラクトースを分解する。"},{"id":"p8a46b110","q":"セルロースをセルラーゼで加水分解したときの生成物をすべて選べ。","a":"セロビオース","w":["グルコース","フルクトース","ガラクトース","マルトース"],"e":"セルラーゼはセルロースを二糖のセロビオースまで分解する（アミラーゼがデンプンをマルトースまで分解するのと同じ）。"},{"id":"p4ffbdad1","q":"セロビオースを加水分解する酵素はどれか。","a":"セロビアーゼ","w":["アミラーゼ","マルターゼ","インベルターゼ","ラクターゼ"],"e":"セロビオースはセロビアーゼで加水分解される。マルターゼはマルトース、インベルターゼはスクロース、ラクターゼはラクトースを分解する。"},{"id":"p55ec988e","q":"セロビオースをセロビアーゼで加水分解したときの生成物をすべて選べ。","a":"グルコース","w":["フルクトース","ガラクトース","マルトース","セロビオース"],"e":"セロビオースはβ-グルコース2分子からなるので、加水分解するとグルコースだけになる。"},{"id":"pb23c65b5","q":"グルコースをエタノールと二酸化炭素に分解する酵素(群)はどれか。","a":"チマーゼ","w":["アミラーゼ","マルターゼ","インベルターゼ","ラクターゼ"],"e":"チマーゼ（酵母に含まれる酵素群）がグルコースをエタノールとCO₂に分解する（アルコール発酵）。アミラーゼ・マルターゼなどは加水分解酵素。"},{"id":"p280cc1bb","q":"アルコール発酵でグルコースから生じる物質をすべて選べ。","a":"エタノール・二酸化炭素","w":["メタノール","酢酸","水素"],"e":"アルコール発酵：C₆H₁₂O₆→2C₂H₅OH＋2CO₂。エタノールと二酸化炭素ができる。メタノール・酢酸・水素はできない。"},{"id":"p0af86c52","q":"デンプンを希塩酸で十分に加水分解したときの生成物をすべて選べ。","a":"グルコース","w":["マルトース","フルクトース","セロビオース"],"e":"希塩酸で十分に加水分解すると、デンプンはグルコースまで分解される。アミラーゼだとマルトースで止まる。"},{"id":"pc2e2f554","q":"セルロースを希硫酸で十分に加水分解したときの生成物をすべて選べ。","a":"グルコース","w":["セロビオース","マルトース","フルクトース"],"e":"希硫酸で十分に加水分解すると、セルロースはグルコースまで分解される。セルラーゼだとセロビオースで止まる。"},{"id":"p4e0fd14f","q":"酵素で加水分解したときと、希硫酸で十分に加水分解したときで、生成物が異なるものをすべて選べ。","a":"デンプン・セルロース","w":["スクロース","マルトース","ラクトース"],"e":"デンプンは酵素だとマルトース、酸だとグルコース。セルロースは酵素だとセロビオース、酸だとグルコース。二糖（スクロース・マルトース・ラクトース）はどちらでも単糖まで分解されるので同じ。"}]},{"name":"No.6 アミノ酸の構造式","items":[{"id":"p8232a3f0","q":"名称を答えよ。","a":"グリシン","w":["アラニン","セリン","バリン","リシン"],"e":"側鎖がHのグリシン（唯一不斉炭素なし）。アラニンは−CH₃、セリンは−CH₂OH、バリンは−CH(CH₃)₂、リシンは−(CH₂)₄NH₂。","img":"グリシン.png"},{"id":"p9e413f34","q":"名称を答えよ。","a":"アラニン","w":["グリシン","バリン","セリン","乳酸"],"e":"側鎖が−CH₃のアラニン。グリシンはH、バリンは−CH(CH₃)₂、セリンは−CH₂OH。乳酸は−NH₂の代わりに−OHでアミノ酸ではない。","img":"アラニン.png"},{"id":"p26b2ff52","q":"名称を答えよ。","a":"フェニルアラニン","w":["チロシン","アラニン","ロイシン","メチオニン"],"e":"側鎖が−CH₂−C₆H₅（アラニンのHがフェニル基）のフェニルアラニン。チロシンはベンゼン環にさらに−OH、ロイシンは−CH₂CH(CH₃)₂、メチオニンはSを含む。","img":"フェニルアラニン.png"},{"id":"p5e21272f","q":"名称を答えよ。","a":"チロシン","w":["フェニルアラニン","セリン","アラニン","グルタミン酸"],"e":"フェニルアラニンのベンゼン環のパラ位に−OHがついたチロシン。フェニルアラニンは−OHなし、セリンは−CH₂OH（ベンゼン環なし）、グルタミン酸は側鎖に−COOH。","img":"チロシン.png"},{"id":"pb5199104","q":"名称を答えよ。","a":"システイン","w":["メチオニン","セリン","アラニン","バリン"],"e":"側鎖が−CH₂SHのシステイン（−SHどうしでジスルフィド結合をつくる）。メチオニンは−(CH₂)₂−S−CH₃、セリンはSの代わりにO（−CH₂OH）。","img":"システイン.png"},{"id":"p263da42d","q":"名称を答えよ。","a":"メチオニン","w":["システイン","リシン","ロイシン","グルタミン酸"],"e":"側鎖が−(CH₂)₂−S−CH₃のメチオニン。システインは−CH₂SH、リシンは−(CH₂)₄NH₂、グルタミン酸は−(CH₂)₂COOH。","img":"メチオニン.png"},{"id":"p797fd072","q":"名称を答えよ。","a":"アスパラギン酸","w":["グルタミン酸","リシン","セリン","バリン"],"e":"側鎖が−CH₂COOHのアスパラギン酸（酸性アミノ酸）。グルタミン酸はCH₂が1つ多い−(CH₂)₂COOH、リシンは側鎖に−NH₂。","img":"アスパラギン酸.png"},{"id":"pdf2bab3a","q":"名称を答えよ。","a":"グルタミン酸","w":["アスパラギン酸","リシン","メチオニン","ロイシン"],"e":"側鎖が−(CH₂)₂COOHのグルタミン酸（酸性アミノ酸、うま味）。アスパラギン酸はCH₂が1つ少ない、リシンは側鎖に−NH₂、メチオニンはS。","img":"グルタミン酸.png"},{"id":"pa583af6d","q":"名称を答えよ。","a":"リシン","w":["グルタミン酸","アスパラギン酸","メチオニン","ロイシン"],"e":"側鎖が−(CH₂)₄NH₂のリシン（塩基性アミノ酸）。グルタミン酸・アスパラギン酸は側鎖に−COOH、メチオニンはS。","img":"リシン.png"}]},{"name":"No.7 アミノ酸の分類と等電点","items":[{"id":"p62f0b218","q":"グリシンは次のどれに分類されるか。","a":"中性アミノ酸","w":["酸性アミノ酸","塩基性アミノ酸"],"e":"側鎖に−COOHがあれば酸性、−NH₂があれば塩基性、どちらもなければ中性。グリシンは側鎖がHなので中性アミノ酸。"},{"id":"p34c6a702","q":"アラニンは次のどれに分類されるか。","a":"中性アミノ酸","w":["酸性アミノ酸","塩基性アミノ酸"],"e":"アラニンは側鎖が−CH₃で、−COOHも−NH₂もないので中性アミノ酸。"},{"id":"p8b6bdc52","q":"フェニルアラニンは次のどれに分類されるか。","a":"中性アミノ酸","w":["酸性アミノ酸","塩基性アミノ酸"],"e":"フェニルアラニンは側鎖がベンゼン環で、−COOHも−NH₂もないので中性アミノ酸。"},{"id":"pfbdb0437","q":"システインは次のどれに分類されるか。","a":"中性アミノ酸","w":["酸性アミノ酸","塩基性アミノ酸"],"e":"システインは側鎖が−CH₂SHで、−COOHも−NH₂もないので中性アミノ酸。"},{"id":"pff176bc8","q":"アスパラギン酸は次のどれに分類されるか。","a":"酸性アミノ酸","w":["中性アミノ酸","塩基性アミノ酸"],"e":"アスパラギン酸は側鎖に−COOHをもつので酸性アミノ酸。"},{"id":"p5db6a648","q":"グルタミン酸は次のどれに分類されるか。","a":"酸性アミノ酸","w":["中性アミノ酸","塩基性アミノ酸"],"e":"グルタミン酸は側鎖に−COOHをもつので酸性アミノ酸。"},{"id":"p1d85145b","q":"リシンは次のどれに分類されるか。","a":"塩基性アミノ酸","w":["中性アミノ酸","酸性アミノ酸"],"e":"リシンは側鎖に−NH₂をもつので塩基性アミノ酸。"},{"id":"p00754fa2","q":"不斉炭素原子をもたないα-アミノ酸をすべて選べ。","a":"グリシン","w":["アラニン","セリン","システイン","リシン"],"e":"グリシンは側鎖がHで、中心の炭素にHが2つつくので不斉炭素がない。他のα-アミノ酸はすべて不斉炭素をもつ。"},{"id":"pad5017bd","q":"側鎖にベンゼン環をもつα-アミノ酸をすべて選べ。","a":"フェニルアラニン・チロシン","w":["メチオニン","セリン","アラニン"],"e":"フェニルアラニンとチロシンは側鎖にベンゼン環をもつ（キサントプロテイン反応陽性）。メチオニンはS、セリンは−OH、アラニンは−CH₃。"},{"id":"pc75afb61","q":"側鎖に硫黄原子を含むα-アミノ酸をすべて選べ。","a":"システイン・メチオニン","w":["セリン","リシン","チロシン"],"e":"システイン（−CH₂SH）とメチオニン（−(CH₂)₂−S−CH₃）は側鎖にSを含む（硫黄の検出反応陽性）。セリンはSの代わりにO。"},{"id":"p29f4348e","q":"側鎖にカルボキシ基をもつα-アミノ酸をすべて選べ。","a":"アスパラギン酸・グルタミン酸","w":["リシン","セリン","アラニン"],"e":"アスパラギン酸とグルタミン酸は側鎖に−COOHをもつ酸性アミノ酸。リシンは側鎖に−NH₂。"},{"id":"p32420dee","q":"側鎖にアミノ基をもつα-アミノ酸をすべて選べ。","a":"リシン","w":["グルタミン酸","メチオニン","セリン","アラニン"],"e":"リシンは側鎖に−NH₂をもつ塩基性アミノ酸。グルタミン酸は側鎖に−COOH、メチオニン・セリン・アラニンは中性。"},{"id":"pcf494ac7","q":"アミノ酸の結晶中や水溶液中で、−COO⁻ と −NH₃⁺ を同時にもつイオンを何というか。","a":"双性イオン","w":["陽イオン","陰イオン","錯イオン"],"e":"−COOHのH⁺が−NH₂に移り、1つの分子に＋と−の両方をもつイオンを双性イオンという。錯イオンは金属イオンに配位子が結合したもの。"},{"id":"p611d6822","q":"アミノ酸の融点が高く、水に溶けやすい理由はどれか。","a":"双性イオンになっていて、イオン結晶に似た性質をもつから","w":["分子量が大きいから","水素結合をつくらないから","ペプチド結合をもつから"],"e":"アミノ酸は結晶中で双性イオンになり、イオン結晶に似たふるまいをするので、融点が高く水に溶けやすい。"},{"id":"p8a364921","q":"アミノ酸の平衡混合物の電荷が全体として0になるときのpHを何というか。","a":"等電点","w":["中和点","電離定数","最適pH"],"e":"アミノ酸の電荷が全体として0になるpHを等電点という。中和点は酸と塩基がちょうど反応する点、最適pHは酵素がよくはたらくpH。"},{"id":"pb90e8888","q":"等電点でアミノ酸は主にどのような状態で存在するか。","a":"双性イオン","w":["陽イオン","陰イオン","電離していない分子"],"e":"等電点では電荷が全体として0なので、大部分が双性イオンになっている。"},{"id":"p3f1321f1","q":"等電点より酸性の水溶液中では、アミノ酸は主にどのような状態で存在するか。","a":"陽イオン","w":["陰イオン","双性イオン","沈殿している"],"e":"等電点より酸性では、−COO⁻がH⁺を受け取って−COOHになり、分子全体は陽イオンになる。"},{"id":"p63ef35ce","q":"等電点より塩基性の水溶液中では、アミノ酸は主にどのような状態で存在するか。","a":"陰イオン","w":["陽イオン","双性イオン","沈殿している"],"e":"等電点より塩基性では、−NH₃⁺がH⁺を失って−NH₂になり、分子全体は陰イオンになる。"},{"id":"p0486ab89","q":"グルタミン酸の等電点はおよそいくつか。","a":"約3","w":["約6","約10"],"e":"グルタミン酸は酸性アミノ酸なので、等電点は酸性側（約3）。中性アミノ酸は約6、塩基性アミノ酸は約10。"},{"id":"p205d695d","q":"アラニンの等電点はおよそいくつか。","a":"約6","w":["約3","約10"],"e":"アラニンは中性アミノ酸なので、等電点は中性付近（約6）。酸性アミノ酸は約3、塩基性アミノ酸は約10。"},{"id":"p07113c50","q":"リシンの等電点はおよそいくつか。","a":"約10","w":["約3","約6"],"e":"リシンは塩基性アミノ酸なので、等電点は塩基性側（約10）。"},{"id":"p5a7914f7","q":"pH=1 の水溶液中で、グリシンは主にどのような状態で存在するか。","a":"陽イオン（H₃N⁺−CH₂−COOH）","w":["双性イオン（H₃N⁺−CH₂−COO⁻）","陰イオン（H₂N−CH₂−COO⁻）"],"e":"pH=1は等電点（約6）よりずっと酸性なので、−COO⁻もH⁺を受け取り、陽イオン（H₃N⁺−CH₂−COOH）になる。"},{"id":"p31da51c2","q":"pH6.0 の緩衝液中で電気泳動を行うと、アラニン(等電点6.0)はどうなるか。","a":"移動しない","w":["陽極側へ移動する","陰極側へ移動する"],"e":"pHが等電点と同じなので、アラニンは双性イオン（電荷0）で、どちらの極にも移動しない。"},{"id":"p6b10198a","q":"pH6.0 の緩衝液中で電気泳動を行うと、グルタミン酸(等電点3.2)はどうなるか。","a":"陽極側へ移動する","w":["移動しない","陰極側へ移動する"],"e":"pH6.0は等電点3.2より塩基性なので、グルタミン酸は陰イオンになり陽極側へ移動する。"},{"id":"p13230142","q":"pH6.0 の緩衝液中で電気泳動を行うと、リシン(等電点9.7)はどうなるか。","a":"陰極側へ移動する","w":["移動しない","陽極側へ移動する"],"e":"pH6.0は等電点9.7より酸性なので、リシンは陽イオンになり陰極側へ移動する。"}]},{"name":"No.8 アミノ酸・タンパク質の検出反応(基礎)","items":[{"id":"pb9d0af74","q":"アミノ基をもつ物質(アミノ酸など)を検出する反応はどれか。","a":"ニンヒドリン反応","w":["ビウレット反応","キサントプロテイン反応","硫黄の検出反応","銀鏡反応"],"e":"アミノ基をもつ物質はニンヒドリン反応で赤紫〜青紫色になる。ビウレットはペプチド結合2つ以上、キサントプロテインはベンゼン環、硫黄の検出はS、銀鏡反応は還元性の検出。"},{"id":"p9f92f644","q":"ペプチド結合を2つ以上もつ物質(トリペプチド以上)を検出する反応はどれか。","a":"ビウレット反応","w":["ニンヒドリン反応","キサントプロテイン反応","硫黄の検出反応","銀鏡反応"],"e":"ペプチド結合を2つ以上もつもの（トリペプチド以上）はビウレット反応で赤紫色になる。ニンヒドリンはアミノ基、キサントプロテインはベンゼン環、硫黄の検出はSの検出。"},{"id":"p2341b3f7","q":"ベンゼン環などの芳香環をもつアミノ酸やタンパク質を検出する反応はどれか。","a":"キサントプロテイン反応","w":["ニンヒドリン反応","ビウレット反応","硫黄の検出反応","銀鏡反応"],"e":"ベンゼン環をもつアミノ酸はキサントプロテイン反応で黄色になる（ベンゼン環がニトロ化される）。"},{"id":"p4c50e560","q":"硫黄原子を含むアミノ酸やタンパク質を検出する反応はどれか。","a":"硫黄の検出反応","w":["ニンヒドリン反応","ビウレット反応","キサントプロテイン反応","銀鏡反応"],"e":"Sを含むアミノ酸は、NaOHで加熱後に酢酸鉛(Ⅱ)を加えるとPbSの黒色沈殿ができる（硫黄の検出反応）。"},{"id":"peef9ea0d","q":"ニンヒドリン反応で見られる色はどれか。","a":"赤紫〜青紫色","w":["黄色→(アンモニア水で)橙黄色","黒色沈殿","緑色","白色沈殿"],"e":"ニンヒドリン反応は赤紫〜青紫色。黄色→橙黄色はキサントプロテイン反応、黒色沈殿は硫黄の検出反応。"},{"id":"p160fd26c","q":"ビウレット反応で見られる色はどれか。","a":"赤紫色","w":["黄色→(アンモニア水で)橙黄色","黒色沈殿","青色","緑色"],"e":"ビウレット反応は、Cu²⁺がペプチド結合の部分と錯イオンをつくって赤紫色になる。黄色→橙黄色はキサントプロテイン反応、黒色沈殿は硫黄の検出反応。"},{"id":"p82e241a3","q":"キサントプロテイン反応で見られる色の変化はどれか。","a":"黄色→(アンモニア水で)橙黄色","w":["赤紫色","黒色沈殿","青色","白色沈殿"],"e":"キサントプロテイン反応は、濃硝酸で黄色になり、アンモニア水を加えると橙黄色になる。赤紫色はビウレット反応、黒色沈殿は硫黄の検出反応。"},{"id":"pcdf09bc2","q":"硫黄の検出反応で見られる変化はどれか。","a":"黒色沈殿","w":["赤紫色","黄色→(アンモニア水で)橙黄色","白色沈殿","青色"],"e":"硫黄の検出反応ではPbSの黒色沈殿ができる。赤紫色はビウレット反応、黄色→橙黄色はキサントプロテイン反応。"},{"id":"pb288521b","q":"ニンヒドリン反応の操作として正しいものはどれか。","a":"ニンヒドリン溶液を加えて温める","w":["NaOH水溶液を加え、少量のCuSO₄水溶液を加える","濃硝酸を加えて加熱する","NaOH水溶液を加えて加熱後、酢酸鉛(Ⅱ)水溶液を加える"],"e":"ニンヒドリン反応はニンヒドリン溶液を加えて温める。NaOH＋CuSO₄はビウレット反応、濃硝酸はキサントプロテイン反応、NaOH加熱＋酢酸鉛(Ⅱ)は硫黄の検出反応。"},{"id":"paf44ce9d","q":"ビウレット反応の操作として正しいものはどれか。","a":"NaOH水溶液を加え、少量のCuSO₄水溶液を加える","w":["ニンヒドリン溶液を加えて温める","濃硝酸を加えて加熱する","NaOH水溶液を加えて加熱後、酢酸鉛(Ⅱ)水溶液を加える"],"e":"ビウレット反応はNaOH水溶液を加え、少量のCuSO₄水溶液を加える。濃硝酸はキサントプロテイン反応、酢酸鉛(Ⅱ)は硫黄の検出反応。"},{"id":"p7a29ff8b","q":"キサントプロテイン反応の操作として正しいものはどれか。","a":"濃硝酸を加えて加熱する","w":["ニンヒドリン溶液を加えて温める","NaOH水溶液を加え、少量のCuSO₄水溶液を加える","NaOH水溶液を加えて加熱後、酢酸鉛(Ⅱ)水溶液を加える"],"e":"キサントプロテイン反応は濃硝酸を加えて加熱する。NaOH＋CuSO₄はビウレット反応、酢酸鉛(Ⅱ)は硫黄の検出反応。"},{"id":"p0a99e667","q":"硫黄の検出反応の操作として正しいものはどれか。","a":"NaOH水溶液を加えて加熱後、酢酸鉛(Ⅱ)水溶液を加える","w":["ニンヒドリン溶液を加えて温める","NaOH水溶液を加え、少量のCuSO₄水溶液を加える","濃硝酸を加えて加熱する"],"e":"硫黄の検出反応はNaOHで加熱してS²⁻にし、酢酸鉛(Ⅱ)を加えてPbSを沈殿させる。NaOH＋CuSO₄はビウレット反応、濃硝酸はキサントプロテイン反応。"},{"id":"pf890a03e","q":"タンパク質に固体のNaOHを加えて加熱すると発生し、窒素の検出に使われる気体はどれか。","a":"アンモニア","w":["二酸化炭素","硫化水素","窒素","一酸化窒素"],"e":"タンパク質中のNは、NaOHと加熱するとNH₃になる（濃塩酸を近づけると白煙）。CO₂はCの検出、H₂SはSを含むときの気体。"},{"id":"p04c018b7","q":"硫黄の検出反応で生じる黒色沈殿の化学式はどれか。","a":"PbS","w":["CuS","Ag₂S","PbSO₄","Cu₂O"],"e":"S²⁻とPb²⁺から黒色のPbS（硫化鉛(Ⅱ)）ができる。CuS・Ag₂Sも黒いが、使う試薬が酢酸鉛(Ⅱ)なのでPbS。PbSO₄は白色、Cu₂Oは赤色。"},{"id":"p22ace2aa","q":"アミノ酸どうしが脱水縮合してできる −CO−NH− の結合を何というか。","a":"ペプチド結合","w":["エステル結合","グリコシド結合","ジスルフィド結合","水素結合"],"e":"アミノ酸の−COOHと−NH₂が脱水縮合してできる−CO−NH−をペプチド結合という（構造はアミド結合と同じ）。エステル結合は−COO−、グリコシド結合は糖どうし。"},{"id":"p151cbb26","q":"トリペプチド1分子に含まれるペプチド結合の数はいくつか。","a":"2","w":["1","3","4"],"e":"アミノ酸3つをつなぐので、ペプチド結合は2つ（アミノ酸n個ならn−1個）。"}]},{"name":"No.9 アミノ酸・タンパク質の検出反応(応用)","items":[{"id":"p4d95f986","q":"キサントプロテイン反応を示すアミノ酸をすべて選べ。","a":"フェニルアラニン・チロシン","w":["アラニン","グリシン","システイン"],"e":"キサントプロテイン反応はベンゼン環をもつフェニルアラニン・チロシンで陽性。アラニン・グリシン・システインはベンゼン環がない。"},{"id":"p242511f7","q":"硫黄の検出反応を示すアミノ酸をすべて選べ。","a":"システイン・メチオニン","w":["セリン","グリシン","チロシン"],"e":"硫黄の検出反応はSを含むシステイン・メチオニンで陽性。セリン・グリシン・チロシンはSを含まない。"},{"id":"pa6ce5dc8","q":"ニンヒドリン反応を示すものをすべて選べ。","a":"グリシン・アラニン・グリシン2分子からなるジペプチド","w":["グルコース","デンプン"],"e":"ニンヒドリン反応はアミノ基があれば陽性なので、アミノ酸もペプチドも示す。グルコース・デンプンはアミノ基をもたない。"},{"id":"p6e28a3f0","q":"グリシン2分子からなるジペプチドはビウレット反応を示すか。","a":"示さない","w":["示す"],"e":"ジペプチドはペプチド結合が1つなので、ビウレット反応を示さない。トリペプチド以上（ペプチド結合2つ以上）で陽性。"},{"id":"p74c2b13c","q":"ビウレット反応とキサントプロテイン反応の両方を示すペプチドはどれか。","a":"グリシン−フェニルアラニン−メチオニン","w":["グリシン−フェニルアラニン","グリシン−システイン−メチオニン","グリシン−システイン"],"e":"ビウレット反応にはトリペプチド以上、キサントプロテイン反応にはベンゼン環（フェニルアラニン）が必要。グリシン−フェニルアラニンはジペプチド、システインやメチオニンだけではベンゼン環がない。"},{"id":"p70723808","q":"フェニルアラニンが示す反応をすべて選べ。","a":"ニンヒドリン反応・キサントプロテイン反応","w":["ビウレット反応","硫黄の検出反応","銀鏡反応"],"e":"フェニルアラニンはアミノ基をもつのでニンヒドリン、ベンゼン環をもつのでキサントプロテイン反応を示す。アミノ酸1分子なのでビウレット反応は示さない。Sは含まない。"},{"id":"p981f8832","q":"メチオニンが示す反応をすべて選べ。","a":"ニンヒドリン反応・硫黄の検出反応","w":["ビウレット反応","キサントプロテイン反応","銀鏡反応"],"e":"メチオニンはアミノ基をもつのでニンヒドリン、Sを含むので硫黄の検出反応を示す。アミノ酸1分子なのでビウレットは示さず、ベンゼン環もない。"},{"id":"p6f47f5e4","q":"グリシン−アラニン(ジペプチド)が示す反応をすべて選べ。","a":"ニンヒドリン反応","w":["ビウレット反応","キサントプロテイン反応","硫黄の検出反応","銀鏡反応"],"e":"ジペプチドはアミノ基をもつのでニンヒドリン反応を示す。ペプチド結合が1つなのでビウレットは示さず、ベンゼン環もSもない。"},{"id":"p309ed141","q":"グリシン−チロシン−システイン(トリペプチド)が示す反応をすべて選べ。","a":"ニンヒドリン反応・ビウレット反応・キサントプロテイン反応・硫黄の検出反応","w":["銀鏡反応"],"e":"トリペプチドなのでニンヒドリン・ビウレット、チロシンのベンゼン環でキサントプロテイン、システインのSで硫黄の検出反応を示す。銀鏡反応は還元性の糖などの検出。"},{"id":"p014958b8","q":"アラニン−グリシン−セリン(トリペプチド)が示す反応をすべて選べ。","a":"ニンヒドリン反応・ビウレット反応","w":["キサントプロテイン反応","硫黄の検出反応","銀鏡反応"],"e":"トリペプチドなのでニンヒドリン・ビウレット反応を示す。アラニン・グリシン・セリンはベンゼン環もSもないので、キサントプロテイン・硫黄の検出反応は示さない。"}]},{"name":"No.10 タンパク質の構造と変性","items":[{"id":"p7141a3d5","q":"「ペプチド鎖のアミノ酸の配列順序」はタンパク質の何構造か。","a":"一次構造","w":["二次構造","三次構造","四次構造"],"e":"アミノ酸の配列順序が一次構造。二次構造はα-ヘリックスなど、三次構造は折りたたまれた立体構造、四次構造は複数の鎖の集まり。"},{"id":"p5f777325","q":"「α-ヘリックスやβ-シートなどの部分的な立体構造」はタンパク質の何構造か。","a":"二次構造","w":["一次構造","三次構造","四次構造"],"e":"α-ヘリックスやβ-シートは二次構造（ペプチド結合どうしの水素結合でできる）。"},{"id":"p16406e76","q":"「側鎖どうしの相互作用で折りたたまれた立体構造」はタンパク質の何構造か。","a":"三次構造","w":["一次構造","二次構造","四次構造"],"e":"側鎖どうしの相互作用で複雑に折りたたまれた立体構造が三次構造。"},{"id":"p43204344","q":"「複数のポリペプチド鎖(サブユニット)が集まった構造」はタンパク質の何構造か。","a":"四次構造","w":["一次構造","二次構造","三次構造"],"e":"三次構造をとったポリペプチド鎖（サブユニット）がいくつか集まったものが四次構造。"},{"id":"p76a71753","q":"タンパク質の二次構造をすべて選べ。","a":"α-ヘリックス・β-シート","w":["ジスルフィド結合","二重らせん","サブユニット"],"e":"二次構造はα-ヘリックス（らせん）とβ-シート（ひだ状の平面）。ジスルフィド結合は三次構造を保つ結合、二重らせんはDNA、サブユニットは四次構造の単位。"},{"id":"p9ea64707","q":"α-ヘリックスはどのような構造か。","a":"らせん構造","w":["ひだ状の平面構造","枝分かれ構造","環状構造"],"e":"α-ヘリックスはらせん構造（アミノ酸約3.6個で1回転）。ひだ状の平面構造はβ-シート。"},{"id":"pbe8955d4","q":"β-シートはどのような構造か。","a":"ひだ状の平面構造","w":["らせん構造","枝分かれ構造","環状構造"],"e":"β-シートはひだ状（ジグザグ）の平面構造。らせん構造はα-ヘリックス。"},{"id":"pbfd8b606","q":"二次構造をつくる主な結合(力)はどれか。","a":"水素結合","w":["ジスルフィド結合","イオン結合","ペプチド結合"],"e":"二次構造は、ペプチド結合のC=OとN−Hの間の水素結合でできる。ジスルフィド結合・イオン結合は三次構造、ペプチド結合は一次構造。"},{"id":"pdf9bdd8c","q":"システインの −SH どうしがつくる結合はどれか。","a":"ジスルフィド結合","w":["ペプチド結合","水素結合","エステル結合"],"e":"システインの−SHどうしが酸化されて−S−S−（ジスルフィド結合）をつくり、三次構造を保つ。"},{"id":"pb2b40fac","q":"タンパク質を変性させるものをすべて選べ。","a":"加熱・強い酸・アルコール・重金属イオン","w":["純水で薄める"],"e":"熱・酸・塩基・アルコール・重金属イオンで、水素結合などが壊れて変性する。純水で薄めるだけでは変性しない。"},{"id":"pf5959da2","q":"タンパク質が変性したとき、壊れないのはどの構造か。","a":"一次構造","w":["二次構造","三次構造","四次構造"],"e":"変性で壊れるのは水素結合などでできた二次構造以上。ペプチド結合は切れないので一次構造は残る。"}]},{"name":"No.11 合成高分子のモノマー①(構造式→名称)","items":[{"id":"p63526ca0","q":"名称を答えよ。","a":"プロピレン","w":["エチレン","塩化ビニル","アクリロニトリル","酢酸ビニル"],"e":"CH₂=CH−CH₃でプロピレン（→ポリプロピレン）。エチレンは−CH₃がなくH、塩化ビニルは−Cl、アクリロニトリルは−CN、酢酸ビニルは−OCOCH₃。","img":"プロピレン.jpg"},{"id":"pba5d8959","q":"名称を答えよ。","a":"塩化ビニル","w":["塩化ビニリデン","クロロプレン","エチレン","アクリロニトリル"],"e":"CH₂=CHClで塩化ビニル（→ポリ塩化ビニル）。塩化ビニリデンはClが同じCに2つ、クロロプレンはブタジエンにCl、アクリロニトリルは−CN。","img":"塩化ビニル.jpg"},{"id":"p77caff91","q":"名称を答えよ。","a":"酢酸ビニル","w":["メタクリル酸メチル","ビニルアルコール","アクリル酸ナトリウム","酢酸エチル"],"e":"CH₂=CH−OCOCH₃で酢酸ビニル（→ポリ酢酸ビニル→ビニロン）。メタクリル酸メチルは−CH₃と−COOCH₃、ビニルアルコールは−OH、酢酸エチルはC=Cがない。","img":"酢酸ビニル.png"},{"id":"pc147b9ec","q":"名称を答えよ。","a":"テレフタル酸","w":["テレフタル酸ジクロリド","フタル酸","𝑝-フェニレンジアミン","アジピン酸"],"e":"ベンゼン環のパラ位に−COOHが2つでテレフタル酸（PETの原料）。テレフタル酸ジクロリドは−COCl、フタル酸はオルト位、アジピン酸はベンゼン環なし。","img":"テレフタル酸.jpg"},{"id":"p81e0b041","q":"名称を答えよ。","a":"スチレン","w":["𝑝-ジビニルベンゼン","アクリロニトリル","塩化ビニル","1,3-ブタジエン"],"e":"CH₂=CH−C₆H₅でスチレン（→ポリスチレン、SBRの原料）。p-ジビニルベンゼンはビニル基が2つ、1,3-ブタジエンはベンゼン環なし。","img":"スチレン.png"},{"id":"pdcd2829e","q":"名称を答えよ。","a":"𝑝-ジビニルベンゼン","w":["スチレン","テレフタル酸","𝑝-フェニレンジアミン","1,3-ブタジエン"],"e":"ベンゼン環のパラ位にビニル基が2つでp-ジビニルベンゼン。スチレンと共重合して架橋をつくる（イオン交換樹脂の骨格）。スチレンはビニル基が1つ。","img":"p-ジビニルベンゼン.png"},{"id":"p9ed7b769","q":"名称を答えよ。","a":"塩化ビニリデン","w":["塩化ビニル","クロロプレン","テトラフルオロエチレン","エチレン"],"e":"CH₂=CCl₂で塩化ビニリデン（Clが同じCに2つ）。塩化ビニルはClが1つ、テトラフルオロエチレンはF₄。","img":"塩化ビニリデン.png"},{"id":"p3077228f","q":"名称を答えよ。","a":"アクリロニトリル","w":["塩化ビニル","アクリル酸ナトリウム","酢酸ビニル","プロピレン"],"e":"CH₂=CH−CNでアクリロニトリル（→アクリル繊維、NBRの原料）。アクリル酸ナトリウムは−COONa、塩化ビニルは−Cl、プロピレンは−CH₃。","img":"アクリロニトリル.png"},{"id":"p96b083c7","q":"名称を答えよ。","a":"メタクリル酸メチル","w":["酢酸ビニル","アクリル酸ナトリウム","アクリロニトリル","イソプレン"],"e":"CH₂=C(CH₃)−COOCH₃でメタクリル酸メチル（→アクリル樹脂）。酢酸ビニルは−OCOCH₃、アクリル酸ナトリウムは−COONa、イソプレンは二重結合が2つ。","img":"メタクリル酸メチル.png"},{"id":"p1ef8bf1f","q":"名称を答えよ。","a":"アクリル酸ナトリウム","w":["アクリロニトリル","メタクリル酸メチル","酢酸ビニル","塩化ビニル"],"e":"CH₂=CH−COONaでアクリル酸ナトリウム（→高吸水性樹脂）。アクリロニトリルは−CN、メタクリル酸メチルは−CH₃と−COOCH₃。","img":"アクリル酸ナトリウム.png"},{"id":"p9a134132","q":"名称を答えよ。","a":"ヘキサメチレンジアミン","w":["アジピン酸","𝑝-フェニレンジアミン","エチレングリコール","ε-カプロラクタム"],"e":"H₂N−(CH₂)₆−NH₂でヘキサメチレンジアミン（ナイロン66の原料）。アジピン酸は−COOHが2つ、p-フェニレンジアミンはベンゼン環に−NH₂が2つ。","img":"ヘキサメチレンジアミン.png"},{"id":"pf7eea66c","q":"名称を答えよ。","a":"アジピン酸","w":["ヘキサメチレンジアミン","アジピン酸ジクロリド","テレフタル酸","乳酸"],"e":"HOOC−(CH₂)₄−COOHでアジピン酸（ナイロン66の原料）。アジピン酸ジクロリドは−COCl、テレフタル酸はベンゼン環、乳酸は−OHと−COOH。","img":"アジピン酸.png"},{"id":"p77da31ba","q":"名称を答えよ。","a":"アジピン酸ジクロリド","w":["アジピン酸","テレフタル酸ジクロリド","ヘキサメチレンジアミン","テレフタル酸"],"e":"ClOC−(CH₂)₄−COClでアジピン酸ジクロリド（アジピン酸の−OHを−Clにしたもの）。実験室でナイロン66をつくるのに使う。テレフタル酸ジクロリドはベンゼン環。","img":"アジピン酸ジクロリド.png"},{"id":"p20527fc4","q":"名称を答えよ。","a":"ε-カプロラクタム","w":["ヘキサメチレンジアミン","アジピン酸","乳酸","メラミン"],"e":"7員環のアミドでε-カプロラクタム（開環重合→ナイロン6）。ヘキサメチレンジアミン・アジピン酸は鎖状、メラミンは窒素を含む6員環。","img":"ε-カプロラクタム.png"},{"id":"pe9cc82df","q":"名称を答えよ。","a":"テレフタル酸ジクロリド","w":["テレフタル酸","アジピン酸ジクロリド","𝑝-フェニレンジアミン","フタル酸"],"e":"ベンゼン環のパラ位に−COClが2つでテレフタル酸ジクロリド（アラミド繊維の原料）。テレフタル酸は−COOH、アジピン酸ジクロリドはベンゼン環なし、フタル酸はオルト位。","img":"テレフタル酸ジクロリド.png"},{"id":"p52d39cf0","q":"名称を答えよ。","a":"𝑝-フェニレンジアミン","w":["ヘキサメチレンジアミン","テレフタル酸","アニリン","𝑝-ジビニルベンゼン"],"e":"ベンゼン環のパラ位に−NH₂が2つでp-フェニレンジアミン（アラミド繊維の原料）。ヘキサメチレンジアミンはベンゼン環なし、アニリンは−NH₂が1つ。","img":"p-フェニレンジアミン.png"},{"id":"pf708cfd4","q":"名称を答えよ。","a":"エチレングリコール","w":["ヘキサメチレンジアミン","グリコール酸","エタノール","乳酸"],"e":"HO−CH₂−CH₂−OHでエチレングリコール（PETの原料）。グリコール酸は−CH₂OHと−COOH、エタノールは−OHが1つ、乳酸は−CH₃もある。","img":"エチレングリコール.png"},{"id":"pbe18de9e","q":"名称を答えよ。","a":"乳酸","w":["グリコール酸","アジピン酸","酢酸","エチレングリコール"],"e":"CH₃−CH(OH)−COOHで乳酸（→ポリ乳酸、生分解性）。グリコール酸は−CH₃がない、アジピン酸は−COOHが2つ、酢酸は−OHがない。","img":"乳酸.png"},{"id":"p5cf8ee8e","q":"名称を答えよ。","a":"尿素","w":["メラミン","ホルムアルデヒド","ε-カプロラクタム","ヘキサメチレンジアミン"],"e":"H₂N−CO−NH₂で尿素（＋ホルムアルデヒド→尿素樹脂）。メラミンは窒素を含む6員環、ホルムアルデヒドはHCHO。","img":"尿素.png"},{"id":"p39311b85","q":"名称を答えよ。","a":"メラミン","w":["尿素","フェノール","ε-カプロラクタム","𝑝-フェニレンジアミン"],"e":"窒素を含む6員環に−NH₂が3つでメラミン（＋ホルムアルデヒド→メラミン樹脂）。尿素は鎖状、フェノールはベンゼン環に−OH。","img":"メラミン.png"}]},{"name":"No.13 合成高分子のモノマー③(ポリマー→モノマーの名称)","items":[{"id":"pe0787b6e","q":"ナイロン66の単量体(モノマー)をすべて選べ。","a":"ヘキサメチレンジアミン・アジピン酸","w":["ε-カプロラクタム","テレフタル酸","エチレングリコール"],"e":"ナイロン66はヘキサメチレンジアミンとアジピン酸の縮合重合。ε-カプロラクタムはナイロン6、テレフタル酸・エチレングリコールはPETの原料。"},{"id":"pc3b70924","q":"ナイロン6の単量体(モノマー)をすべて選べ。","a":"ε-カプロラクタム","w":["ヘキサメチレンジアミン","アジピン酸","乳酸","アクリロニトリル"],"e":"ナイロン6はε-カプロラクタムの開環重合。ヘキサメチレンジアミン・アジピン酸はナイロン66、アクリロニトリルはアクリル繊維の原料。"},{"id":"p39c7a776","q":"アラミド繊維の単量体(モノマー)をすべて選べ。","a":"𝑝-フェニレンジアミン・テレフタル酸ジクロリド","w":["ヘキサメチレンジアミン","アジピン酸","ε-カプロラクタム"],"e":"アラミド繊維はp-フェニレンジアミンとテレフタル酸ジクロリドの縮合重合。ヘキサメチレンジアミン・アジピン酸はナイロン66、ε-カプロラクタムはナイロン6の原料。"},{"id":"pae17b5a6","q":"ポリエチレンテレフタラート(PET)の単量体(モノマー)をすべて選べ。","a":"テレフタル酸・エチレングリコール","w":["エチレン","アジピン酸","フタル酸"],"e":"PETはテレフタル酸とエチレングリコールの縮合重合。エチレンはポリエチレン、アジピン酸はナイロン66、フタル酸はオルト位でPETには使わない。"},{"id":"pfd8766be","q":"アクリル繊維の単量体(モノマー)をすべて選べ。","a":"アクリロニトリル","w":["アクリル酸ナトリウム","酢酸ビニル","メタクリル酸メチル","塩化ビニル"],"e":"アクリル繊維はアクリロニトリルの付加重合。アクリル酸ナトリウムは高吸水性樹脂、メタクリル酸メチルはアクリル樹脂の原料。"},{"id":"p0530b3f2","q":"ポリビニルアルコール(ビニロンの原料)の単量体(モノマー)をすべて選べ。","a":"酢酸ビニル","w":["ビニルアルコール","エチレン","アセトアルデヒド","酢酸"],"e":"ビニルアルコールは不安定ですぐアセトアルデヒドになるので単量体に使えない。酢酸ビニルを付加重合し、けん化してポリビニルアルコールにする。"},{"id":"p6538f45b","q":"高吸水性樹脂の単量体(モノマー)をすべて選べ。","a":"アクリル酸ナトリウム","w":["アクリロニトリル","酢酸ビニル","メタクリル酸メチル","乳酸"],"e":"高吸水性樹脂（ポリアクリル酸ナトリウム）はアクリル酸ナトリウムの付加重合。アクリロニトリルはアクリル繊維、乳酸はポリ乳酸の原料。"},{"id":"p91eddefb","q":"フェノール樹脂の単量体(モノマー)をすべて選べ。","a":"フェノール・ホルムアルデヒド","w":["尿素","メラミン","アセトアルデヒド"],"e":"フェノール樹脂はフェノールとホルムアルデヒドの付加縮合。尿素・メラミンは別の樹脂、アセトアルデヒドは使わない。"},{"id":"pf564e064","q":"尿素樹脂の単量体(モノマー)をすべて選べ。","a":"尿素・ホルムアルデヒド","w":["メラミン","フェノール","アセトアルデヒド"],"e":"尿素樹脂は尿素とホルムアルデヒドの付加縮合。メラミン・フェノールは別の樹脂、アセトアルデヒドは使わない。"},{"id":"p0c9adb1f","q":"メラミン樹脂の単量体(モノマー)をすべて選べ。","a":"メラミン・ホルムアルデヒド","w":["尿素","フェノール","アセトアルデヒド"],"e":"メラミン樹脂はメラミンとホルムアルデヒドの付加縮合。尿素・フェノールは別の樹脂、アセトアルデヒドは使わない。"},{"id":"pae73ef2d","q":"イオン交換樹脂の骨格の単量体(モノマー)をすべて選べ。","a":"スチレン・𝑝-ジビニルベンゼン","w":["1,3-ブタジエン","アクリロニトリル","エチレン"],"e":"イオン交換樹脂の骨格はスチレンとp-ジビニルベンゼンの共重合。1,3-ブタジエン・アクリロニトリルは合成ゴム、エチレンはポリエチレンの原料。"},{"id":"pf3ea8b95","q":"ヘキサメチレンジアミンとアジピン酸を原料として得られる高分子は何か。","a":"ナイロン66","w":["ナイロン6","アラミド繊維","ポリエチレンテレフタラート","ビニロン"],"e":"ヘキサメチレンジアミンとアジピン酸の縮合重合でナイロン66。ナイロン6はε-カプロラクタム、アラミド繊維はp-フェニレンジアミンとテレフタル酸ジクロリド、PETはテレフタル酸とエチレングリコール。"},{"id":"p429f97b2","q":"ε-カプロラクタムを重合して得られる高分子は何か。","a":"ナイロン6","w":["ナイロン66","アラミド繊維","ポリエチレンテレフタラート","アクリル繊維"],"e":"ε-カプロラクタムの開環重合でナイロン6。ナイロン66はヘキサメチレンジアミンとアジピン酸、アクリル繊維はアクリロニトリル。"},{"id":"p3c05409b","q":"テレフタル酸とエチレングリコールを原料として得られる高分子は何か。","a":"ポリエチレンテレフタラート","w":["ナイロン66","ナイロン6","アラミド繊維","ポリエチレン"],"e":"テレフタル酸とエチレングリコールの縮合重合でPET。ナイロン66はヘキサメチレンジアミンとアジピン酸、ポリエチレンはエチレン。"},{"id":"p3d104db3","q":"酢酸ビニルを原料として、いくつかの反応を経て得られる合成繊維は何か。","a":"ビニロン","w":["アクリル繊維","ナイロン6","ポリエチレンテレフタラート","アラミド繊維"],"e":"酢酸ビニル→（付加重合）→（けん化）→（アセタール化）→ビニロン。アクリル繊維はアクリロニトリル、ナイロン6はε-カプロラクタムからつくる。"},{"id":"pb93b679b","q":"酢酸ビニルからビニロンをつくる手順として正しいものはどれか。","a":"付加重合→けん化→アセタール化","w":["けん化→付加重合→アセタール化","付加重合→アセタール化→けん化","縮合重合→けん化→アセタール化"],"e":"酢酸ビニルを付加重合してポリ酢酸ビニル、けん化してポリビニルアルコール、ホルムアルデヒドでアセタール化してビニロン。重合が先で、縮合重合ではない。"}]},{"name":"No.14 合成繊維と重合の種類","items":[{"id":"pefabbbb8","q":"カロザースが合成した世界初の合成繊維はどれか。","a":"ナイロン66","w":["アラミド繊維","ポリエチレンテレフタラート","ビニロン","アクリル繊維"],"e":"カロザースが絹に似せてつくった世界初の合成繊維はナイロン66。ビニロンは日本初の国産合成繊維。"},{"id":"pbee7c987","q":"強度と耐熱性に優れ、消防服や防弾チョッキに使われる合成繊維はどれか。","a":"アラミド繊維","w":["ナイロン66","ポリエチレンテレフタラート","ビニロン","アクリル繊維"],"e":"アラミド繊維は強さと耐熱性に優れ、消防服や防弾チョッキに使われる。ナイロン66は熱に弱い。"},{"id":"p60eb2a2c","q":"丈夫で乾きやすくしわになりにくく、衣料やペットボトルに使われるものはどれか。","a":"ポリエチレンテレフタラート","w":["ナイロン66","アラミド繊維","ビニロン","アクリル繊維"],"e":"PETは丈夫で乾きやすくしわになりにくいので衣料品に使われ、樹脂としてペットボトルにも使われる。"},{"id":"p5626b4b4","q":"日本で開発された最初の合成繊維で、適度な吸湿性をもつものはどれか。","a":"ビニロン","w":["ナイロン66","アラミド繊維","ポリエチレンテレフタラート","アクリル繊維"],"e":"ビニロンは日本初の国産合成繊維。−OHが一部残っているので吸湿性がある。ナイロン66はカロザースの発明。"},{"id":"p972f9b26","q":"羊毛に似た風合いで、セーターなどに使われる合成繊維はどれか。","a":"アクリル繊維","w":["ナイロン66","アラミド繊維","ポリエチレンテレフタラート","ビニロン"],"e":"アクリル繊維は羊毛に似た風合いで、セーターなどに使われる。ナイロン66は絹に似せてつくられた。"},{"id":"p47f8e1c5","q":"ポリビニルアルコールをそのまま繊維にできない理由はどれか。","a":"水に溶けてしまうから","w":["燃えやすいから","かたすぎるから","重合度が小さいから"],"e":"ポリビニルアルコールは−OHが多く水に溶けてしまうので、そのままでは繊維にできない。アセタール化で−OHを減らして水に溶けにくくする。"},{"id":"pdc66fbf9","q":"ポリビニルアルコールをホルムアルデヒドで処理する操作を何というか。","a":"アセタール化","w":["けん化","加硫","エステル化","スルホン化"],"e":"ポリビニルアルコールの−OHをホルムアルデヒドで処理する操作はアセタール化。けん化はポリ酢酸ビニル→ポリビニルアルコール、加硫はゴムに硫黄を加える操作。"},{"id":"p144d398f","q":"ε-カプロラクタムのように、環状の単量体が環を開きながら次々と結合する重合を何というか。","a":"開環重合","w":["付加重合","縮合重合","付加縮合","共重合"],"e":"環状の単量体が環を開きながら結合する重合は開環重合（例：ε-カプロラクタム→ナイロン6）。付加重合はC=Cが開く、縮合重合は水などがとれる。"},{"id":"p78193290","q":"ナイロン6は何という重合でつくられるか。","a":"開環重合","w":["付加重合","縮合重合","付加縮合","共重合"],"e":"ナイロン6はε-カプロラクタムの環が開いてつながる開環重合。ナイロン66は縮合重合。"},{"id":"p609bb0dd","q":"ナイロン66は何という重合でつくられるか。","a":"縮合重合","w":["付加重合","開環重合","付加縮合","共重合"],"e":"ナイロン66は−COOHと−NH₂から水がとれてアミド結合ができる縮合重合。ナイロン6は開環重合。"},{"id":"p2372f819","q":"ポリエチレンテレフタラートは何という重合でつくられるか。","a":"縮合重合","w":["付加重合","開環重合","付加縮合","共重合"],"e":"PETは−COOHと−OHから水がとれてエステル結合ができる縮合重合。"},{"id":"pcab74a27","q":"アクリル繊維は何という重合でつくられるか。","a":"付加重合","w":["縮合重合","開環重合","付加縮合","共重合"],"e":"アクリル繊維はアクリロニトリルのC=Cが開いてつながる付加重合。"},{"id":"p5d74eded","q":"フェノール樹脂は何という重合でつくられるか。","a":"付加縮合","w":["付加重合","縮合重合","開環重合","共重合"],"e":"フェノール樹脂は、ホルムアルデヒドの付加と縮合（脱水）をくり返す付加縮合でできる。"},{"id":"p5a039666","q":"スチレン-ブタジエンゴムは何という重合でつくられるか。","a":"共重合","w":["付加重合","縮合重合","開環重合","付加縮合"],"e":"SBRはスチレンと1,3-ブタジエンの2種類をまぜて重合する共重合でできる。"},{"id":"pbea3dd5b","q":"アクリロニトリル-ブタジエンゴム(NBR)は何という重合でつくられるか。","a":"共重合","w":["付加重合","縮合重合","開環重合","付加縮合"],"e":"NBRはアクリロニトリルと1,3-ブタジエンの2種類をまぜて重合する共重合でできる。"},{"id":"peba41fe7","q":"開環重合でつくられる高分子をすべて選べ。","a":"ナイロン6","w":["ナイロン66","ポリエチレンテレフタラート","ポリエチレン","フェノール樹脂"],"e":"開環重合でできるのはナイロン6（ε-カプロラクタム）。ナイロン66・PETは縮合重合、ポリエチレンは付加重合、フェノール樹脂は付加縮合。"},{"id":"p76332bd2","q":"縮合重合でつくられる高分子をすべて選べ。","a":"ナイロン66・ポリエチレンテレフタラート・アラミド繊維","w":["ナイロン6","ポリスチレン","アクリル繊維"],"e":"ナイロン66・PET・アラミド繊維は縮合重合。ナイロン6は開環重合、ポリスチレン・アクリル繊維は付加重合。"},{"id":"p040660a8","q":"共重合でつくられる高分子をすべて選べ。","a":"スチレン-ブタジエンゴム(SBR)・アクリロニトリル-ブタジエンゴム(NBR)","w":["ブタジエンゴム(BR)","クロロプレンゴム(CR)","ナイロン6"],"e":"SBR・NBRは2種類の単量体の共重合。BR・CRは1種類の単量体の付加重合、ナイロン6は開環重合。"},{"id":"p4cb7c1ac","q":"付加重合でつくられる高分子をすべて選べ。","a":"アクリル繊維・ポリ塩化ビニル・ポリスチレン","w":["ナイロン6","ナイロン66","尿素樹脂"],"e":"アクリル繊維・ポリ塩化ビニル・ポリスチレンはC=Cをもつ単量体の付加重合。ナイロン6は開環重合、ナイロン66は縮合重合、尿素樹脂は付加縮合。"}]},{"name":"No.15 合成樹脂と機能性高分子","items":[{"id":"p68e361fd","q":"加熱するとやわらかくなり、冷やすと再び硬くなる樹脂を何というか。","a":"熱可塑性樹脂","w":["熱硬化性樹脂"],"e":"加熱するとやわらかくなり、冷やすと硬くなるのは熱可塑性樹脂（鎖状構造）。熱硬化性樹脂は加熱すると縮合が進んでより硬くなる。"},{"id":"p64880df7","q":"熱硬化性樹脂の分子の構造はどれか。","a":"立体網目構造","w":["鎖状構造","らせん構造","平面構造"],"e":"熱硬化性樹脂は立体網目構造なので、加熱してもやわらかくならない。熱可塑性樹脂は鎖状構造。"},{"id":"pa74ce660","q":"熱硬化性樹脂をすべて選べ。","a":"フェノール樹脂・尿素樹脂・メラミン樹脂","w":["ポリエチレン","アクリル樹脂","ポリスチレン"],"e":"フェノール樹脂・尿素樹脂・メラミン樹脂は付加縮合でできる熱硬化性樹脂。ポリエチレン・アクリル樹脂・ポリスチレンは付加重合でできる熱可塑性樹脂。"},{"id":"p47a10c48","q":"付加縮合でつくられる樹脂をすべて選べ。","a":"フェノール樹脂・尿素樹脂・メラミン樹脂","w":["ポリ塩化ビニル","ナイロン66","ポリエチレンテレフタラート"],"e":"フェノール樹脂・尿素樹脂・メラミン樹脂はホルムアルデヒドとの付加縮合でできる。ポリ塩化ビニルは付加重合、ナイロン66・PETは縮合重合。"},{"id":"peb85fbc1","q":"「ポリ袋や包装用フィルム」に使われる樹脂はどれか。","a":"ポリエチレン","w":["ナイロン66","メラミン樹脂","ポリ塩化ビニル","アクリル樹脂"],"e":"ポリエチレンはポリ袋や包装用フィルムに使う。ポリ塩化ビニルは水道管、メラミン樹脂は食器、アクリル樹脂は有機ガラス。"},{"id":"pc0529147","q":"「燃えにくく、上下水道管や電線の被覆」に使われる樹脂はどれか。","a":"ポリ塩化ビニル","w":["フェノール樹脂","ポリエチレン","アラミド繊維","尿素樹脂"],"e":"ポリ塩化ビニルはClを含み燃えにくく、水道管や電線の被覆に使う。フェノール樹脂は配電盤、尿素樹脂はボタン。"},{"id":"p0cf410bf","q":"「発泡させて断熱材や食品トレー」に使われる樹脂はどれか。","a":"ポリスチレン","w":["メラミン樹脂","ポリ酢酸ビニル","高吸水性樹脂","ビニロン"],"e":"ポリスチレンは発泡させて断熱材や食品トレーに使う（発泡スチロール）。"},{"id":"pb68f3cda","q":"「透明度が高く、有機ガラスや水槽」に使われる樹脂はどれか。","a":"アクリル樹脂(ポリメタクリル酸メチル)","w":["尿素樹脂","ポリエチレンテレフタラート","フェノール樹脂","ポリスチレン"],"e":"アクリル樹脂（ポリメタクリル酸メチル）は透明度が高く、有機ガラスや水槽に使う。"},{"id":"p97eb946d","q":"「接着剤やチューインガム」に使われる樹脂はどれか。","a":"ポリ酢酸ビニル","w":["メラミン樹脂","ナイロン6","陽イオン交換樹脂","ポリ塩化ビニル"],"e":"ポリ酢酸ビニルは接着剤やチューインガムに使う。メラミン樹脂は食器、ポリ塩化ビニルは水道管。"},{"id":"p20efad24","q":"「電気絶縁性が高く、配電盤やプリント基板」に使われる樹脂はどれか。","a":"フェノール樹脂","w":["尿素樹脂","ポリエチレン","アクリル樹脂","感光性樹脂"],"e":"フェノール樹脂は電気絶縁性が高く、配電盤やプリント基板に使う。尿素樹脂はボタン、アクリル樹脂は有機ガラス。"},{"id":"p2aab34dc","q":"「着色しやすく、ボタンや電気器具」に使われる樹脂はどれか。","a":"尿素樹脂","w":["メラミン樹脂","ポリスチレン","フェノール樹脂","アラミド繊維"],"e":"尿素樹脂は着色しやすく、ボタンや電気器具に使う。メラミン樹脂は食器、フェノール樹脂は配電盤。"},{"id":"p9127b0a2","q":"「硬くて傷がつきにくく、食器や化粧板」に使われる樹脂はどれか。","a":"メラミン樹脂","w":["尿素樹脂","ポリプロピレン","フェノール樹脂","ビニロン"],"e":"メラミン樹脂は強度・硬度が高く、食器や化粧板に使う。尿素樹脂はボタン、フェノール樹脂は配電盤。"},{"id":"p0fb9c5b2","q":"ベークランドが発明した世界初の合成樹脂はどれか。","a":"フェノール樹脂","w":["尿素樹脂","メラミン樹脂","ポリエチレン","ナイロン66"],"e":"ベークランドが発明した世界初の合成樹脂はフェノール樹脂（ベークライト）。世界初の合成繊維はナイロン66。"},{"id":"p2ddb1657","q":"フェノール樹脂の合成で、酸触媒のときにできる中間体はどれか。","a":"ノボラック","w":["レゾール","ポリビニルアルコール","ラテックス"],"e":"フェノール樹脂の合成で、酸触媒ではノボラック、塩基触媒ではレゾールが中間体になる。"},{"id":"pc3eb8434","q":"フェノール樹脂の合成で、塩基触媒のときにできる中間体はどれか。","a":"レゾール","w":["ノボラック","ポリビニルアルコール","ラテックス"],"e":"塩基触媒ではレゾール、酸触媒ではノボラックが中間体になる。"},{"id":"pd8e0ce54","q":"ヨウ素を加える(ドーピング)と電気を通すようになる高分子はどれか。","a":"ポリアセチレン","w":["ナイロン66","フェノール樹脂","ポリエチレン","ビニロン"],"e":"ポリアセチレンにヨウ素を加える（ドーピング）と電気を通す。白川英樹博士が2000年にノーベル化学賞を受賞。"},{"id":"p02e21c5d","q":"スルホ基 −SO₃H を導入した樹脂はどれか。","a":"陽イオン交換樹脂","w":["陰イオン交換樹脂","高吸水性樹脂","感光性樹脂","生分解性高分子"],"e":"スルホ基−SO₃Hを導入したものは陽イオン交換樹脂（H⁺と陽イオンを交換する）。陰イオン交換樹脂はトリメチルアンモニウム基。"},{"id":"pd9e12636","q":"トリメチルアンモニウム基を導入した樹脂はどれか。","a":"陰イオン交換樹脂","w":["陽イオン交換樹脂","高吸水性樹脂","感光性樹脂","生分解性高分子"],"e":"トリメチルアンモニウム基（−N⁺(CH₃)₃）を導入したものは陰イオン交換樹脂（OH⁻と陰イオンを交換する）。陽イオン交換樹脂はスルホ基。"},{"id":"p39d60808","q":"紙おむつや土壌の保水剤に使われる樹脂はどれか。","a":"高吸水性樹脂","w":["陽イオン交換樹脂","陰イオン交換樹脂","感光性樹脂","生分解性高分子"],"e":"高吸水性樹脂（ポリアクリル酸ナトリウム）は、−COO⁻どうしの反発で網目が広がり水を取り込む。紙おむつや土壌の保水剤に使う。"},{"id":"p2d8dccb7","q":"光が当たると硬化し、プリント配線などに使われる樹脂はどれか。","a":"感光性樹脂","w":["陽イオン交換樹脂","陰イオン交換樹脂","高吸水性樹脂","生分解性高分子"],"e":"感光性樹脂は光で重合・架橋が進んで硬くなり、プリント配線などに使う（例：ポリビニル桂皮酸）。"},{"id":"p0fa7eab4","q":"微生物などにより最終的に二酸化炭素と水に分解される高分子はどれか。","a":"生分解性高分子","w":["陽イオン交換樹脂","陰イオン交換樹脂","高吸水性樹脂","感光性樹脂"],"e":"生分解性高分子は微生物などで最終的にCO₂と水に分解される（例：ポリ乳酸、ポリグリコール酸）。手術用の縫合糸など医療分野で使う。"},{"id":"pa62ff80e","q":"陽イオン交換樹脂に塩化ナトリウム水溶液を通すと、流出する液は何か。","a":"塩酸","w":["水酸化ナトリウム水溶液","純水","塩化ナトリウム水溶液"],"e":"陽イオン交換樹脂はNa⁺をとってH⁺を出すので、NaCl水溶液は塩酸になって流出する。"},{"id":"p99178c29","q":"陰イオン交換樹脂(OH⁻型)に塩化ナトリウム水溶液を通すと、流出する液は何か。","a":"水酸化ナトリウム水溶液","w":["塩酸","純水","塩化ナトリウム水溶液"],"e":"陰イオン交換樹脂（OH⁻型）はCl⁻をとってOH⁻を出すので、NaCl水溶液はNaOH水溶液になって流出する。"},{"id":"p794416b6","q":"使い終わった陽イオン交換樹脂を再生するときに通すものはどれか。","a":"塩酸(強酸)","w":["水酸化ナトリウム水溶液","純水","塩化ナトリウム水溶液"],"e":"イオン交換は可逆反応なので、使った陽イオン交換樹脂に塩酸（強酸）を通すと、Na⁺がH⁺に戻る（再生）。"}]},{"name":"No.16 ゴムのモノマー","items":[{"id":"p9c1ffb1e","q":"名称を答えよ。","a":"イソプレン","w":["1,3-ブタジエン","クロロプレン","プロピレン","スチレン"],"e":"CH₂=C(CH₃)−CH=CH₂でイソプレン（2位にCH₃、天然ゴム・IRの単量体）。1,3-ブタジエンはCH₃がない、クロロプレンはCH₃の代わりにCl。","img":"イソプレン.png"},{"id":"pcbaaabc4","q":"名称を答えよ。","a":"1,3-ブタジエン","w":["イソプレン","クロロプレン","アセチレン","エチレン"],"e":"CH₂=CH−CH=CH₂で1,3-ブタジエン（BRの単量体、SBR・NBRの原料）。イソプレンは2位にCH₃、クロロプレンは2位にCl。","img":"1,3-ブタジエン.png"},{"id":"p92a51a19","q":"名称を答えよ。","a":"クロロプレン","w":["イソプレン","1,3-ブタジエン","塩化ビニル","塩化ビニリデン"],"e":"CH₂=CCl−CH=CH₂でクロロプレン（CRの単量体）。イソプレンは2位がCH₃、1,3-ブタジエンは何もつかない、塩化ビニルは二重結合が1つ。","img":"クロロプレン.png"},{"id":"pfb78be1f","q":"この構造の高分子は何か。","a":"天然ゴム(生ゴム)","w":["グタペルカ","ブタジエンゴム","クロロプレンゴム"],"e":"シス形のポリイソプレンなので天然ゴム（生ゴム）。トランス形ならグタペルカ。ブタジエンゴムはCH₃がない、クロロプレンゴムはCH₃の代わりにCl。","img":"シス形ポリイソプレン(天然ゴム).png"},{"id":"pf9496a72","q":"この構造の高分子は何か。","a":"グタペルカ","w":["天然ゴム(生ゴム)","ブタジエンゴム","クロロプレンゴム"],"e":"トランス形のポリイソプレンなのでグタペルカ（硬く弾性がない）。シス形なら天然ゴム。","img":"トランス形ポリイソプレン(グタペルカ).png"},{"id":"pcec5a748","q":"天然ゴムの単量体をすべて選べ。","a":"イソプレン","w":["1,3-ブタジエン","クロロプレン","スチレン","アクリロニトリル"],"e":"天然ゴムはポリイソプレンで、単量体はイソプレン（乾留するとイソプレンが得られる）。"},{"id":"peffb1730","q":"IRの単量体をすべて選べ。","a":"イソプレン","w":["1,3-ブタジエン","クロロプレン","スチレン","アクリロニトリル"],"e":"IR（イソプレンゴム）の単量体はイソプレン。"},{"id":"pb40b2fd4","q":"BRの単量体をすべて選べ。","a":"1,3-ブタジエン","w":["イソプレン","クロロプレン","スチレン","アクリロニトリル"],"e":"BR（ブタジエンゴム）の単量体は1,3-ブタジエン。"},{"id":"p19da8983","q":"CRの単量体をすべて選べ。","a":"クロロプレン","w":["イソプレン","1,3-ブタジエン","スチレン","アクリロニトリル"],"e":"CR（クロロプレンゴム）の単量体はクロロプレン。"},{"id":"p0f1d4204","q":"SBRの単量体をすべて選べ。","a":"スチレン・1,3-ブタジエン","w":["イソプレン","クロロプレン","アクリロニトリル"],"e":"SBR（スチレン-ブタジエンゴム）はスチレンと1,3-ブタジエンの共重合。"},{"id":"p311799cb","q":"NBRの単量体をすべて選べ。","a":"アクリロニトリル・1,3-ブタジエン","w":["イソプレン","クロロプレン","スチレン"],"e":"NBR（アクリロニトリル-ブタジエンゴム）はアクリロニトリルと1,3-ブタジエンの共重合。"}]},{"name":"No.17 ゴムの略称・性質・用途","items":[{"id":"p2a358efb","q":"イソプレンゴムの略称は何か。","a":"IR","w":["BR","CR","SBR","NBR"],"e":"イソプレンゴムはIR（Isoprene Rubber）。BRはブタジエン、CRはクロロプレン、SBRはスチレン-ブタジエン、NBRはアクリロニトリル-ブタジエン。"},{"id":"p638ab1d0","q":"ブタジエンゴムの略称は何か。","a":"BR","w":["IR","CR","SBR","NBR"],"e":"ブタジエンゴムはBR（Butadiene Rubber）。"},{"id":"p15b3976e","q":"クロロプレンゴムの略称は何か。","a":"CR","w":["IR","BR","SBR","NBR"],"e":"クロロプレンゴムはCR（Chloroprene Rubber）。"},{"id":"p6a43b4cf","q":"スチレン-ブタジエンゴムの略称は何か。","a":"SBR","w":["IR","BR","CR","NBR"],"e":"スチレン-ブタジエンゴムはSBR（Styrene-Butadiene Rubber）。"},{"id":"p9b927196","q":"アクリロニトリル-ブタジエンゴムの略称は何か。","a":"NBR","w":["IR","BR","CR","SBR"],"e":"アクリロニトリル-ブタジエンゴムはNBR（Nitrile-Butadiene Rubber）。"},{"id":"pff016a8c","q":"耐摩耗性・機械的強度が大きく、自動車タイヤに用いられる合成ゴムはどれか。","a":"SBR","w":["NBR","CR","BR","IR"],"e":"SBRは機械的強度が大きく、自動車タイヤに使う。NBRは耐油性、CRは難燃性。"},{"id":"pb96acf40","q":"耐油性が高く、石油ホースなどに用いられる合成ゴムはどれか。","a":"NBR","w":["SBR","CR","BR","IR"],"e":"NBRは−C≡Nの極性が大きく油となじまないので耐油性が高く、石油ホースに使う。SBRはタイヤ、CRは難燃性。"},{"id":"p092ce3c4","q":"難燃性・耐候性に優れる合成ゴムはどれか。","a":"CR","w":["SBR","NBR","BR","IR"],"e":"CRはClを含むので燃えにくく（難燃性）、耐候性にも優れる。SBRはタイヤ、NBRは耐油性。"},{"id":"p11e52cb0","q":"ゴムノキの樹皮に傷をつけると流れ出る乳液を何というか。","a":"ラテックス","w":["生ゴム","エボナイト","グタペルカ"],"e":"ゴムノキの樹皮から流れ出る乳液はラテックス。これを凝固・乾燥させたものが生ゴム。エボナイトは硫黄を多く加えた硬いゴム、グタペルカはトランス形のゴム。"},{"id":"p4e4a0b90","q":"生ゴムに硫黄を加えて加熱し、弾性を増す操作を何というか。","a":"加硫","w":["アセタール化","けん化","乾留"],"e":"生ゴムに硫黄を加えて加熱し、鎖の間に硫黄の橋（架橋）をかけて弾性を増す操作が加硫。アセタール化はビニロン、けん化はエステルの加水分解。"},{"id":"pde3f7869","q":"生ゴムに硫黄を30〜40%加えてできる、とても硬い物質は何か。","a":"エボナイト","w":["弾性ゴム","グタペルカ","ラテックス"],"e":"硫黄を30〜40％加えるとエボナイト（とても硬い）。数％なら弾性ゴム（輪ゴムなど）。"},{"id":"p49a4a53f","q":"天然ゴムが空気中で劣化する主な原因はどれか。","a":"二重結合が酸化されるから","w":["硫黄が抜けるから","水を吸収するから","加水分解されるから"],"e":"天然ゴムは構造中の二重結合が空気中の酸素で酸化されて劣化する。"}]},{"name":"No.18 酵素・再生繊維・半合成繊維","items":[{"id":"p194de76d","q":"酵素の主成分は何か。","a":"タンパク質","w":["糖","脂質","核酸"],"e":"酵素は主にタンパク質からなり、生体内の反応の触媒としてはたらく。"},{"id":"p8fae2afa","q":"酵素が特定の物質(基質)にしか作用しない性質を何というか。","a":"基質特異性","w":["最適温度","失活","変性"],"e":"酵素が特定の物質（基質）にしか作用しない性質を基質特異性という。基質と結合する部位を活性部位という。"},{"id":"pf607ef86","q":"高温で酵素のタンパク質が変性し、はたらかなくなることを何というか。","a":"失活","w":["基質特異性","加硫","けん化"],"e":"高温でタンパク質が変性し、酵素がはたらかなくなることを失活という。"},{"id":"pba671927","q":"一般的な酵素の最適温度はどれくらいか。","a":"30〜40℃","w":["0〜10℃","60〜70℃","90〜100℃"],"e":"酵素は通常30〜40℃で最もよくはたらく。高すぎると変性して失活する。"},{"id":"p430974f0","q":"胃液に含まれ、強い酸性(pH2付近)でよくはたらくタンパク質分解酵素はどれか。","a":"ペプシン","w":["トリプシン","アミラーゼ","リパーゼ","カタラーゼ"],"e":"ペプシンは胃液に含まれ、強い酸性（pH2付近）でよくはたらくタンパク質分解酵素。トリプシンはすい液、アミラーゼはデンプン、リパーゼは脂肪を分解する。"},{"id":"pde0950c2","q":"すい液に含まれるタンパク質分解酵素はどれか。","a":"トリプシン","w":["ペプシン","マルターゼ","カタラーゼ"],"e":"トリプシンはすい液に含まれるタンパク質分解酵素。ペプシンは胃液、カタラーゼは過酸化水素を分解する。"},{"id":"pff509fc8","q":"脂肪を脂肪酸とモノグリセリドに分解する酵素はどれか。","a":"リパーゼ","w":["アミラーゼ","ペプシン","カタラーゼ","トリプシン"],"e":"リパーゼは脂肪を脂肪酸とモノグリセリドに分解する。アミラーゼはデンプン、ペプシン・トリプシンはタンパク質を分解する。"},{"id":"p498bc3c8","q":"過酸化水素を酸素と水に分解する酵素はどれか。","a":"カタラーゼ","w":["リパーゼ","ペプシン","アミラーゼ","チマーゼ"],"e":"カタラーゼは過酸化水素を酸素と水に分解する酸化酵素（肝臓・血液に含まれる）。"},{"id":"pbe881258","q":"基質の濃度を大きくしていくと、酵素反応の速度はどうなるか。","a":"一定の値(最大反応速度)に近づく","w":["基質濃度に比例して大きくなり続ける","小さくなる","変わらない"],"e":"酵素−基質複合体の濃度は酵素の濃度を超えられないので、基質を増やしても反応速度は一定の値（最大反応速度）に近づく。"},{"id":"pca266235","q":"再生繊維をすべて選べ。","a":"ビスコースレーヨン・銅アンモニアレーヨン","w":["アセテート","ナイロン66","ビニロン"],"e":"セルロースをいったん溶かして繊維として再生させたものが再生繊維（ビスコースレーヨン・銅アンモニアレーヨン）。アセテートは半合成繊維、ナイロン66・ビニロンは合成繊維。"},{"id":"pd1b9562f","q":"半合成繊維をすべて選べ。","a":"アセテート","w":["ビスコースレーヨン","銅アンモニアレーヨン","ナイロン66"],"e":"セルロースの−OHを別の基に変えたものが半合成繊維（アセテート）。レーヨンは再生繊維、ナイロン66は合成繊維。"},{"id":"p12780aac","q":"セルロースをシュバイツァー試薬に溶かし、希硫酸中に押し出してつくる繊維はどれか。","a":"銅アンモニアレーヨン","w":["ビスコースレーヨン","アセテート","トリニトロセルロース"],"e":"シュバイツァー試薬に溶かして希硫酸中に押し出すのは銅アンモニアレーヨン（キュプラ）。ビスコースレーヨンはNaOHと二硫化炭素を使う。"},{"id":"p3bc43d94","q":"シュバイツァー試薬はどのようにつくるか。","a":"水酸化銅(Ⅱ)を濃アンモニア水に溶かす","w":["硫酸銅(Ⅱ)を希硫酸に溶かす","酸化銅(Ⅰ)を水に溶かす","銅を濃硝酸に溶かす"],"e":"シュバイツァー試薬は水酸化銅(Ⅱ)を濃アンモニア水に溶かしたもの（[Cu(NH₃)₄]²⁺を含む）。"},{"id":"p3d695fb2","q":"セルロースを濃NaOH・二硫化炭素で処理してつくったコロイド溶液を、希硫酸中に押し出してつくる繊維はどれか。","a":"ビスコースレーヨン","w":["銅アンモニアレーヨン","アセテート","トリニトロセルロース"],"e":"濃NaOH・二硫化炭素で処理してできたコロイド溶液（ビスコース）を希硫酸中に押し出すのがビスコースレーヨン。銅アンモニアレーヨンはシュバイツァー試薬を使う。"},{"id":"p3a156d55","q":"セルロースを無水酢酸でアセチル化し、一部を加水分解してつくる繊維はどれか。","a":"アセテート","w":["ビスコースレーヨン","銅アンモニアレーヨン","トリニトロセルロース"],"e":"セルロースをアセチル化し、一部を加水分解して溶媒に溶かしてつくるのがアセテート（半合成繊維）。"},{"id":"pf60e083b","q":"セルロースに混酸(濃硝酸＋濃硫酸)を作用させてできる、激しく燃える物質はどれか。","a":"トリニトロセルロース","w":["ビスコースレーヨン","銅アンモニアレーヨン","アセテート"],"e":"セルロースに混酸を作用させ、−OHを硝酸エステルにしたものがトリニトロセルロース（硝化綿、激しく燃える）。"}]},{"name":"No.19 核酸","items":[{"id":"p4ab75dc1","q":"DNAの正式名称はどれか。","a":"デオキシリボ核酸","w":["リボ核酸","アデノシン三リン酸","デオキシリボース"],"e":"DNAはデオキシリボ核酸（DeoxyriboNucleic Acid）。RNAはリボ核酸、デオキシリボースはDNAに含まれる糖の名前。"},{"id":"pc273d346","q":"核酸の単量体(モノマー)にあたるものを何というか。","a":"ヌクレオチド","w":["アミノ酸","単糖","ヌクレアーゼ","ペプチド"],"e":"核酸はヌクレオチドが縮合重合したポリヌクレオチド。アミノ酸はタンパク質、単糖は多糖の単量体。"},{"id":"p3f73765b","q":"ヌクレオチドを構成するものをすべて選べ。","a":"糖・塩基・リン酸","w":["アミノ酸","脂肪酸"],"e":"ヌクレオチドは糖（五炭糖）・塩基・リン酸からなる。アミノ酸・脂肪酸は含まない。"},{"id":"p71787599","q":"DNAに含まれる糖はどれか。","a":"デオキシリボース","w":["リボース","グルコース","フルクトース"],"e":"DNAの糖はデオキシリボース（リボースのOHが1つHになったもの）。RNAの糖はリボース。"},{"id":"pe2775c81","q":"RNAに含まれる糖はどれか。","a":"リボース","w":["デオキシリボース","グルコース","フルクトース"],"e":"RNAの糖はリボース。DNAの糖はデオキシリボース。"},{"id":"p0223740c","q":"DNAに含まれる塩基をすべて選べ。","a":"アデニン・グアニン・シトシン・チミン","w":["ウラシル"],"e":"DNAの塩基はA・G・C・T（チミン）。ウラシルはRNAにだけ含まれる。"},{"id":"p71aa1fe8","q":"RNAに含まれる塩基をすべて選べ。","a":"アデニン・グアニン・シトシン・ウラシル","w":["チミン"],"e":"RNAの塩基はA・G・C・U（ウラシル）。チミンはDNAにだけ含まれる。"},{"id":"pbbb99632","q":"DNAではアデニン(A)はどの塩基と対をつくるか。","a":"チミン","w":["グアニン","シトシン","ウラシル"],"e":"DNAではアデニン（A）はチミン（T）と、グアニン（G）はシトシン（C）と対をつくる。ウラシルはRNAの塩基。"},{"id":"pcf5bd13c","q":"DNAではグアニン(G)はどの塩基と対をつくるか。","a":"シトシン","w":["アデニン","チミン","ウラシル"],"e":"DNAではグアニン（G）はシトシン（C）と、アデニン（A）はチミン（T）と対をつくる。"},{"id":"p13bde484","q":"G−C間の水素結合の数はいくつか。","a":"3本","w":["1本","2本","4本"],"e":"G−C間の水素結合は3本、A−T間は2本。そのためG−Cの方がやや強い。"},{"id":"pd84c8bb6","q":"A−T間の水素結合の数はいくつか。","a":"2本","w":["1本","3本","4本"],"e":"A−T間の水素結合は2本、G−C間は3本。"},{"id":"p077b5c32","q":"DNAの2本の鎖が塩基どうしの水素結合でつくる構造はどれか。","a":"二重らせん構造","w":["α-ヘリックス","β-シート","立体網目構造"],"e":"DNAは2本の鎖が塩基どうしの水素結合でつながり、二重らせん構造をとる。α-ヘリックス・β-シートはタンパク質の二次構造。"},{"id":"pd530e045","q":"プリン塩基をすべて選べ。","a":"アデニン・グアニン","w":["シトシン","チミン","ウラシル"],"e":"アデニン・グアニンはプリン塩基（環が2つ）。シトシン・チミン・ウラシルはピリミジン塩基（環が1つ）。"},{"id":"p8dd6cd58","q":"DNAの塩基配列を写し取ってmRNAをつくる過程を何というか。","a":"転写","w":["翻訳","複製","変性"],"e":"DNAの塩基配列を写し取ってmRNAをつくる過程が転写。mRNAをもとにタンパク質をつくるのが翻訳。"},{"id":"p7008f74c","q":"mRNAの塩基配列にしたがってアミノ酸をつなぎ、タンパク質をつくる過程を何というか。","a":"翻訳","w":["転写","複製","加水分解"],"e":"mRNAの塩基配列にしたがってアミノ酸をつなぐ過程が翻訳。DNAからmRNAをつくるのが転写。"},{"id":"p91c643e4","q":"翻訳のときにアミノ酸を運んでくるRNAはどれか。","a":"tRNA","w":["mRNA","rRNA","DNA"],"e":"翻訳ではtRNA（運搬RNA）がアミノ酸を運んでくる。mRNAは塩基配列の情報を運ぶRNA。"}]}]}];
